INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-468vp', '468vp', 'Injustiça ambiental e saúde no Brasil: o Mapa de Conflitos', NULL, '["Marcelo Firpo Porto","Tania Pacheco","Jean Pierre Leroy"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresentação O Mapa dos Conflitos Ambientais no Estado do Rio de JaneiroO debate sobre problemas ambientais sob a ótica das desigualdades sociais, políticas, econômicas e culturais e, portanto, das injustiças presentes no modelo hegemônico de sociedade já era fundamental e estruturante em entidades como a Fase, mais especificamente no projeto BSD.Com a criação da rede, pode-se dizer que o projeto acumulou mais força política, aglutinando diferentes sujeitos e impondo novos desafios à sua prática.Antes da criação da RBJA, o debate sobre os conflitos ambientais no país já tinha sido realizado por iniciativas de várias entidades e grupos universitários, como o Instituto Brasileiro de Análises Sociais e Econômicas (Ibase), a Central Única dos Trabalhadores do Rio de Janeiro (CUT-RJ), pesquisadores do Instituto de Pesquisa e Planejamento Urbano e Regional (Ippur) e do Museu Nacional da Universidade Federal do Rio de Janeiro (UFRJ), da UFF, além de outros grupos acadêmicos ligados às ciências sociais e à saúde coletiva, como a Fiocruz (Herculano, Porto & Freitas, 2000; Ibase/CUT-RJ/Ippur/UFRJ, 2000).Os problemas ambientais já eram tema obrigatório das discussões inseridas no projeto BDS/Fase, e, com a criação da rede, novos parceiros fomentaram a ideia de se construir um Mapa de Conflitos Ambientais do Rio de Janeiro (Acselrad, Herculano & Pádua, 2004).Com o vigor da recém-criada RBJA, em novembro de 2002 o BSD/Fase promoveu uma oficina para se pensar numa forma de viabilizar essa estratégia de luta em torno dos conflitos e movimentos por justiça ambiental, partindo do levantamento do "perfil do conhecimento disponível, das pesquisas em andamento e dos esforços dos pesquisadores" que se dedicavam, "no âmbito das mais diversas instituições universitárias e de pesquisa, ao estudo de conflitos ambientais no Estado do Rio de Janeiro", conforme consta da apresentação do CD-ROM "Mapa dos Conflitos Ambientais no Estado do Rio de Janeiro 2002-2005".Como consequência da oficina, em janeiro de 2004 o projeto BSD/Fase e o laboratório Estado, Trabalho, Território e Natureza (Ettern/Ippur/UFJR) lançavam o Mapa dos Conflitos Ambientais do Estado do Rio de Janeiro 1992-2002.Com o apoio da Secretaria de Estado de Meio Ambiente e Desenvolvimento Urbano do Rio de Janeiro e com recursos provenientes de um Termo de Ajuste de Conduta da Petrobras, após o desastre ambiental ocorrido na baía de Guanabara em 2000, o mapa foi produzido em CD-ROM no qual se compilaram 251 casos cujos registros foram colhidos de documentos da Fundação Estadual de Engenharia do Meio Ambiente (Feema) e dos ministérios públicos estadual e federal.Deles, 183 diziam respeito a atividades 21 industriais; 48, à ausência de saneamento; dez conjugavam essas duas questões; e outros dez envolviam temas diversos.Dois anos mais tarde, em 2006, os mesmos parceiros lançaram um novo Mapa dos Conflitos Ambientais no Estado do Rio de Janeiro, também em CD-ROM, totalizando, assim, 480 conflitos ocorridos entre 2002 e 2005, aos quais foram ainda acrescentados estudos analíticos dos casos.Às fontes iniciais -Feema e os ministérios públicos estadual e federal -se somariam também casos registrados pelo Departamento de Recursos Minerais do Estado do Rio de Janeiro, pela Secretaria Municipal de Meio Ambiente do Rio de Janeiro e pela Secretaria de Urbanismo e Meio Ambiente de Mesquita.2Os conflitos, selecionados ao longo de trinta meses, relativos ao período de 2002 a 2005, foram georreferenciados em 68 municípios e sistematizados em 18 classificações específicas: mineração; disposição não licenciada de resíduos industriais; depósito licenciado de resíduos industriais; armazenamento temporário de resíduos industriais; poluição atmosférica; poluição de corpo hídrico; poluição do solo; poluição sonora; gasodutos, oleodutos, estações rádio-base e linhas de transmissão; vazadouros de lixo; lançamento de esgoto em corpo hídrico; acesso à água potável; apropriação de corpo hídrico; deslocamento compulsório de assentamento humano; ocupações irregulares; moradia de risco; comprometimento da pesca; e futuros empreendimentos (Acselrad, 2004).Ainda de acordo com as informações apresentadas no CD-ROM, Os casos foram organizados por município de ocorrência do evento denunciado e classificados em grandes categorias, segundo o tipo de problema ambiental a que estiveram associados, a saber: conflitos associados a atividades industriais -poluição industrial da água, do ar e do solo, mineração irregular e disposição irregular de resíduos industriais; conflitos associados à falta de saneamento, localização e operação de lixões e aterros sanitários; conflitos associados simultaneamente a atividades industriais e à falta de saneamento; e outros. O Mapa de Conflitos Causados por Racismo Ambiental no BrasilEnquanto se produzia o segundo CD-ROM sobre os conflitos do estado do Rio de Janeiro, o debate acerca da necessidade de criação de instrumentos de registros e publicização dos casos de injustiça ambiental no país começaram a se intensificar dentro da própria RBJA, presente nas discussões coletivas nos A Estrutura do LivroComo este livro tem como tema o Mapa de Conflitos, mas não trata apenas dele, houve uma preocupação inicial em se explicar a forma como se chegou ao mapa.Essa explicação está no capítulo 1, em que se apresenta a metodologia utilizada e se resumem os casos presentes no mapa.Já a 29 partir do capítulo seguinte, o livro toma outro caminho: os resultados e as conclusões que podemos colher do mapa passam a ser objeto de diferentes análises específicas, servindo de base para questionamentos, observações críticas e sugestões sobre alternativas de enfrentamento das causas geradoras dos conflitos em pauta.Em última instância, o que se encontra em jogo é a crítica do modelo hegemônico de desenvolvimento que impõe interesses de curto prazo dos grupos mais poderosos às populações atingidas.No capítulo 2, adentra-se num um terreno pouco discutido nos meios acadêmicos, mas que o Mapa de Conflitos nos desafia a encarar, dado o caráter de insofismável prevalência que assume no conjunto da pesquisa: o racismo ambiental.Nele se analisa a forma como o capital utiliza o racismo e o preconceito para expulsar povos indígenas, quilombolas e comunidade tradicionais de seus espaços originários, de suas culturas e tradições, no campo, ao passo que, nas cidades, pobreza e negritude predominam nos embates com a especulação imobiliária e as indústrias poluentes.Grande parte dessas personagens é retomada no capítulo 3, em que os conflitos são objeto de análise sob um enfoque complementar especializado: o da territorialidade.Trabalhadores rurais também são mencionados, mas o protagonismo do estudo recai novamente sobre os povos originários e as comunidades tradicionais, com seus embates pelo direito a um território que, para eles, tem um significado que até mesmo os operadores do sistema de Justiça enfrentam dificuldade de compreender.No capítulo 4, discutem-se as injustiças ambientais nos espaços das cidades, campos e florestas.Trata-se de uma questão de grande complexidade, já que tais espaços são influenciados por inúmeras dinâmicas que tanto os diferenciam como os interconectam.Por exemplo, no campo destacamos a expansão do agronegócio, dos monocultivos e o uso intensivo dos agrotóxicos, mas isso também influencia a migração campo-cidade e o conjunto da população que consome alimentos contaminados.Nas cidades, a perversa combinação das desigualdades socioespaciais com empreendimentos, como complexos portuários e indústrias perigosas, intensifica a formação das zonas de sacrifício.Porém, tais empreendimentos também avançam sobre os espaços onde vivem populações indígenas, quilombolas e camponesas.Abordam-se, nos capítulos 5 e 6, duas forças motrizes de grande relevância para a geração de conflitos ambientais no contexto brasileiro: a primeira trata da mineração e da siderurgia, e a segunda da produção de energia.A mineração é uma atividade intensiva em r', '["environmental injustice","environmental conflicts","Rio de Janeiro","social movements","health and environment","social inequality","collective health","environmental awareness campaigns","environmental education in higher education","environmental education in the workplace"]', '10.7476/9788575415764', '9788575415764', 'https://books.scielo.org/id/468vp', 'https://books.scielo.org/id/468vp/pdf/porto-9788575415764.pdf', NULL, 'https://books.scielo.org/id/468vp/cover/cover_thumbnail.jpeg', NULL, 69, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-46trp', '46trp', 'Conhecimento em rede: desenvolvimento, cooperação e integração regional em território de fronteira – Rede CIDIR: 10 anos', NULL, '["Edemar Rotta","Ivann Carlos Lago","Andréia Fröhlich JUSTEN","Micheli dos Santos"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra reúne 33 textos, organizados em sete capítulos: I- Comércio internacional e relações de fronteira; II- Integração regional; III- Desenvolvimento regional; IV- Desenvolvimento e meio ambiente; V- Desenvolvimento e novas tecnologias produtivas e sociais; VI- Desenvolvimento e participação social; VII- Desenvolvimento e políticas públicas. A obra resulta de seleção dos trabalhos melhor avaliados pelo Comitê Internacional da Rede CIDIR no “VIII Simpósio Iberoamericano de Cooperação para o Desenvolvimento e a Integração Regional”. Trata-se de evento internacional itinerante realizado pelas instituições da Rede, alternando edições no Brasil, na Argentina e no Paraguai. Os sete capítulos traduzem os temas prioritários de discussão, reflexão e produção do conhecimento que perpassam as atividades desenvolvidas pela Rede CIDIR que, em 2017, comemorou seus dez anos de funcionamento. Como Rede de pesquisa, ela reúne 22 Instituições de Ensino Superior (IES) do Brasil, Paraguai, Uruguai, México, da Argentina, Venezuela e Espanha, com foco prioritário de integração e socialização do conhecimento nas áreas de Ciências Humanas, Sociais e Sociais Aplicadas.', '["borderlands","regional integration","regional development","environment and development","social participation","public policy","knowledge networks","Ibero-American cooperation","higher education institutions"]', '10.7476/9786586545432', '9786586545432', 'https://books.scielo.org/id/46trp', 'https://books.scielo.org/id/46trp/pdf/rotta-9786586545432.pdf', NULL, 'https://books.scielo.org/id/46trp/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
