publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-479cy', '479cy', 'Discusiones contemporáneas sobre derechos humanos en el marco de la globalización', NULL, '["Torres Villarreal, María Lucía","Paola Marcela Iregui Parra"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La Universidad del Rosario, por conducto de su Observatorio Legislativo y del Grupo de Investigación en Derechos Humanos de la Facultad de Jurisprudencia, se asoció con la Fundación Hanns Seidel para organizar el Foro “Protección internacional de los derechos humanos en un marco de justicia transicional”. El objetivo principal del foro fue crear un espacio para hacer una reflexión, desde diversas perspectivas, alrededor de las discusiones actuales sobre derechos humanos y su protección internacional, en especial, por la coyuntura que vive nuestro país con ocasión del proceso de paz iniciado en 2012 y un eventual escenario de posconflicto derivado de éste, en el marco del derecho internacional de los derechos humanos y de la mano de expertos nacionales e internacionales en la materia.', '["international human rights protection","transitional justice","post-conflict","peace process","Colombian peace process","international human rights law"]', '10.7476/9789587386714', '9789587386714', 'https://books.scielo.org/id/479cy', 'https://books.scielo.org/id/479cy/pdf/torres-9789587386714.pdf', NULL, 'https://books.scielo.org/id/479cy/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47hv3', '47hv3', 'Tecendo histórias: espaço, política e identidade', NULL, '["Antônio Luigi Negro","Evergton Sales Souza","Lígia Bellini"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O principal objetivo do livro é o de aprofundar o debate historiográfico sobre métodos e abordagens relativos às linhas de pesquisa dos programas de pós-graduação em História das regiões norte, nordeste e centro-oeste do país, contemplando fenômenos culturais variados, propiciando o intercâmbio acadêmico entre centros de pesquisa e pesquisadores das regiões envolvidas. Os trabalhos reunidos foram originalmente apresentados no Seminário de Pesquisa dos Programas de Pós-Graduação em História das Regiões Norte, Nordeste e Centro-Oeste, que ocorreu em novembro de 2008, na cidade de Salvador.', '["historiography","historical method","regional history","Northern Brazil","Northeast Brazil","Central-West Brazil","spatial politics","identity","academic exchange"]', '10.7476/9788523212346', '9788523206451', 'https://books.scielo.org/id/47hv3', NULL, NULL, 'https://books.scielo.org/id/47hv3/cover/cover_thumbnail.jpeg', 310, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47nd4', '47nd4', 'Temas atuais de hermenêutica jurídica', NULL, '["Homero Chiaraba Gouveia","Guaraí Pereira Machado"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra reúne textos que exploram os múltiplos caminhos da hermenêutica jurídica, em diálogo com a filosofia, literatura, sociologia, história e crítica racial. Desafiando a visão tradicional do Direito, os autores evidenciam sua natureza não neutra e sua constante interseção com disputas políticas, culturais e históricas. O livro convida o leitor a repensar a prática jurídica a partir de perspectivas plurais e comprometidas com a transformação social.', '["legal hermeneutics","nature of law","philosophy and law","law and literature","sociology of law","law and history","legal practice","social change"]', '10.7476/9788574556345', '9788574556093', 'https://books.scielo.org/id/47nd4', NULL, NULL, 'https://books.scielo.org/id/47nd4/cover/cover_thumbnail.jpeg', 88, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47r85', '47r85', 'Perfil do leitor colonial', NULL, '["Jorge de Souza Araujo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é um instrumento importante para pensar a história nacional. O autor nos apresenta um detalhado trabalho de campo com pesquisas nos arquivos públicos dos Estados da Bahia, Rio Grande do Sul, Mato Grosso, na Casa Setecentista de Mariana, nos arquivos públicos das cidades de Ouro Preto e São João del-Rei (MG). O seu propósito foi preparar um panorama dos livros encontrados no Brasil Colônia para, a partir da amostragem obtida, elaborar um perfil do leitor colonial.', '["reading practices","book ownership","colonial Brazil","Ouro Preto","São João del-Rei","Bahia","Rio Grande do Sul","Mato Grosso","public archives"]', '10.7476/9786586213089', '9788574555225', 'https://books.scielo.org/id/47r85', NULL, NULL, 'https://books.scielo.org/id/47r85/cover/cover_thumbnail.jpeg', 463, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47wcj', '47wcj', 'Meu encontro com os outros: memórias de José de Albuquerque, pioneiro da sexologia no Brasil', NULL, '["Sério Carrara","Marcos Vinícius de Freitas Carvalho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A sexualidade como função fisiológica e o desejo sexual como necessidade orgânica primária. A educação sexual – para homens e mulheres – como estratégia para solucionar não só o problema das doenças venéreas, mas outros como a desarmonia conjugal e as perversões sexuais. A legitimação e institucionalização da andrologia, a ciência do homem. A crítica à abstinência sexual socialmente imposta às mulheres solteiras e viúvas. Essas eram algumas das ideias defendidas pelo autoproclamado sexólogo e andrologista brasileiro José de Albuquerque, médico que, embora tenha enfrentado tabus, levantado polêmicas e causado rebuliço na elite carioca nos anos 1930, ficou esquecido ao longo das décadas seguintes. Mas agora esse importante personagem da história da sexualidade no Brasil volta à cena com a publicação de sua autobiografia até então inédita. “Enfim, para além das peripécias de uma vida bastante agitada e de uma singular trajetória profissional, a autobiografia desvela aspectos interessantíssimos do desenvolvimento das ciências médicas no Rio de Janeiro do entreguerras. Nela, aparecem seus principais personagens, a vida em suas escolas e o universo de sua prática”, afirmam os organizadores. “Sua leitura na segunda década dos anos 2000 permite colocar em uma nova perspectiva a própria história da sexualidade no Brasil, um campo que hoje, como nos anos 1930, continua tensionado por inúmeros dilemas, conflitos e impasses”.', '["sexology","andrology","history of sexuality","sex education","sexually transmitted infections","sexual abstinence","female sexuality","marital conflict","paraphilias","1930s"]', '10.7476/9788575415757', '9788575414736', 'https://books.scielo.org/id/47wcj', NULL, NULL, 'https://books.scielo.org/id/47wcj/cover/cover_thumbnail.jpeg', 234, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47yny', '47yny', 'Judaísmo e Modernidade: metamorfoses da tradição messiânica', NULL, '["Bernardo Sorj","Mónica Grin"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O judaísmo moderno corresponde aos diversos esforços de traduzir a tradição judaica rabínica em conceitos e valores da modernidade. Esta tradução não foi somente intelectual, mas, fundamentalmente, prática. Significou o abandono da auto-organização comunal e a autonomia cultural e judiciária dos judeus que o rolo compressor do Estado moderno não podia suportar. Na visão dos defensores da causa judaica na Revolução Francesa, a emancipação política dos judeus passava pela emancipação do judaísmo. Os “vícios” judaicos – hábitos alimentares repulsivos; misantropia – eram generosamente explicados como se fora efeito do isolamento a que foram condenados. A integração na sociedade permitiria uma rápida “regeneração” do povo judeu.[Trecho retirado da introdução do livro]', '["modern Judaism","rabbinic tradition","modernity","Jewish emancipation","French Revolution","Jewish emancipation movement","Jewish autonomy","Jewish stereotypes"]', '10.7476/9788599662656', '9788599662656', 'https://books.scielo.org/id/47yny', 'https://books.scielo.org/id/47yny/pdf/sorj-9788599662656.pdf', NULL, 'https://books.scielo.org/id/47yny/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-47zrm', '47zrm', 'TikTok: más allá de la hipermedialidad', NULL, '["Andrea De Santis-Piras","Diego Vintimilla-León"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Durante el confinamiento producido por la pandemia de la Covid-19, las redes sociales jugaron un papel predominante dentro del ecosistema mediático. Plataformas emergentes como TikTok recibieron un impulso inesperado respecto al número de usuarios registrados y frecuencia de uso. La versatilidad de TikTok ha permitido que se diversifiquen sus propósitos siendo utilizada más allá del entretenimiento, enfocándose hacia fines comerciales políticos y educativos. Además de una visión panorámica de TikTok desde la perspectiva comunicativa, esta publicación incluye reflexiones sobre los medios de comunicación en pandemia, sus vulnerabilidades, amenazas y problemáticas -desinformación, infoxicación y noticias falsas- en un debate que busca prevenir su reiteración en futuras situaciones de crisis.', '["TikTok","hypermedia","COVID-19 pandemic","social media","media ecosystem","disinformation","infotainment","fake news","crisis communication","user engagement"]', '10.7476/9789978106815', '9789978106815', 'https://books.scielo.org/id/47zrm', 'https://books.scielo.org/id/47zrm/pdf/torres-9789978106815.pdf', NULL, 'https://books.scielo.org/id/47zrm/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-48', '48', 'África à vista: dez estudos sobre o português escrito por africanos no Brasil do século XIX', NULL, '["Tânia Lobo","Klebson Oliveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A formação histórica do português brasileiro deu-se em complexo contexto de contato entre línguas. Dentre as diversas situações de contato havidas, a do português com línguas africanas assume maior relevância por ter sido generalizada no tempo e no espaço. Africanos e afro-descendentes, no período que se estende do século XVII ao século XIX, correspondem juntos a cerca de 60% da população brasileira (cf. MUSSA, 1991). Contudo, a escrita da história lingüística deste que é o mais expressivo segmento formador da população brasileira era tarefa que se colocava no plano de uma reconstrução quase que exclusivamente a partir de ''indícios'', uma tarefa não para historiadores, mas para arqueólogos da língua portuguesa (cf. MATTOS E SILVA, 2002) (trecho retirado da Introdução do livro).', '["Brazilian Portuguese","language contact","African languages","19th-century Brazilian literature","language history","creolization"]', '10.7476/9788523208882', '9788523208882', 'https://books.scielo.org/id/48', 'https://books.scielo.org/id/48/pdf/lobo-9788523208882.pdf', NULL, 'https://books.scielo.org/id/48/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-48334', '48334', 'Teoria da aprendizagem na obra de Jean Piaget', NULL, '["Adrián Oscar Dongo-Montoya"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro aborda o primeiro período das pesquisas de Piaget, que se referem à formação dos primeiros hábitos ou dos primeiros esquemas adquiridos até evoluírem para formas de coordenação de esquemas com busca intencional da novidade da experiência. Nesse período, o autor fornece elementos conceituais e factuais para a dissolução da dicotomia entre aprendizagem e inteligência. Essa parte possui relevância teórica para a primeira formulação de um novo conceito de aprendizagem como um processo que obedece a processos adaptativos de natureza ativa e sistêmica, e de processo que se torna solidário com o desenvolvimento da inteligência.', '["Piaget","learning theory","schema formation","habit formation","adaptive processes","active learning"]', '10.7476/9788539304530', '9788571399457', 'https://books.scielo.org/id/48334', NULL, NULL, 'https://books.scielo.org/id/48334/cover/cover_thumbnail.jpeg', 222, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-48j6g', '48j6g', 'Cosmología en la obra de Dante Alighieri. Génesis y fuentes', NULL, '["Jorge Iván Salazar Muñoz"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este texto explora algunas relaciones entre arte y ciencia; se concentra en un periodo especifico de la historia: la Baja Edad Media, y en un autor en particular: Dante Alighieri. La selección de la obra de Dante como objeto de estudio obedece a dos razones: en primer lugar, a su importancia histórica. Para muchos autores, La divina comedia es el texto central de la literatura medieval. Jorge Luis Borges llego a considerar el poema de Dante como un microcosmos del saber medieval. En segundo lugar, la obra de Dante, en especial La divina comedia, dado el objetivo general que desarrolla, permite una aproximación a diversas cuestiones de ciencia y de cosmología. Hay que recordar que el poema trata un amplio espectro de temas: filosofía, teología, moral y política. Las discusiones cosmológicas no constituyen el eje del texto, pero resultan inevitables, dado el plan general de la obra. Dante quería mostrar el recorrido simbólico y moral del alma a través de los reinos sobrenaturales: el infierno, el purgatorio y el paraíso. La geografía de estos reinos, en muchos casos, se acomodaba al saber de la ciencia medieval, especialmente en los versos del Paraíso. Otro tanto ocurre en el Convivio.', '["Dante Alighieri","Divine Comedy","cosmology","medieval science","art and science","Convivio","Inferno","Purgatorio","paradise","medieval geography","Jorge Luis Borges","late Middle Ages"]', '10.7476/9789587849547', '9789587384338', 'https://books.scielo.org/id/48j6g', NULL, NULL, 'https://books.scielo.org/id/48j6g/cover/cover_thumbnail.jpeg', 163, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-48jg4', '48jg4', 'Doença de Chagas, doença do Brasil: ciência, saúde e nação, 1909-1962', NULL, '["Simone Petraglia Kropf"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ainda hoje estima-se que na América Latina aproximadamente 13 milhões de pessoas desconheçam estarem infectadas e sobrevivendo com o vetor da doença de Chagas, de acordo com a ONG Médicos Sem Fronteiras. Embora o Brasil tenha sido considerado livre da transmissão pela principal espécie de vetor em 2006, pela OMS, é importante que novas gerações de estudantes das áreas da saúde coletiva possam conhecer o processo histórico e o percurso pelo qual a descoberta científica pôde ser identificada, reconhecida e legitimada pela comunidade médico-científica como ''doença''. O livro em questão analisa o processo de transformação da doença de Chagas em ''doença'' e reconstrói a trajetória de Carlos Chagas e seus estudos sobre a enfermidade. Tem por objetivo, nas palavras da autora, “refletir sobre a dimensão histórica e social desse processo, no qual este fato científico foi sendo produzido e validado em estreita relação com vários grupos e esferas da vida social brasileira”. A obra conjuga história social da medicina, história social da ciência e do pensamento social brasileiro, uma vez que a própria caracterização da doença de Chagas foi, ao longo de boa parte do século XX, associada à imagem do Brasil.', '["Chagas disease","Carlos Chagas","disease classification","history of medicine","social history of science","social thought","Brazil","Triatominae","public health","national identity"]', '10.7476/9788575413159', '9788575413159', 'https://books.scielo.org/id/48jg4', 'https://books.scielo.org/id/48jg4/pdf/kropf-9788575413159.pdf', NULL, 'https://books.scielo.org/id/48jg4/cover/cover_thumbnail.jpeg', NULL, 66, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-48z26', '48z26', 'Como e por que as desigualdades sociais fazem mal à saúde', NULL, '["Rita Barradas Barata"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'ApreSentAçãoMeu interesse pela temática das desigualdades sociais em saúde é relativamente antigo.Desde os tempos da faculdade, o interesse pelas ciências sociais e pela epidemiologia me fez buscar articular esses saberes para melhor compreender o processo saúde-doença em sua dimensão coletiva.A temática das desigualdades sociais em saúde esteve sempre presente na minha trajetória como investigadora do campo da epidemiologia social.Ainda na etapa de elaboração da dissertação de mestrado, sob a influência da professora Cecília Donnangelo e do meu orientador, professor José da Silva Guedes, decidi estudar o comportamento de uma epidemia de doença meningocóccica, analisando o surgimento e a disseminação do processo segundo distritos da cidade de São Paulo classificados por diferentes condições de vida.O trabalho acabou virando livro ainda na década de 1980.Na década seguinte, organizei em São Paulo um seminário ibero-americano sobre a temática das condições de vida e a situação de saúde, que resultou em uma publicação pela Abrasco dos trabalhos ali apresentados.', '["health disparities","social determinants of health","living conditions","social epidemiology","health-disease process","São Paulo"]', '10.7476/9788575413913', '9788575413913', 'https://books.scielo.org/id/48z26', 'https://books.scielo.org/id/48z26/pdf/barata-9788575413913.pdf', NULL, 'https://books.scielo.org/id/48z26/cover/cover_thumbnail.jpeg', NULL, 94, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-493c5', '493c5', 'Geografia cultural: uma antologia, Vol. 2', NULL, '["Zeny Rosendahl","Roberto Lobato Corrêa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Indicado para alunos de cursos de graduação e de pós-graduação, oferece uma criteriosa seleção de textos publicados em língua portuguesa sobre as relações entre espaço e cultura. Neste volume, predominam artigos da linha de estudos conhecida como nova geografia cultural, vertente que analisa a cultura como um contexto, condição de existência e reflexo dos diferentes grupos sociais. A antologia divide-se em cinco partes: O urbano e a cultura; Formas simbólicas e espaço; Espaço e religião; Festas e espaço; Identidade e território; e Cinema e literatura.', '["cultural geography","new cultural geography","space and culture","urban culture","symbolic forms","religion and space","festivals","territory and identity","cinema","literature","social groups"]', '10.7476/9788575114391', '9788575112892', 'https://books.scielo.org/id/493c5', NULL, NULL, 'https://books.scielo.org/id/493c5/cover/cover_thumbnail.jpeg', 344, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-49tbx', '49tbx', 'Estrategias de enseñanza aprendizaje en ambientes musicales. Enfoque para niños, niñas y adolescentes con discapacidad víctimas del conflicto armado colombiano', NULL, '["Oscar Javier Larrota Veloza","Elvis Siprián Castro Alzate","Karen Aguía Rojas","María Carolina Navas Solano","Mónica María Ruiz Acuña"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estrategias de enseñanza aprendizaje en ambientes musicales. Enfoque para niños, niñas y adolescentes con discapacidad víctimas del conflicto armado colombiano, es uno de los resultados destacables de la alianza de cinco años, celebrada entre la Universidad Colegio Mayor del Rosario y la Fundación Nacional Batuta, para profundizar y dinamizar el trabajo en el área de terapia ocupacional en beneficio de los procesos pedagógicos y musicales de los niños y niñas con discapacidad pertenecientes al Programa Música para la Reconciliación. Esta publicación refleja la interlocución de saberes entre la música y la terapia ocupacional y presenta algunas estrategias que favorecen los procesos de enseñanza/ aprendizaje de la población con discapacidad en el marco del campo de acción de la Fundación. Así mismo, presenta elementos esenciales para la motivación de los equipos interdisciplinarios que trabajan, día a día, en las clases de música para facilitar la participación activa en la formación musical de las personas en situación de discapacidad. Este libro es una herramienta útil para los trabajadores sociales, los terapeutas ocupacionales, los profesores de música, las personas vinculadas a procesos formativos o participativos mediante los cuales se atienden personas en condición de discapacidad y para todos aquellos que creen –como nosotros– que la música es un vehículo fundamental para favorecer el desarrollo del ser humano.', '["music education","teaching-learning strategies","occupational therapy","children and adolescents with disabilities","interdisciplinary teams","music therapy","social inclusion"]', '10.7476/9789587386950', '9789587386943', 'https://books.scielo.org/id/49tbx', NULL, NULL, 'https://books.scielo.org/id/49tbx/cover/cover_thumbnail.jpeg', 78, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-49yt7', '49yt7', 'A formação cultural dos jovens do MST : a experiência do assentamento Mário Lago, em Ribeirão Preto (SP)', NULL, '["Frederico Daia Firmiano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A presente pesquisa é um esforço de reflexão sobre o processo de formação cultural dos jovens integrantes do assentamento Mário Lago, construído através da luta de famílias de trabalhadores que formam a base de mobilização do Movimento dos Trabalhadores Rurais Sem Terra, MST, no município de Ribeirão Preto-SP, auto-denominado “capital nacional do agronegócio”, em razão de sua projeção nacional e internacional através do complexo de atividades econômicas vinculadas ao contexto da produção agro-industrial. Consideramos os jovens como sujeitos dos processos abertos pela luta política em torno da terra e interlocutores dos grupos com os quais convivem, configurando sua consciência perante o que experimentam no cotidiano. Além disso, identificamos as referências ético-políticas construídas junto a comunidade e junto ao MST, os constrangimentos presentes em suas vidas, constituídos pelos limites objetivos e subjetivos da luta pela terra em Ribeirão Preto, bem como sua capacidade de projetar o futuro. Destarte, nossa pesquisa distingue-se de outras voltadas à compreensão das opiniões individuais ou de contingentes populacionais jovens, à medida que reconhece a experiência dos jovens do assentamento Mário Lago como a expressão diversificada da experiência de formação cultural e política na sociedade brasileira.', '["cultural formation","youth","Landless Workers'' Movement (MST)","land reform","land struggle","political consciousness","agribusiness","Ribeirão Preto","political education"]', '10.7476/9788579830433', '9788579830433', 'https://books.scielo.org/id/49yt7', 'https://books.scielo.org/id/49yt7/pdf/firmiano-9788579830433.pdf', NULL, 'https://books.scielo.org/id/49yt7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4bhdw', '4bhdw', 'Entre cenas, memórias e estilhaços', NULL, '["Ana Cristina Colla","Raquel Scotti Hirson","Renato Ferracini"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro, escrito a seis mãos pelos artistas da cena Ana Cristina Colla, Raquel Scotti Hirson e Renato Ferracini, aborda as fases, os trabalhos e as propostas do processo criativo da obra cênica do Lume Kintsugi, 100 memórias, desenvolvido em 2019. Para além da narrativa ou do arquivo de criação de uma obra teatral, o texto problematiza questões da produção cênica na contemporaneidade, como o uso da memória pessoal, social e política como ação poética, a tensão entre a ficção e o real e o enlace entre performatividade e teatralidade. Discute o conceito de pesquisa de campo na área de artes presenciais e ainda inaugura a possibilidade de uma prática de pesquisa de campo performativa a partir das propostas práticas dos atores e atrizes realizadas com a população da cidade de Angostura, na Colômbia.', '["collaborative theatre","creative process","personal memories","social memory","political memory","fiction and reality","performativity","theatricality","Angostura","Colombian theatre"]', '10.7476/9788526816633', '9788526815803', 'https://books.scielo.org/id/4bhdw', NULL, NULL, 'https://books.scielo.org/id/4bhdw/cover/cover_thumbnail.jpeg', 231, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4c6bv', '4c6bv', 'Amor e violência: um paradoxo das relações de namoro e do ‘ficar’ entre jovens brasileiros', NULL, '["Maria Cecília de Souza Minayo","Simone Gonçalves de Assis","Kathie Njaine"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Gerar conhecimento estratégico sobre o tema da violência no namoro e no ‘ficar’ dos adolescentes brasileiros: este foi o objetivo de um estudo pioneiro realizado por pesquisadores de nove universidades públicas e da Fiocruz. O trabalho, que teve início em 2007, coletou, produziu e analisou dados quantitativos e qualitativos de âmbito nacional. O estudo foi realizado com cerca de 3.200 jovens, de 15 a 19 anos, matriculados em escolas públicas e particulares de dez cidades (Belo Horizonte, Brasília, Cuiabá, Florianópolis, Manaus, Porto Alegre, Porto Velho, Rio de Janeiro, Recife e Teresina). Os resultados da investigação deram origem a esta coletânea, que faz uma síntese dos achados, mas também das interrogações do estudo.', '["dating violence","romantic relationships","adolescents","young adults","love and violence","gender-based violence","Brazilian youth","public and private schools"]', '10.7476/9788575413852', '9788575413852', 'https://books.scielo.org/id/4c6bv', 'https://books.scielo.org/id/4c6bv/pdf/minayo-9788575413852.pdf', NULL, 'https://books.scielo.org/id/4c6bv/cover/cover_thumbnail.jpeg', NULL, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4cdf6', '4cdf6', 'O Rio em Movimento: quadros médicos e(m) história 1890 - 1920', NULL, '["Myriam Bahia Lopes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Preparaçãode originais, copidesque e revisões finais Marcionílio Cavalcanti de Paiva Prefácio O cenário é nosso conhecido: o Rio de Janeiro vivendo os primeiros tempos do regime republicano.A cidade colonial ainda visível no traçado das ruas e nos costumes de seus habitantes.A ausência de saneamento básico, a sujeira das ruas e a promiscuidade dos cortiços acentuam a ameaça de doenças contagiosas, tornando mais visível a pouca adesão dos citadinos aos princípios de urbanidade.Na esteira dos anos da propaganda republicana, liberais e positivistas trilham caminhos diversos e polemizam na defesa de ideais republicanos.Restam ainda alguns renitentes defensores do regime monárquico.O trabalho escravo ficou no passado em meio à formação do mercado de trabalho livre.Imigrantes chegam, falam línguas desconhecidas, trazem na bagagem aspirações de melhores dias e hábitos e contrastam com o da população local.As autoridades governamentais se esforçam para transformar a cidade em cartão de visitas do Brasil: o bota-abaixo do morro da Favela e a guerra aos cortiços; a abertura de largas avenidas ladeadas de edifícios construídos com as modernas técnicas da engenharia e obedecendo aos padrões neoclássico e eclético; médicos e engenheiros sanitaristas não chegam a um acordo quanto aos meios eficazes de erradicação de doenças epidêmicas.A população reage, ou ao menos parte dela, contra as campanhas de vacinação obrigatória.Contudo, entre as pessoas avessas a se deixarem inocular com a vacina encontram-se muitas que não o fazem por ignorância ou preconceitos arraigados.Ε exatamente esse desencontro de opiniões que chega a se enfrentar nos jornais e revistas, que cresce assumindo a dimensão de revolta violenta no qual a população amotinada subverte a delimitação entre o espaço público e o privado, que provoca a intriga que Myriam resolveu investigar.Sua pesquisa começa, pois, rejeitando o recorrente quadro completo, no qual vacinistas atuam incitando a reação dos que dele discordam.Ou seja, um quadro onde as peças se encaixam como num grande mosaico e que para ela soa como explicação simples demais.Procura, como boa pesquisadora, se assemelhar a um detetive; detetive pouco prosaico, no entanto, quando empresta a Walter Benjamin a noção de centelha e a desconfiança nas interpretações que arrematam os fios dispersos da ação e do pensamento num argumento explicativo acabado, fácil, conclusivo, com freqüência bastante assemelhada às ''verdades científicas'' que pretende derrubar.Em suma, recusa as pistas muito evidentes.Questiona a maneira como história e medicina se tornam cúmplices para falar de uma cidade -Rio de Janeiro -que se ''civiliza'', aceita a provocação benjaminiana de que "todo documento de cultura é também um documento de barbárie".Discorda, portanto, dos que descartam a priori, como pouco importantes, os pressupostos e os procedimentos dos médicos antivacinistas, dado que o tempo mostrou que a razão estava com os adeptos da vacina.Num movimento a contrapelo, Myriam desvenda uma outra prática, estigmatizada pela opinião do saber oficial que a combatia, e reduzida ao esquecimento pelos historiadores.Dirige sua atenção para os profissionais vinculados aos postulados do positivismo e que não necessariamente contrariavam o lema ''ordem e progresso'' ao denunciarem a prática invasiva da vacinação, em circunstâncias nas quais os métodos disponíveis faziam de cidades, países e continentes laboratórios de experimentação.Com seu procedimento, Myriam chega aos alicerces das disputas médicas: os preceitos científicos também se fundamentam em pressupostos filosóficos.O embate de opiniões científicas não se esgota nas ''verdades comprovadas'' pela prática médica.Tal como a engenharia sanitária, sua companheira de rota na adesão a uma dada concepção de sanitarismo, os médicos vacinistas têm suas certezas amparadas no pressuposto liberal da identificação e universalidade do agente epidêmico.Com base em outros pressupostos, os clínicos positivistas se batem pela concepção mesológica de complementaridade entre a natureza e o equilíbrio dos corpos.No debate, entretanto, a historiografia tem embarcado no poder de convencimento dos argumentos da documentação médica de época, na qual inexistem registros dos fracassos provocados pelas reações orgânicas à vacina.Contudo, na trajetória de certezas, houveram reversões de expectativa que chegaram às vezes até à morte.Considerada, talvez, acidente de percurso, sacrifício necessário ''no altar da ciência'' para que a prática médica se aperfeiçoasse.Recorrendo a fontes diversas, nas quais falas médicas, leis e códigos mesclam-se a caricaturas e considerações irônicas, e nas quais também informações jornalísticas completam e/ou contradizem justificativas policiais para a repressão à população amotinada, Myriam nos apresenta um quadro fragmentado, inacabado, onde a lógica dos argumentos oficiais são entrecortados por vozes dissonantes: menos um diálogo e mais o desencontro de certezas inscritas em campos diferentes, incapazes de se escutarem.Uma luta política acima de tudo, que em muito extrapola os limites geográficos do Brasil e expõe uma guerra não convencional que se espalha pelo ''mundo civilizado'' do século XIX e início do XX.Myriam chega, assim, a outro ponto polêmico ante o qual não recua: o da forma como as ''idéias'' e o conhecimento circulam entre países, indiferentes às fronteiras dos Estados nacionais, muito mais relacionadas com o debate entre grupos de especialistas aferrados às suas próprias convicções.Incansável, Myriam fez deste trabalho o ponto de partida para o exercício da pesquisa que recusa conclusões aprisionadas a teorias explicativas da história.Ela não se detém perante o desafio de percorrer textos pouco usuais na prática historiográfica, tais como a dimensão técnica das teorias médicas e, sobretudo, seus pressupostos teórico-filosóficos.O mesmo fez com a fotografia, mostrando-a como algo muito mais complexo do que uma técnica a serviço da ''verdade científica'' fixada pela neutralidade das lentes ou documente empregada pelo fotógrafo em busca de uma concepção estética.Foi além, encarou o desafio de aproximar-se da caricatura, não somente como ilustração de um argumento seu, mas dela fazendo fonte historiográfica.Considero importante salientar, por último, sua ousadia maior: a forma inovadora de escrita a partir de narrativas entrecruzadas, nas quais confirma a recusa a dar uma resposta acabada a suas indagações e desvenda facetas inesperadas que introduzem ruído em toda e qualquer explicação conclusiva a que se queira chegar.', '["Rio de Janeiro","urban history","public health","sanitation","epidemics","mandatory vaccination","anti-vaccine movement","favelas","cortiços","Republican era","newspapers and periodicals","public health campaigns"]', '10.7476/9788575412756', '9788575412756', 'https://books.scielo.org/id/4cdf6', 'https://books.scielo.org/id/4cdf6/pdf/lopes-9788575412756.pdf', NULL, 'https://books.scielo.org/id/4cdf6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4dhx8', '4dhx8', 'Aristas del conflicto colombiano', NULL, '["María Victoria Uribe","Ana María Alba Forero"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aristas del Conflicto refleja los diálogos sostenidos al interior de la Línea Democracia y Justicia de la Facultad de Jurisprudencia de la Universidad del Rosario. El volumen está conformado por seis capítulos. El primero de ellos, Análisis del Marco Jurídico para la paz ¿Una ley para quienes?, hace un seguimiento al marco jurídico para la paz propuesto por el gobierno Santos para darle sustento jurídico a los diálogos que se llevan a cabo en la Habana con la guerrilla de las FARC; en el texto se indaga si éste es un modelo que garantiza o no los derechos de las víctimas. El segundo capítulo, Tomarse el derecho en serio: el derecho en las transiciones políticas. A propósito del caso colombiano, analiza cuáles concepciones del derecho son favorables a los fines normativos de la justicia transicional. El capítulo siguiente, La reparación a las víctimas en la Ley de Justicia y Paz, un modelo de desacuerdos y falsas promesas, se centra en el debate sobre los derechos adquiridos por las víctimas del conflicto armado y las expectativas creadas en el marco de la reparación judicial de la Ley de Justicia y Paz. El escrito Asimetrías en el Proceso de Justicia y Paz en Colombia deja de lado la mirada jurídica, y ofrece una etnografía de los espacios y procedimientos judiciales; en otras palabras, observa y describe la compleja forma en la que se interrelacionan tres ámbitos de producción de conocimiento, diferentes y asimétricos, inherentes a la ley de Justicia y Paz. En el capitulo Conflicto Armado Colombiano, Feminismo Radical Criollo se evalúan las influencias de los discursos feministas en la comprensión del conflicto armado colombiano. Y, por último, el capítulo Comprendiendo al Ejército analiza de que manera algunos altos mandos del ejército nacional colombiano se auto representan, cómo inventan su tradición, y cuál es el trasfondo mediante el cual justifican sus acciones.', '["Colombian armed conflict","peace process","Law of Justice and Peace","FARC","transitional justice","victims'' rights","political transition","Colombian Army"]', '10.7476/9789587384819', '9789587384802', 'https://books.scielo.org/id/4dhx8', NULL, NULL, 'https://books.scielo.org/id/4dhx8/cover/cover_thumbnail.jpeg', 167, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4dp27', '4dp27', 'Mundo do crime: a ordem pelo avesso', NULL, '["José Ricardo Ramalho"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O crime e a prisão constituem os objetos de estudo deste livro. Procura-se percebê-los a partir da ótica do próprio criminoso enquanto preso, ponto de vista nem sempre reconhecido como legítimo. As várias discussões sobre o tema têm sistematicamente colocado em uma nova roupagem velhas concepções sobre os criminosos e a prisão, concepções estas que em geral reproduzem versões difundidas pelo sistema judiciário. É para pensar esta temática através de outra perspectiva, que este trabalho procura se desenvolver. Discute-se aqui, não só a versão do criminoso sobre o mundo do crime e suas formas de manifestação na prisão, como também as formas pelas quais sua consciência capta a situação num contexto mais amplo, em que a origem social tem um peso fundamental na sua identificação enquanto delinqüente.', '["prisons","prisoners","criminal identity","criminality","criminal justice system"]', '10.7476/9788599662267', '9788599662267', 'https://books.scielo.org/id/4dp27', 'https://books.scielo.org/id/4dp27/pdf/ramalho-9788599662267.pdf', NULL, 'https://books.scielo.org/id/4dp27/cover/cover_thumbnail.jpeg', NULL, 107, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4fdcs', '4fdcs', 'El desafío latinoamericano: cohesión social y democracia', NULL, '["Bernardo Sorj","Danilo Martuccelli"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Entender la dinámica a través de la cual se construye la cohesión social en América Latina supone una inversión de perspectiva frente a la tendencia dominante que enfatiza los problemas sociales que afligen el continente. Si desconocer estas dificultades sería caer en apologías conservadoras, para entender cómo nuestras sociedades generan cohesión social no podemos dejar de identificar igualmente los enormes recursos positivos de integración y de creatividad socio-cultural existentes en nuestras sociedades.', '["social cohesion","democracy","Latin America","social integration"]', '10.7476/9788579820793', '9788579820793', 'https://books.scielo.org/id/4fdcs', 'https://books.scielo.org/id/4fdcs/pdf/sorj-9788579820793.pdf', NULL, 'https://books.scielo.org/id/4fdcs/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4fdpg', '4fdpg', 'Urbanismo de colina: uma tradição luso-brasileira', NULL, '["Lobo, Manuel Leal da Costa","José Geraldo Simões"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', '[RETIRADO/WITHDRAWN] Este livro aborda os processos tradicionais de ocupação das áreas de colina nas cidades brasileiras e portuguesas, associados à tradição da urbanística lusitana de ocupar sítios em locais elevados para a fundação de sete cidades: Lisboa, Coimbra e Óbidos, em Portugal, e Salvador, São Paulo, Rio de Janeiro e Ouro Preto, no Brasil.', '["hilltop settlement","traditional settlement patterns","Lisbon","Coimbra","Salvador, Bahia","São Paulo","Rio de Janeiro","Ouro Preto"]', '10.7476/9788582930533', '9788582930533', 'https://books.scielo.org/id/4fdpg', NULL, NULL, 'https://books.scielo.org/id/4fdpg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4fz8b', '4fz8b', 'Jurisdição constitucional, hermenêutica e democracia: um recorte teórico judicial do STF', 'um recorte teórico judicial do STF', '["Rosário, Luana Paixão Dantas do","Oliveira, João Mateus Silva Fagundes"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro explora a relação entre a Jurisdição Constitucional, a Hermenêutica e a Democracia, com base nas decisões do Supremo Tribunal Federal (STF). Muitas dessas decisões garantiram direitos a grupos historicamente excluídos, como mulheres, pessoas não brancas e LGBTQIA+; outras reforçaram essa exclusão. Essas decisões tiveram um impacto significativo no desenho da democracia brasileira. O livro aborda ainda, questões como gênero, aborto, cotas raciais, união homoafetiva, impeachment, ocupações estudantis, registro civil de pessoas transexuais, direito à verdade e memória, entre outras. Além disso, ele questiona o ativismo e a autocontenção judicial presentes nessas decisões, analisando a diversidade de discursos judiciais, suas bases ideológicas e legitimidade.', '["constitutional jurisdiction","legal hermeneutics","democracy","Supreme Federal Court","judicial activism","judicial restraint","gender","abortion","racial quotas","same-sex unions","impeachment","student occupations"]', '10.7476/9788574556017', '9788574555843', 'https://books.scielo.org/id/4fz8b', NULL, NULL, 'https://books.scielo.org/id/4fz8b/cover/cover_thumbnail.jpeg', 279, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4gdw9', '4gdw9', 'Narrativas de um revisor de textos', 'vivências em uma editora universitária', '["Roberto Santos de Carvalho"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é uma celebração da linguagem, um tributo aos detalhes que transformam um manuscrito em uma obra publicada. Por meio de suas narrativas, o autor nos mostra que a revisão não é apenas uma etapa técnica, mas uma jornada de descoberta, aperfeiçoamento e decisões amparadas na formação e visão de mundo do profissional. É uma leitura indispensável para escritores, revisores e amantes da leitura, produção e revisão de textos.', '["text editing","proofreading","manuscript revision","editorial process","language","writing process","editorial decision-making"]', '10.7476/9788574556192', '9788574555997', 'https://books.scielo.org/id/4gdw9', NULL, NULL, 'https://books.scielo.org/id/4gdw9/cover/cover_thumbnail.jpeg', 239, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4ghgb', '4ghgb', 'Agir comunicativo e planejamento social: uma crítica ao enfoque estratégico', NULL, '["Francisco Javier Uribe Rivera"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estudo teórico, de natureza comparativo-contrastante, abordando a lógica do planejamento estratégico no setor social e da saúde à luz da teoria do agir comunicativo de Jürgen Habermas. Na verdade, trata-se de uma ''crítica da crítica'', na medida em que são problematizados os enfoques metodológicos tomados, até o momento, como referencial teórico alternativo ao planejamento normativo. A partir da teoria da ação habermasiana, o autor consegue indicações importantes para uma (re)leitura da teoria organizacional, na perspectiva de uma abordagem comunicativa entre todos os atores envolvidos nas organizações de saúde.', '["communicative action","strategic planning","social planning","Jürgen Habermas","normative planning","organizational theory","health organizations","communicative language teaching","health sector"]', '10.7476/9788575412480', '9788575412480', 'https://books.scielo.org/id/4ghgb', 'https://books.scielo.org/id/4ghgb/pdf/rivera-9788575412480.pdf', NULL, 'https://books.scielo.org/id/4ghgb/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4gxvj', '4gxvj', 'Poder blando y diplomacia cultural. Elementos clave de políticas exteriores en transformaciones', NULL, '["Mauricio Jaramillo Jassir"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Esta obra no tiene una ambición distinta a la de estimular una reflexión sobre el alcance de la cultura en la política exterior de los Estados. Se sabe que la diplomacia y la política exterior constituyen un campo de estudio de las relaciones internacionales en constante expansión e imposible de agotar en un solo sentido o un una sola lectura. En consecuencia, este libro pretende constituir un insumo en la comprensión de una temática delimitada y particular. El lector que opte por adentrase en el fascinante tema de la cultura y de la gestión de la política exterior, encontrará preguntas y algunas respuestas que le permitirán entender en su real dimensión la forma como los atributos que definen a las potencias y a los actores influyentes del sistema internacional han venido transformándose con el paso de los años. Se trata de un cambio que no debe pasar inadvertido para aquellos interesados en la cultura y en la política exterior. Este texto es el resultado del proyecto de investigación sobre el poder blando y la diplomacia cultural de Turquía y sus lecciones para Colombia financiado por el Fondo de Investigaciones de la Universidad del Rosario (FIUR) entre 2013 y 2014”. [Extracto del prólogo]', '["soft power","cultural diplomacy","foreign policy","Colombia","international relations"]', '10.7476/9789587386974', '9789587386967', 'https://books.scielo.org/id/4gxvj', NULL, NULL, 'https://books.scielo.org/id/4gxvj/cover/cover_thumbnail.jpeg', 141, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4hdyr', '4hdyr', 'Valores familiares e uso abusivo de drogas', NULL, '["Miriam Schenker"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Na esfera do conflito entre gerações, pesquisei a forma de organização da família, os sonhos e os modelos de comportamento. Finalmente, no domínio do processo educativo, investiguei o estilo de educação, o estabelecimento de limites e as figuras de autoridade na família.As famílias pesquisadas pertencem às camadas médias da população urbana e provêem de duas instituições especializadas no atendimento à drogadição. Escolhi empreender a pesquisa dos valores familiares seguindo a narrativa das três gerações de algumas famílias do campo pesquisado e a partir de uma entrevista semi-estruturada e gravada com o consentimento dos participantes, dentro do marco referencial sistêmico-cibernético.Utilizei alternadamente três dimensões para a operacionalização dos temas: opinião, comportamento e expectativa.Os resultados dessa abordagem compreensiva da tecedura das histórias familiares são amplos e complexos e respondem afirmativamente à questão inicial porque: a) Há uma inversão na hierarquia familiar que influencia o estilo de educação, a construção da autonomia e os modelos familiares todos eles fundamentais para a promoção dos valores familiares;b)Vínculos dependentes, de apego, que estimulam a infantilização dos filhos e netos não configuram condições de possibilidade para a internalização dos valores familiares no sentido almejado pelas famílias; c) Há expectativas conflitantes através das gerações porque avós e pais, ao não perceberem a defasagem entre a idade cronólogica e a emocional de seus filhos e netos elaboram projetos distantes da realidade desses últimos;d) Os atributos de avós e pais são de tal ordem que auxiliam a construção de modelos sem sustentação para os jovens; e) Os estilos de criação autoritária e permissiva dos avós e pais não contribuíram para o desenvolvimento sócio-emocional da maioria dos filhos e de todos os jovens, influenciando a aquisição dos valores pelos participantes da geração dos pais e dos filhos.A conclusão também contém reflexões sobre a prevenção e o tratamento do uso abusivo de drogas pautadas no trabalho com os valores familiares, de acordo como eles são descritos nessa tese. A educação para valores familiares deve ser incluída no tratamento do uso abusivo e na prevenção ao uso indevido de substâncias.', '["family values","drug abuse","intergenerational conflict","family hierarchy","parenting styles","authoritarian parenting","permissive parenting","family boundaries","generational expectations","substance use prevention","addiction treatment","family narratives"]', '10.7476/9788575413791', '9788575411537', 'https://books.scielo.org/id/4hdyr', NULL, NULL, 'https://books.scielo.org/id/4hdyr/cover/cover_thumbnail.jpeg', 166, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4hfg3', '4hfg3', 'Oralidades y escrituras kichwas', NULL, '["Fernando Garcés","Armando Muyolema"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Las tensiones entre oralidad y escritura han caracterizado silenciosamente tanto los estudios como los esfuerzos de enseñanza/aprendizaje y de revitalización de las lenguas minorizadas en sus diferentes contextos sociales, culturales, históricos y políticos en la región. Ese tránsito de ida y vuelta entre los universos de la oralidad y la escritura, mediado de manera creciente por medios audiovisuales, ha provocado discusiones y dilemas en distintos ámbitos de uso de estas lenguas. En este contexto, est elibro recoge un selecto conjunto de estudios que aborda estas complejas dinámicas desde distintas perspectivas temáticas y experiencias sociales, en este caso, del quichua ecuatoriano.', '["Kichwa","Quichua language","orality and writing","language revitalization","minority languages","audiovisual media","language teaching and learning"]', '10.7476/9789978108246', '9789978108246', 'https://books.scielo.org/id/4hfg3', 'https://books.scielo.org/id/4hfg3/pdf/garces-9789978108246.pdf', NULL, 'https://books.scielo.org/id/4hfg3/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4j2xp', '4j2xp', 'Medicina no Brasil imperial: clima, parasitas e patologia tropical', NULL, '["Flávio Coelho Edler"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro guia o leitor pelos caminhos do pensamento médico brasileiro no século XIX e as origens da medicina tropical no país. Mais especificamente, fala da gênese da parasitologia helmintológica (estudo de vermes parasitas) e mostra como esse novo saber se legitimou e foi incorporado às práticas de diagnóstico, tratamento e profilaxia de doenças. Analisa as disputas em torno dessa legitimação, onde a helmintologia médica se confrontava com a climatologia - que associava as doenças às peculiaridades do clima e às características naturais do Brasil. Mostra como a helmintologia médica contribuiu para a corrosão da climatologia, embora esse processo tenha sido marcado tanto por rupturas como por continuidades, na medida em que, a princípio, não se tratava de saberes incomensuráveis. Como se lê desde o prefácio, "os inovadores não queriam vencer, mas convencer".', '["tropical medicine","helminthology","history of medicine","19th century","climatology","climate and disease","parasites","diagnosis","disease treatment","disease prevention","Brazil","Brazilian Empire"]', '10.7476/9788575413371', '9788575412152', 'https://books.scielo.org/id/4j2xp', NULL, NULL, 'https://books.scielo.org/id/4j2xp/cover/cover_thumbnail.jpeg', 298, 48, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4jfjj', '4jfjj', 'Comunistas brasileiros: cultura política e produção cultural', NULL, '["Marcos Napolitano","Rodrigo Czajka","Motta, Rodrigo Patto Sá"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea representa uma proposta inovadora, ao reunir textos que abordam o tema do comunismo por um viés ainda pouco explorado na literatura acadêmica, enfocando-o como cultura política e como agência produtora de padrões de comportamento e de crenças. A motivação é oferecer melhor entendimento dos elementos constituintes da cultura comunista, cujos valores e ideias circularam para além dos espaços tradicionais da esquerda, fornecendo temas e argumentos para os agentes produtores de cultura, assim como inspirando determinadas políticas culturais. Pretende-se, desse modo, avaliar a força de atração e a capacidade de reprodução dos valores e padrões comunistas, decisiva para a compreensão da modernidade cultural e política brasileira.', '["communism","political culture","cultural production","cultural policy","left-wing movements","cultural modernity","political modernity"]', '10.7476/9786558580836', '9788570419989', 'https://books.scielo.org/id/4jfjj', NULL, NULL, 'https://books.scielo.org/id/4jfjj/cover/cover_thumbnail.jpeg', 362, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4jjyh', '4jjyh', 'A harmonia de Jobim', NULL, '["Carlos de Lemos Almada"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A música de Antonio Carlos Jobim é mundialmente reconhecida por sua extraordinária beleza e originalidade. No entanto, sua estrutura ainda hoje carece de estudos técnicos que a examinem com os devidos detalhamento e profundidade. A harmonia de Jobim busca contribuir para suprir essa lacuna, propondo um estudo teórico-analítico sobre a construção harmônica desse grande compositor. O livro apresenta, em sua primeira parte, dois modelos teóricos originais, elaborados a partir do exame dos dados coletados em uma análise de 145 canções de Jobim e parceiros. A segunda parte é dedicada à funcionalidade harmônica dos campos tonais e das relações entre regiões, bem como ao peculiar modalismo jobiniano, alternando formulações conceituais e análises. Algumas abordagens específicas formam a terceira parte do volume, considerando aspectos textuais, melódicos e alguns tópicos especiais (acordes com sexta, a estética blues, acordes híbridos etc.).', '["Antonio Carlos Jobim","harmony","Brazilian popular music","harmonic analysis","modalism","song lyrics","melody"]', '10.7476/9788526816480', '9788526815476', 'https://books.scielo.org/id/4jjyh', NULL, NULL, 'https://books.scielo.org/id/4jjyh/cover/cover_thumbnail.jpeg', 348, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4kqtv', '4kqtv', 'Productos naturales: investigación y perspectivas en Ecuador', NULL, '["Tatiana Mosquera"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Ecuador es un país privilegiado por su riqueza en organismos vivos íntimamente relacionados con su alta biodiversidad. En los últimos 20 años, las universidades públicas y privadas, así como los institutos de investigación, han invertido en la formación de sus docentes-investigadores como en tecnología de última generación relacionada con este tema. Este texto refleja los avances en la producción científica que se han generado en el país. Tres capítulos son revisiones exhaustivas del uso tradicional y el potencial de las plantas medicinales en problemas de salud y aplicaciones puntuales. Un capítulo analiza las plantas medicinales y sus metabolitos en una determinada área biogeográfica del Ecuador. Una revisión se centra en el aceite esencial de una especie nativa de elevado potencial bio-económico como la Psidium guajava. Dos estudios experimentales confirman la riqueza fitoquímica y el potencial medicinal de especies de nuestra biodiversidad como la Persea americana y Chuquiraga jussiuei. Y finalmente, un capítulo analiza la importancia del control en los productos naturales procesados con base en su calidad microbiológica y la relación con las correctas prácticas de manufactura. Este texto confirma que Ecuador tiene mucho que mostrar al mundo de la ciencia.', '["natural products","medicinal plants","Ecuadorian biodiversity","traditional medicine","plant metabolites","guava","avocado","phytochemicals","essential oils","microbiological quality control","manufacturing practices"]', '10.7476/9789978108260', '9789978108260', 'https://books.scielo.org/id/4kqtv', 'https://books.scielo.org/id/4kqtv/pdf/tatiana-9789978108260.pdf', NULL, 'https://books.scielo.org/id/4kqtv/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4krgb', '4krgb', 'Machado de Assis e o cânone ocidental: itinerários de leitura', NULL, '["Sonia Netto Salomão"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Por um cânone machadianoSão todos meus irmãos, não são jornais nem deslizar de lancha entre camélias: é toda a minha vida que joguei.Carlos Drummond de Andrade.Os itinerários de leitura percorridos para a realização deste estudo levam a um ponto comum: a busca extraordinária de um modelo por parte de Machado de Assis ao longo do seu trajeto literário.Na leitura e reescritura dos cânones efetuadas pelo escritor carioca é como se houvesse a ratificação de um elemento permanente que o leitor, por sua vez, reconhece.Não resta dúvida que Machado confrontou-se com diversos modelos do cânone ocidental e realizou uma síntese original a partir de processos mistos de rejeição, desconstrução, adaptação, tradução ou fusão.No entanto, não foi nosso objetivo realizar uma pesquisa exaustiva dos modelos com os quais se confrontou o escritor carioca, mas, sim, desvelar os mecanismos de construção da sua obra em diálogo com diversos contextos: da literatura clássica à moderna, da música ao teatro, do jornalismo à política.Diálogo que se estendeu ao leitor-crítico e ao próprio autor que se observa enquanto escreve os seus textos.Por outro lado, ao falar de cânone ocidental, não queremos com isso negar a presença da cultura africana ou da oriental, de Introdução: Por um cânone machadiano Qualquer proposta para o cânone machadiano deve levar em conta o trabalho metaliterário realizado pelo autor das Memórias póstumas.Como um moderno hipertexto, os seus romances autorizam o confronto com os grandes modelos, mas a eles dão uma resposta original, jamais subalterna.Jogo, estratégia e cambalhota dialética delineiam uma obra cuja marca principal, do ponto de vista histórico, está na capacidade de apreensão psicossocial da ação humana no contexto complexo e multicultural do Brasil do segundo Oitocentos.Do ponto de vista temático, adiantando de modo sintético o que desenvolvemos a seguir, encontraremos: vida e morte, ciúme e vaidade, loucura e melancolia, verdade e aparência, além da análise antropológica, histórica e política do patriarcalismo brasileiro.Do ponto de vista estrutural: memorialismo, pacto ficcional, despistamento e suspense, ironia, jogos de duplos e falsetes, alteridade dos códigos ideológicos e linguísticos, paródia, pastiche e mistura de gêneros.Quanto ao método, realizei uma integração de vários processos teóricos, interrogando muito a intertextualidade e o que vai para além dela, num diálogo constante com a crítica, nacional e estrangeira.Mas, a um certo ponto, não há como não citar o mestre, "que isto de método, sendo, como é, uma coisa indispensável, todavia é melhor tê-lo sem gravata nem suspensórios".O zigue--zague narrativo da obra machadiana provocou um zigue-zague crítico.Os capítulos aqui elencados se entrecruzam e dialogam entre si porque fazem parte de um todo articulado pela relação obra-crítica.Roma, 7 de dezembro de 2015.este último, referido en passant e, portanto, não estudado de forma exaustiva.Mais do que qualquer coisa, Caldwell sugeriu, no seu confronto do romance machadiano com o drama shakespeariano, que "na peça de Shakespeare, o amor de Otelo é atacado de fora pela inveja, o ódio e o dolo de Iago: em Dom Casmurro, a disputa tem lugar dentro do mesmo homem".12 A partir daí, o caminho para análises que interrogassem as instâncias relativas ao narrador em primeira e em terceira pessoa e as questões relativas à intertextualidade estava aberto, e, efetivamente, surgiram trabalhos ou foram traduzidos alguns de nítido débito para com Caldwell, como Machado de Assis, impostura e realismo, de J. Gledson; O olhar oblíquo do bruxo, de M. de Senna; O enigma do olhar e Brás Cubas em três versões, estudos machadianos, de A. Bosi, e textos relativos às fontes e à intertextualidade como o de Rouanet, sobre o modelo shandiano, e os de Pinheiro Passos, sobre as fontes francesas.13 É verdade que a crítica brasileira anterior já havia fornecido pistas, sugestões e válidas interpretações, antes de 1960.Afrânio Coutinho propôs a "teoria do molho", contida num aforismo do próprio autor carioca, para exprimir a sua teoria da originalidade em literatura: "pode-se ir buscar a especiaria alheia, mas há de ser para temperá-la com o molho de sua fábrica".(OC, II: 731).14 Eugênio Gomes levantou as fontes inglesas; e tanto Augusto Meyer como Otto Maria Carpeaux deixaram notas importantes sobre o trabalho das fontes, como, aliás, todos os demais grandes críticos machadianos.Ao longo de sua obra, no entanto, Machado mostrou como "ler" os seus romances, chamando a atenção, no Esaú e Jacó, para essa instância crítica:', '["Machado de Assis","Western canon","literary canon","literary models","Parnassianism","Romanticism","intertextuality","Brazilian literature","19th-century Brazilian literature"]', '10.7476/9786599036484', '9786599036484', 'https://books.scielo.org/id/4krgb', 'https://books.scielo.org/id/4krgb/pdf/salomao-9786599036484.pdf', NULL, 'https://books.scielo.org/id/4krgb/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4kvdv', '4kvdv', 'A literatura na língua do outro: Jacques Derrida e Abdelkebir Khatibi', NULL, '["Maria Angélica Deângeli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A autora se debruça sobre uma questão clássica no campo da literatura, que é o sentido e o papel da linguagem em obras escritas em outra língua, que não a materna, exercício de proposital errância de identidade que atraiu escritores do porte de Samuel Beckett, Paul Celan, Elias Canetti, Franz Kafka, Eugène Ionesco, Vladimir Nabokov,Guillaume Apollinaire e Joseph Conrad, apenas para citar alguns. No trabalho, são analisados dois textos que, para a pesquisadora, problematizam bastante bem a definição do que é essa língua não-materna na escrita literária: “Amour Bilingue” (1983/1992), do marroquino Abdelkebir Khatibi, e “Le monolinguisme de l’autre” (1996), do judeu argelino e francês por adoção Jacques Derrida. Este último foi traduzido para o árabe justamente por Khatibi, com quem ele dialogava incessantemente. Para a pesquisadora, os dois autores têm em comum mais do que a proveniência magrebina e o fato de escreverem em uma língua distinta da de seus países de origem. A afinidade entre eles se manifestaria ainda mais no trabalho refinado do pensamento – rigorosamente dentro de uma tradição que poderia ser chamada de francesa -, no cultivo do amor pela língua e pela literatura e também no conflito de identidades colocado por esta maneira radical de se estar no mundo, balizas para uma profícua discussão sobre o pertencimento e sobre a língua.', '["Jacques Derrida","Abdelkébir Khatibi","multilingualism in literature","language and identity","Arabic translation","Maghrebi literature","sense of belonging","otherness"]', '10.7476/9786557144947', '9786557144947', 'https://books.scielo.org/id/4kvdv', 'https://books.scielo.org/id/4kvdv/pdf/deangeli-9786557144947.pdf', NULL, 'https://books.scielo.org/id/4kvdv/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4kx2t', '4kx2t', 'Pessoas muito especiais: a construção social do portador de deficiência e a reinvenção da família', NULL, '["Fátima Gonçalves Cavalcante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Buscar histórias de sucesso entre famílias de deficientes mentais, formar uma visão integral do paciente que ultrapasse a doença e confortar os pais que são surpreendidos pelo nascimento de uma criança especial são os objetivos que motivaram a autora a iniciar o desafio de contribuir para inovar a área da saúde, cada vez mais voltada para a questão social. Em uma abordagem transdisciplinar que inclui antropologia, etnografia, psicologia e saúde pública, ela consegue obter uma abordagem integral dos portadores de deficiência, tendo por base a capacidade criativa dos pacientes e de suas famílias no empenho em superar a doença. Mais do que um relato médico, o resultado é uma narrativa comovente, que provoca reflexões sobre a própria vida.', '["intellectual disability","families of people with disabilities","social construction of disability","success stories","parents of children with disabilities","patient narratives","transdisciplinarity","social health"]', '10.7476/9788575416082', '9788575416082', 'https://books.scielo.org/id/4kx2t', 'https://books.scielo.org/id/4kx2t/pdf/cavalcante-9788575416082.pdf', NULL, 'https://books.scielo.org/id/4kx2t/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4m8rx', '4m8rx', 'BR-163 em 5 tempos: uma abordagem geo-foto-gráfica', NULL, '["Messias Modesto dos Passos"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O tema e o conteúdo do livro BR-163 em 5 tempos: uma abordagem geo-foto-gráfica têm caráter essencialmente geográfico, o que desperta o interesse não somente de geógrafos, mas também de profissionais de outras áreas de conhecimento e interessados no tema da Amazônia Brasileira. A análise desenvolvida pelo autor está centrada num dos conceitos chaves da Geografia que é o de paisagem, o qual é empregado no decorrer de toda a obra como ferramenta de diálogo entre as ciências naturais e as ciências sociais em torno de questões socioambientais que envolvem a BR-163. A obra mostra, por meio de fotos e mapas, como a ‘paisagem geo-foto-gráfica’ se constitui num indicador dos processos de antropização de territórios emergentes e como a paisagem pode ser uma ferramenta de análise das dinâmicas espaciais na interface natureza-sociedade, a partir de processos relacionados à ocupação, à instalação de atividades econômicas, à atuação de órgãos governamentais, à marginalização de colonos pobres atraídos para a região e ao comprometimento da sobrevivência de populações indígenas nas áreas situadas nas zonas de influência do eixo da BR-163, entre Cuiabá e Santarém.', '["BR-163 highway","landscape","socio-environmental problems","spatial dynamics","indigenous peoples","Brazilian Amazon"]', '10.7476/9786587626130', '9786587626130', 'https://books.scielo.org/id/4m8rx', 'https://books.scielo.org/id/4m8rx/pdf/passos-9786587626130.pdf', NULL, 'https://books.scielo.org/id/4m8rx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4mpt8', '4mpt8', 'Texturas do sofrimento emocional', NULL, '["Litza Andrade Cunha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A depressão deve se tornar a doença mais popular do mundo dentro de 20 anos, já sendo chamada de epidemia silenciosa, segundo a Organização Mundial da Saúde. Esta doença é um dos assuntos relacionados ao tema deste livro, que trabalha com o estudo do “sofrimento emocional”, desviando da tendência biomedicista dos estudos médicos e culturalistas das ciências sociais. O título assume o pressuposto de que tanto a natureza quanto a cultura fornece importantes respostas para a questão do sofrimento emocional em sua abrangência.', '["emotional pain","depression","nature and culture","critique of biomedicine","silent epidemic","nature-culture dualism"]', '10.7476/9788523220082', '9788523214364', 'https://books.scielo.org/id/4mpt8', NULL, NULL, 'https://books.scielo.org/id/4mpt8/cover/cover_thumbnail.jpeg', 140, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4ndgv', '4ndgv', 'Reforma sanitária Brasileira: contribuição para a compreensão e crítica', NULL, '["Jairnilson Silva Paim"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Reforma Sanitária Brasileira como um fenômeno sócio-histórico Pensando a sociedade e o estado no Brasil Conjuntura da transição democrática: da criação do Cebes à Constituição O nascimento do Cebes O Programa Nacional de Serviços Básicos de Saúde (Prev-Saúde) O Plano de Reorientação da Assistência Médica no Âmbito da Previdência Social (o Plano do Conasp) As Ações Integradas de Saúde (AIS) A 8ª Conferência Nacional de Saúde A Comissão Nacional da Reforma Sanitária (CNRS) Sistema Unificado e Descentralizado de Saúde (SUDS) O processo constituinte Reforma Sanitária como objeto de reflexão teórico-conceitual Concepções de saúde Concepções de práticas de saúde e de organização de serviços', '["Brazilian health reform","health system organization","Cebes","National Health Conference","CNRS","sustainable urban drainage systems","democratic transition","social security","health care organization"]', '10.7476/9788575413593', '9788575413593', 'https://books.scielo.org/id/4ndgv', 'https://books.scielo.org/id/4ndgv/pdf/paim-9788575413593.pdf', NULL, 'https://books.scielo.org/id/4ndgv/cover/cover_thumbnail.jpeg', NULL, 162, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4nktq', '4nktq', 'Febre amarela: a doença e a vacina, uma história inacabada', NULL, '["Jaime Larry Benchimol"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resgata a história da produção da vacina contra a febre amarela, desde 1937, permitindo uma revisão dos ensinamentos de Oswaldo Cruz. Esta obra interessa não só ao leitor estudioso da febre amarela, mas também aos que querem saber mais sobre o desenvolvimento da vacina e dos estudos e estratégias de imunização. Além de rever aspectos técnicos, o livro traz informações sobre os estudos realizados, colaborando com pesquisas futuras. Ao se associar à Casa de Oswaldo Cruz e promover este trabalho, na celebração de seus 25 anos, Bio-Manguinhos reconhece a importância da pesquisa histórica, considerando-a como perspectiva para a compreensão das instituições e seus atuais desafios. Prêmio Jabuti 2002: Menção Honrosa na Categoria Ciências Naturais e Ciências da Saúde', '["yellow fever","yellow fever vaccine","vaccine development history","Oswaldo Cruz","Casa de Oswaldo Cruz","vaccination strategies","history of immunology","history of public health","Bio-Manguinhos"]', '10.7476/9788575413951', '9788575413951', 'https://books.scielo.org/id/4nktq', 'https://books.scielo.org/id/4nktq/pdf/benchimol-9788575413951.pdf', NULL, 'https://books.scielo.org/id/4nktq/cover/cover_thumbnail.jpeg', NULL, 75, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4pqtd', '4pqtd', 'O canto de Graúna: uma poética da heterogeneidade nas literaturas indígenas brasileiras contemporâneas', NULL, '["Randra Kevelyn Barbosa Barros"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A prática escritural desenvolvida por indígenas mostra que esse registro literário é um instrumento relevante na busca pela autonomia em um processo no qual se tornar agente de sua produção contribui para desconstruir a objetificação e os estereótipos frequentes na representação elaborada pelo olhar alheio. Graça Graúna, autora de origem potiguara, se insere dentro desse movimento de protagonismo e ativismo literário. No entanto, a escritora foge do paradigma associado à literatura de autoria indígena no Brasil na medida em que também aborda discussões que não estão diretamente ligadas à sua identidade potiguara.', '["Indigenous literature","heterogeneity","literary autonomy","indigenous writing","stereotypes","representation of indigenous peoples","literary activism"]', '10.7476/9786588211649', '9786588211403', 'https://books.scielo.org/id/4pqtd', 'https://books.scielo.org/id/4pqtd/pdf/barros-9786588211649.pdf', 'https://books.scielo.org/id/4pqtd/epub/barros-9786588211649.epub', 'https://books.scielo.org/id/4pqtd/cover/cover_thumbnail.jpeg', 217, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4pr8q', '4pr8q', 'Zoológicos humanos: gente em exibição na era do imperialismo', NULL, '["Sandra Sofia Machado Koutsoukos"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A partir de meados do século XIX, a exibição de pessoas em museus, circos, zoológicos, feiras e instituições científicas se tornou mais frequente no Ocidente, como forma de entretenimento e objeto de estudo. As correntes de pensamento racial da época estabeleciam hierarquias e colocavam negros, índios e outros povos colonizados no início de escalas da evolução humana. Exibidos ao vivo por meses a fio junto a elementos de sua cultura material, os diversos grupos eram apresentados como primitivos para contrastar com as nações mais ricas. Tais exposições ajudavam a dar crédito à noção de inferioridade racial e ensinavam ao público que o racismo era científico, terminando por incutir novos sentimentos de superioridade no branco e ocidental, justificando e desculpando o crescente imperialismo.', '["human zoos","human exhibits","racial thought","scientific racism","imperialism","circus","museums","racial hierarchy","colonial peoples","Black people","indigenous peoples","human evolution"]', '10.7476/9786586253313', '9786586253320', 'https://books.scielo.org/id/4pr8q', NULL, NULL, 'https://books.scielo.org/id/4pr8q/cover/cover_thumbnail.jpeg', 411, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4pshm', '4pshm', 'A construção da notícia: interseções entre jornalismo e comunicação estratégica', NULL, '["Claudiane de Oliveira Carvalho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra objetiva analisar a construção da notícia na articulação entre jornalismo e comunicação estratégica, investigando o impacto dessa relação na tessitura da informação. Que contratos são estabelecidos? Como são definidos os critérios de noticiabilidade? Como se consegue o efeito de sentido de verdade? Em busca de respostas a essas questões, a autora conecta três domínios do conhecimento – a análise do discurso, a hermenêutica e as teorias do jornalismo -, transformando suas fronteiras em membranas. Além disso, reflete sobre a configuração do discurso informativo numa zona de convergência, que é constituída no processo de agendamento público e tem implicações na construção social da realidade.', '["news production","journalism","strategic communication","news values","truth effect","public agenda setting","social construction of reality","discourse analysis","hermeneutics","journalism theory"]', '10.7476/9786556301808', '9786556301808', 'https://books.scielo.org/id/4pshm', 'https://books.scielo.org/id/4pshm/pdf/carvalho-9786556301808.pdf', NULL, 'https://books.scielo.org/id/4pshm/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4q4z4', '4q4z4', 'Saúde Indígena em perspectiva: explorando suas matrizes históricas e ideológicas', NULL, '["Carla Costa Teixeira","Luíza Garnelo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Compreender a atual política pública de saúde indígena à luz de seus antecedentes: com este objetivo, pesquisadores de diferentes especialidades e regiões do país se reuniram para produzir esta coletânea, que busca aumentar a visibilidade das vozes indígenas no cenário sociopolítico brasileiro. Os capítulos oferecem um panorama bastante consistente sobre o campo da saúde indígena no Brasil. O livro analisa o contexto político e institucional que originou o SUS e, particularmente, o Subsistema de Saúde Indígena. Assinala as diferenças e as dificuldades, mas também aponta caminhos de articulação possíveis entre o sistema médico oficial e o sistema indígena. Mais: corrobora a importância do diálogo para estabelecer interações criativas e, sobretudo, “contribuir com a provisão de uma atenção sanitária culturalmente sensível".', '["Indigenous health","health policy","health policy history","indigenous voices","culturally sensitive care","Brazil"]', '10.7476/9788575415825', '9788575414491', 'https://books.scielo.org/id/4q4z4', 'https://books.scielo.org/id/4q4z4/pdf/teixeira-9788575415825.pdf', 'https://books.scielo.org/id/4q4z4/epub/teixeira-9788575415825.epub', 'https://books.scielo.org/id/4q4z4/cover/cover_thumbnail.jpeg', 262, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4qcts', '4qcts', 'Nos limites da ação: preconceito, inclusão e deficiência', NULL, '["Elizabeth Tunes","Roberto Bartholo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O livro apresenta o tema da inclusão em seu caráter multifacetado, e sua leitura, na perspectiva do pensamento complexo, torna-se extraordinariamente rica. As dimensões econômica, histórica, sociológica, tecnológica e, especialmente, ética da inclusão vão se mostrando para o leitor, ao longo da leitura de uma única obra, em diferentes momentos, de diferentes formas e com diferentes nuances, em uma tessitura que permite refletir a inclusão em sua complexidade, em suas possibilidades e impossibilidades, constituindo, assim, um importante contraponto às representações dominantes relativamente utópicas, fragmentadas e simplistas, atualmente em muitos cenários, especialmente no contexto educativo. A partir das interessantes análises realizadas sobre preconceito, inclusão e deficiência, emergem, com clareza, os limites da ação, os quais obrigam a pensar em reformulações e novas estratégias, nem sempre explicitadas, porém, implicitamente sugeridas para serem pensadas. Esta é uma obra revolucionária pelo seu caráter subversivo e desafiador; criativa pela sua própria natureza e pelas possibilidades que abre para novas reflexões e ações. Foge, com acerto, da repetição, da fragmentação, da simplificação e do reducionismo que caracteriza, infelizmente, boa parte da produção científica nesse campo e, por isso, sua leitura pode constituir um bom incentivo para todos aqueles que, sensibilizados com a complexidade da inclusão, querem fazê-la possível.', '["inclusion","prejudice","disability","limits of action","ethics of inclusion","inclusive education","complexity","social inclusion"]', '10.7476/9788576003649', '9788576003649', 'https://books.scielo.org/id/4qcts', NULL, NULL, 'https://books.scielo.org/id/4qcts/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4qtk5', '4qtk5', 'A formação do Candomblé: história e ritual da nação jeje na Bahia', NULL, '["Luís Nicolau Parés"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Reconstruindo a trajetória dos povos jejes, o autor discute aspectos importantes da formação de identidades étnicas dos africanos na diáspora, mostrando como os cultos aos voduns dos jejes forneceram as bases para a formação do candomblé baiano. A narrativa cruza elementos da história e da antropologia, caminhando da África para o Brasil e do passado para o presente, numa escrita densa e envolvente.', '["Candomblé","African diaspora","ethnic identity formation","Vodun","Afro-Brazilian religions","ritual","Bahia"]', '10.7476/9788526814981', '9788526814646', 'https://books.scielo.org/id/4qtk5', NULL, NULL, 'https://books.scielo.org/id/4qtk5/cover/cover_thumbnail.jpeg', 421, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4qwjt', '4qwjt', 'Acuerdos comerciales y aspectos relacionados con el comercio exterior', NULL, '["Germán Pardo Carrero"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La globalización del comercio es una realidad cotidiana por la que se luchó durante décadas por parte de varios países hasta que finalmente se impuso. No obstante, la actual crisis económica mundial, la situación de sectores como la agricultura, los textiles y el vestido, la existencia de cerca de 300 acuerdos comerciales, problemas de seguridad de los países y la lucha contra el terrorismo, entre otras causas, han puesto sobre la palestra la liberalización del comercio y el rol de las aduanas y de las instituciones del derecho aduanero que, de facilitadores del comercio, pasan o pueden pasar a convertirse en verdaderos arsenales de medidas contra el libre comercio, con barreras no siempre conocidas o fácilmente identificables. Así, se hace necesario el estudio de esta problemática, partiendo de lo que se establece desde los entes reguladores del comercio mundial y las aduanas –OMC y OMA− y los acuerdos comerciales hasta el estudio de las barreras que se imponen al tráfico comercial. Y, tratándose de un tema del interés de todos los países, qué mejor que conocerlo o repasarlo de la mano de profesores de varios países, entendiendo que el mismo se basa en buena parte en normas internacionales, algunas de las cuales están armonizadas, lo que hace indispensable conocer las opinión y la experiencias de expertos venidos de diferentes lugares además de la postura de los profesores nacionales. Para esta oportunidad se cuenta con conferencistas de Argentina, Colombia, Ecuador, España, Perú y Venezuela.', '["trade agreements","international trade","trade liberalization","customs administration","customs law","World Trade Organization","Organization of American States","trade barriers","trade globalization","international trade law"]', '10.7476/9789587384956', '9789587384949', 'https://books.scielo.org/id/4qwjt', NULL, NULL, 'https://books.scielo.org/id/4qwjt/cover/cover_thumbnail.jpeg', 802, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4r', '4r', 'A construção da universidade baiana: origens, missões e afrodescendência', NULL, '["Edivaldo M. Boaventura"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra traz como questão central mostrar a formação do sistema estadual de educação superior na Bahia. O tema, que articula contextos local, regional e nacional, está estruturado em três blocos. O primeiro trata do surgimento das faculdades e universidades, destacando a origem do sistema estadual de educação na Bahia, entre 1968-1991. No segundo bloco, o livro aborda as experiências no exterior como título que agrupa as oportunidades de qualificação e intercâmbio, ressaltando experiências de cooperação com o Canadá, França, Estados Unidos e Portugal. No seu último bloco o Professor Boaventura faz uma análise sobre a Educação dos afrodescendentes, resgatando um tema vital da sociedade contemporânea, motivado pela necessidade de educação de largo contingente afro-baiano.', '["university history","state university systems","university founding","international academic cooperation","study abroad","Afro-Brazilian education","Boaventura de Sousa Santos","Bahia"]', '10.7476/9788523208936', '9788523208936', 'https://books.scielo.org/id/4r', 'https://books.scielo.org/id/4r/pdf/boaventura-9788523208936.pdf', NULL, 'https://books.scielo.org/id/4r/cover/cover_thumbnail.jpeg', NULL, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4r8s5', '4r8s5', 'Memórias de quem ensina história: cultura e identidade docente', NULL, '["Emery Marques Gusmão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resultado de pesquisa realizada pela autora, tendo em vista suas dúvidas e inquietudes como professora da rede oficial do ensino e estudiosa da História, esta obra aborda diferenças entre o ensino na década de 1960 e o contemporâneo, discorrendo a respeito de aproximações e distanciamentos entre o professor do passado e o do presente. Discute a idéia de que a escola antiga não é nem melhor, nem pior do que a atual, mas diferente, por trabalhar com outra clientela, outra cultura histórica e docente e outros referenciais teóricos. Para os defensores da escola moderna, a "fase de ouro da escola pública" oferecia um ensino elitista e trabalhava conteúdos prontos de forma expositiva, sendo que o ensino atual não atinge a qualidade desejada porque os docentes são mal-remunerados, despreparados e resistem ao novo. Os professores mais antigos, considerados tradicionais, duvidam das novas propostas pedagógicas, afirmam que a escola está em decadência, por aprovar alunos sem conhecimento, e vêem com desconfiança teorias que postulam não haver verdades acabadas a transmitir e que consideram a pesquisa como princípio pedagógico.', '["history education","teacher identity","teacher culture","history teachers","public schools","teacher professional development"]', '10.7476/9788539303229', '9788571395466', 'https://books.scielo.org/id/4r8s5', NULL, NULL, 'https://books.scielo.org/id/4r8s5/cover/cover_thumbnail.jpeg', 181, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4rrff', '4rrff', 'A criança com asma e sua família: avaliação psicossomática e sistêmica', NULL, '["Dóris Lieth Peçanha"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra apresenta as teorias psicossomática e sistêmica, incluindo seus aspectos históricos e avanços recentes. Articula, de forma original, esses saberes em 20 casos clínicos (crianças sadias, asmáticas e famílias), utilizando-se dos instrumentos: entrevistas com pais e família; desenho em cores da família e teste das Fábulas, desenvolvidos ou adaptados para pesquisa e tratamento. Assim, oferece ferramentas válidas para avaliar e tratar questões diversas no âmbito individual e/ou familiar.', '["childhood asthma","psychosomatic assessment","systemic family therapy","family assessment","psychosomatic theory","parent interviews","clinical case studies"]', '10.7476/9788576004561', '9788576004561', 'https://books.scielo.org/id/4rrff', 'https://books.scielo.org/id/4rrff/pdf/pecanha-9788576004561.pdf', NULL, 'https://books.scielo.org/id/4rrff/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4ryc8', '4ryc8', 'Diplomacia em saúde e saúde global: perspectivas latino-americanas', NULL, '["Paulo Marchiori Buss","Sebastián Tobar"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Do encontro entre saúde e relações internacionais se originam os conceitos e práticas contemporâneos da saúde global e da diplomacia da saúde. Mas tal encontro só se estabeleceu em função do processo de globalização. A crise econômica sistêmica e global, expondo as brechas estruturais do capitalismo global, aprofundou as desigualdades preexistentes e, desde então, só vem se ampliando, com consequências sociais, econômicas e sanitárias gravíssimas, particularmente para os países pobres e para os pobres de todos os países. A crise abateu-se sobre os países da América Latina, e muitos progressos alcançados estão agora ameaçados, inclusive as conquistas no campo da saúde, que vem sendo profundamente afetada. Este livro procura explicar a saúde no cenário global; o que a molda social e economicamente; como o global dialoga com o regional e o local; como a governança global exerce impacto sobre a saúde; como transcorre a governança da saúde global; e que papel desempenha a diplomacia aplicada em prol de uma situação de saúde mais equitativa. A complexidade internacional tem colocado novos objetos e desafios sobre os quais os autores desta coletânea buscam refletir, na perspectiva da América Latina e Caribe: as desigualdades sociais e sanitárias profundas entre países e no interior destes; as crises humanitárias relacionadas com conflitos armados em diversas partes do mundo; as correntes migratórias na América Latina; as transformações nos padrões culturais que desafiam a visão do ‘normal’ em medicina e saúde pública; o comprometimento ambiental em escala planetária; e a proliferação de instituições multilaterais que incluem os problemas de saúde entre seus programas de cooperação, sem entretanto solucioná-los.', '["health diplomacy","global health","globalization","global health governance","health disparities","Latin America and the Caribbean","economic crisis","migration","environmental health","multilateral institutions","health equity"]', '10.7476/9786557080665', '9788575414972', 'https://books.scielo.org/id/4ryc8', NULL, NULL, 'https://books.scielo.org/id/4ryc8/cover/cover_thumbnail.jpeg', 654, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4s8hf', '4s8hf', 'Etnografías: procesos, experiencias y resistencias sociales', NULL, '["Fredy Aguilar Rodríguez"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Etnografías. Procesos experiencias y resistencias sociales es el resultado de la investigación realizada a partir del trabajo etnográfico y de la observación participante. Áreas marginales de Colombia y Ecuador en donde la vida cotidiana es compleja debido a las condiciones históricas, socioculturales, políticas y económicas, son centro de este estudio. Realidades ocultas -y comunes- en nuestros contextos latinoamericanos, salen a la luz en estas páginas. Sus actores, investigadores y etnógrafos, han logrado generar conocimientos situados “desde dentro” y desde el punto de vista del actor para comprender su cotidianidad, sus formas de pensar, sentir, actuar y creer. Este es un libro dónde la observación, la entrevista, los relatos de vida, el diario de campo. la conversación cotidiana, el dibujo y la pintura, han sido estrategias metodológicas que han permitido a los investigadores poder internarse e interiorizarse en la vida de los actores sociales. El tratamiento de problemas complejos no han sido un obstáculo: la ética, la sensibilidad y la serenidad metodológica han sido condiciones fundamentales para el desarrollo de los diferentes artículos de esta publicación.', '["ethnography","social resistance","marginalized communities","everyday life","participant observation","life stories","field diary","ethnographic research ethics","Colombia","Ecuador","Latin America"]', '10.7476/9789978105740', '9789978105740', 'https://books.scielo.org/id/4s8hf', 'https://books.scielo.org/id/4s8hf/pdf/uribe-9789978105740.pdf', NULL, 'https://books.scielo.org/id/4s8hf/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4sxkm', '4sxkm', 'Mário de Andrade e os mineiros: a carta como exercício crítico', NULL, '["Maria do Rosário Alves Pereira"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro investiga o papel exercido por Mário de Andrade como crítico literário em sua epistolografia para escritores(as) mineiros(as), de diferentes grupos e gerações, tais como Carlos Drummond de Andrade e Martins de Almeida; Henriqueta Lisboa e Oneyda Alvarenga; Fernando Sabino e Alphonsus de Guimaraens Filho, entre outros. Percebe-se que os escritores, ainda que acatassem as sugestões mariodeandradianas e, em grande medida, as colocassem em prática na confecção do texto literário, mantinham, ao mesmo tempo, uma postura crítica e autônoma em relação aos apontamentos que recebiam. Desenvolve-se o conceito de carta-crítica, fundamental para as leituras aqui empreendidas, a fim de delinear como Mário, por meio de sua “sinceridade”, procurava orientar seus correspondentes. Procura-se demonstrar que o meio epistolar funcionou como uma espécie de laboratório tanto para o escritor paulista quanto para os jovens que dele se aproximavam, pois nas cartas se encontram a gênese de obras e, sobretudo, discussões profícuas sobre o fazer literário, a arte, o papel do intelectual e o do próprio crítico. Ao final, fica demonstrado o valor literário e histórico-cultural imbuído nessa vasta correspondência, que, seguramente, agrega novos sentidos à memória literária brasileira.', '["Mário de Andrade","Carlos Drummond de Andrade","Fernando Sabino","literary criticism","role of intellectuals","epistolary culture"]', '10.7476/9788542302806', '9788542302806', 'https://books.scielo.org/id/4sxkm', NULL, NULL, 'https://books.scielo.org/id/4sxkm/cover/cover_thumbnail.jpeg', 404, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4szy8', '4szy8', 'Baía de todos os santos: aspectos oceanográficos', NULL, '["Vanessa Hatje","Andrade, Jailson B. de"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'Este livro agrega informações que subsidiam o entendimento da oceanografia da Baía de Todos os Santos. Propicia o embasamento científico para a interpretação de sua situação atual com vistas ao planejamento de futuros projetos de pesquisa e de ações gerenciais que venham a garantir a recuperação e a preservação de sua riqueza natural, como recifes de corais, estuários, manguezais, bem como a promoção da qualidade de vida das populações do Recôncavo Baiano.', '["Baía de Todos os Santos","oceanography","coral reefs","estuaries","mangroves","coastal ecosystem conservation","natural resource management","Recôncavo Baiano","marine biodiversity"]', '10.7476/9788523209292', '9788523209292', 'https://books.scielo.org/id/4szy8', 'https://books.scielo.org/id/4szy8/pdf/hatje-9788523209292.pdf', NULL, 'https://books.scielo.org/id/4szy8/cover/cover_thumbnail.jpeg', NULL, 66, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4t4wg', '4t4wg', 'A cidade que devora malocas: habitação popular e o espaço urbano de Porto Alegre (c. 1943 – c. 1973)', 'habitação popular e o espaço urbano de Porto Alegre (c. 1943 – c. 1973)', '["Álvaro Antônio Klafke","Rodrigo de Azevedo Weimer","Vinícius Reis Furini"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro trata da moradia popular na cidade de Porto Alegre no período entre 1943 e 1973, aproximadamente, enfocando as habitações que formaram conjuntos que se tornaram conhecidos como "vilas de malocas". Os autores investigam as semelhanças e diferenças em relação a localidades similares, como as "favelas" cariocas. Foram problematizados eventuais vínculos com o período escravista. Também são abordados aspectos como "cor" e "raça", estigmas sofridos e noções locais de justiça, mundos do trabalho e as representações sociais operadas pela imprensa. Entretanto, a linha mestra da análise do livro são os processos pelos quais os pobres da cidade foram "empurrados" progressivamente para áreas periféricas da cidade, por vieses econômicos e extraeconômicos, em uma política higienista de expulsão das regiões centrais. As "malocas" são relacionadas ao processo de crescimento urbano, demonstrando que, longe de ser fenômenos casuais, fazem parte necessária de seu desenvolvimento. Verificam-se, ainda, as iniciativas de resistência e a ineficácia dessa abordagem em relação à moradia da população pauperizada. São levantados alguns exemplos específicos do processo identificado de uma forma macroscópica, enfocando, inclusive, o caso de "vilas" hoje inexistentes, tais como a Doca das Frutas e a Caiu do Céu.', '["popular housing","Porto Alegre","urban periphery","urban expansion","favelas","stigma","local justice","working conditions","press representation"]', '10.7476/9786557252277', '9786557250747', 'https://books.scielo.org/id/4t4wg', NULL, NULL, 'https://books.scielo.org/id/4t4wg/cover/cover_thumbnail.jpeg', 210, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4t7sk', '4t7sk', 'Da feminilidade oitocentista', NULL, '["Elisa Maria Verona"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objeto desta obra de Elisa Maria Verona são os impactos das mudanças sociais sobre a condição feminina durante o Império de D. Pedro II, provocadas pela chegada da corte portuguesa ao Rio de Janeiro no início do século 19. A partir desse período, a cidade avança num processo intenso de urbanização, que inclui ruas calçadas, iluminação a gás, bondes, teatros, bailes, passeios públicos e repercute também nos hábitos e costumes do carioca, que passa a se familiarizar com os padrões europeus. Nesse cenário, nota a autora, alargou-se a paisagem social de “muita iaiá brasileira” e papéis mais tradicionais atribuídos à mulher foram recolocados. Isso porque a mulher tinha – e esta é a hipótese central da pesquisa – um papel a desempenhar no novo ambiente social que surgia. A mulher carioca abastada, conta Verona, abandonou a reclusão, passou a vestir-se e portar-se com mais elegância e procurou apurar “as prendas de espírito”. Esse comportamento veio a reboque da disposição de uma elite formada nas universidades de instruir seus moradores, algo que considerava fundamental para o processo civilizatório da nação. A autora examina o que se esperava da mulher nessa nova configuração social e aborda, ainda, o modo como a medicina da época forjou o espaço de legitimadora da verdade acerca da saúde dos indivíduos, analisando também como os textos médicos descreviam a mulher. A obra lança um olhar abrangente sobre as transformações então em curso sob diversos aspectos, como a relação entre o projeto de instrução da população carioca e as ações que objetivavam a construção do Estado imperial brasileiro, e a literatura oitocentista, outro fator importante para a construção de uma nação “mais civilizada”.', '["femininity","Brazilian Empire","Portuguese court in Rio de Janeiro","urbanization","women''s social roles","elite women","medicalization of health","civilizing mission","gender and social change"]', '10.7476/9786557144831', '9786557144831', 'https://books.scielo.org/id/4t7sk', 'https://books.scielo.org/id/4t7sk/pdf/verona-9786557144831.pdf', NULL, 'https://books.scielo.org/id/4t7sk/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4t94p', '4t94p', 'Consumos alimentares em cenários urbanos - múltiplos olhares', NULL, '["Daniela Menezes Neiva Barcellos","Fausto Amaro","Ricardo Ferreira Freitas","Shirley Donizete Prado"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea nasce no interior do Laboratório de Comunicação, Cidade e Consumo (LACON), grupo de pesquisa vinculado ao Programa de Pós-Graduação em Comunicação Social da Universidade do Estado do Rio de Janeiro (UERJ). Na condição de parceiro institucional, o LACON cumpre seu compromisso atendendo ao chamado da Rede Iberoamericana de Pesquisa Qualitativa em Alimentação e Sociedade (REDE NAUS) para investimentos na divulgação de estudos relativos a esse fértil tema: consumos alimentares em cenários urbanos. Além dos brasileiros, pesquisadores da Espanha, do México e da Argentina nos ajudam a melhor compreender a ideia de que os consumos alimentares definem e são definidos na subjetividade e nos valores que imprimem às mercadorias, sejam objetos ou humanos objetificados.', '["dietary intake","urban environment","food and society","consumer subjectivity","commodification of food","nutritional value"]', '10.7476/9786588808092', '9788559687514', 'https://books.scielo.org/id/4t94p', NULL, NULL, 'https://books.scielo.org/id/4t94p/cover/cover_thumbnail.jpeg', 468, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4txkf', '4txkf', 'Prefácio', NULL, '["Amilcar Araújo Pereira"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne contribuições variadas para o debate sobre a importância das narrativas como conhecimento, não como mera invenção ou versão para a disputa política. Tendo em vista a riqueza e a diversidade de narrativas apresentadas, o livro foi dividido em duas partes, sendo a primeira dedicada às várias formas de pensar o antirracismo no Brasil, da perspectiva da população negra. Há narrativas literárias, históricas, políticas e audiovisuais, entre outras, que servem como ponto de partida para a construção de uma educação antirracista e democrática na sociedade brasileira. A segunda parte do livro traz diversas possibilidades de discussão sobre as narrativas de (re)existência, desde a ideia de “narrativa como evidência”, passando por narrativas de povos Rom (ciganos), na Europa, de uma liderança indígena no Brasil, de pessoas LGBTQIA+ na historiografia, e finalizando com as narrativas de professores/as em seu trabalho no ensino de História.', '["anti-racism","Black population","anti-racist education","democratic education","indigenous leadership","history education","teacher narratives","Brazil"]', '10.7476/9788526815360', '9786586253894', 'https://books.scielo.org/id/4txkf', NULL, NULL, 'https://books.scielo.org/id/4txkf/cover/cover_thumbnail.jpeg', 318, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4v2zh', '4v2zh', 'La política entre nubes de incienso. La participación política de las asociaciones católicas laicas bogotanas (1863-1885)', NULL, '["Sindy Paola Veloza Morales"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este texto explora un campo de la historiografía colombiana poco atendido, buscando rescatar el papel de los laicos en la defensa de la fe y en la consolidación de un proyecto católico en un momento histórico de grandes tensiones entre el Estado liberal y la institución eclesiástica. Asimismo, pretende ser un aporte a la historia local, al enfocarse en la ciudad de Santafé de Bogotá, capital de los Estados Unidos de Colombia y centro de varias dinámicas nacionales. Esta investigación pretende articular modos de acción y organización, objetivos políticos y dinámicas coyunturales, para ofrecer una mirada completa de las sociedades católicas bogotanas, siendo conscientes, por supuesto, de las limitaciones temporales y regionales presente estudio.', '["political participation","Catholicism","Bogotá","liberal state","church-state relations","Catholic societies","19th-century Colombia","local history"]', '10.7476/9789587385045', '9789587385045', 'https://books.scielo.org/id/4v2zh', 'https://books.scielo.org/id/4v2zh/pdf/veloza-9789587385045.pdf', NULL, 'https://books.scielo.org/id/4v2zh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4v4qp', '4v4qp', 'O parto na luz do Daime: corpo e reprodução entre mulheres na Vila Irineu Serra', NULL, '["Juliana Nicolle Rebelo Barretto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-11-17', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Os leitores terão, nesta obra, acesso a aspectos-chave de uma discussão encarnada sobre autonomias, corpo gestante, grávido, parturiente e lactante e em situação de parto, saúde reprodutiva das mulheres das comunidades ayahuasqueiras e a complexas tramas da relação entre saúde, gênero, poder, espiritualidade e cuidados, no embalo de uma forte produção de saberes locais.', '["childbirth","women''s reproductive health","pregnant body","lactation","gender and power","spirituality","care","local knowledge"]', '10.7476/9786557081754', '9786557081402', 'https://books.scielo.org/id/4v4qp', NULL, NULL, 'https://books.scielo.org/id/4v4qp/cover/cover_thumbnail.jpeg', 256, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4v5z9', '4v5z9', 'Cartografias do envelhecimento na contemporaneidade: velhice e terceira idade', NULL, '["Mariele Rodrigues Correa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Desde a década de 1950, diversas pesquisas e estatísticas têm apontado o crescente envelhecimento da população mundial. O Brasil, acostumado a se representar como um país jovem, foi surpreendido com o aumento continuado dos mais velhos, como apontam os censos das últimas décadas, e está sendo forçado a encarar essa nova realidade, acrescentando a velhice no conjunto das preocupações e dos investimentos sociais. Com base em um vasto levantamento bibliográfico sobre o tema e na sua experiência de trabalho com grupos de idosos, a autora analisa o envelhecimento humano no cenário brasileiro como algo que ultrapassa os determinismos biológicos e a ação decisiva do tempo, sendo modelado também por imagens e sentidos criados pelo conhecimento científico e por políticas públicas do Estado. Além disso, ressalta que os estigmas relacionados à velhice cederam lugar a tentativas de representá-la como um período da vida que pode comportar atividades produtivas, realização de projetos e participação ativa no mercado de consumo e que a velhice não é um fato uno e inexorável, mas uma construção humana que abre margens para experiências e significações múltiplas', '["population aging","old age","third age","ageism","age stereotypes","social construction of old age","aging policy","older adults","active ageing"]', '10.7476/9788579830037', '9788579830037', 'https://books.scielo.org/id/4v5z9', 'https://books.scielo.org/id/4v5z9/pdf/correa-9788579830037.pdf', NULL, 'https://books.scielo.org/id/4v5z9/cover/cover_thumbnail.jpeg', NULL, 61, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4v6xv', '4v6xv', 'Vozes quilombolas: uma poética brasileira', NULL, '["Jônatas Conceição da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A poética brasileira estudada por Jônatas Conceição da Silva, com suas vozes quilombolas , foi escrita como Dissertação de Mestrado na Pós-graduação em Letras da Universidade Federal da Bahia, com a orientação da Dra. Florentina Souza. O trabalho deste hábil poeta e militante da causa negra foi defendido poucos meses atrás, quase no mesmo momento em que se dava o desfecho dos debates sobre a adoção de uma Política Afirmativa na Universidade. Ou seja, a aprova-ção de uma política de cotas para garantir o ingresso de estudantes afro-descendentes na UFBA e a aprovação da dissertação aconteceram quase ao mesmo tempo.', '["Brazilian poetry","Afro-Brazilian literature","affirmative action","university admission quotas","Afro-descendants"]', '10.7476/9788523212391', '9788523212391', 'https://books.scielo.org/id/4v6xv', 'https://books.scielo.org/id/4v6xv/pdf/silva-9788523212391.pdf', NULL, 'https://books.scielo.org/id/4v6xv/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4vbw2', '4vbw2', 'Entre palavras e armas: literatura e guerra civil em Moçambique', NULL, '["Ubiratã Roberto Bueno de Souza"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Guerra de agressão", "guerra de desestabilização", "guerra civil", "guerra dos dezasseis anos": o conflito bélico que se alastrou por Moçambique entre 1976 e 1992 recebeu diversos nomes e abordagens. Nesta obra, a crítica literária é o princípio investigativo sobre o qual a linguagem estética e tal conflito podem ser analisados como experiências sociais distintas, mas intrinsecamente entrelaçadas. Por isso, este não é um trabalho de verificação de como existe um conteúdo histórico que é ficcionalizado em maior ou menor grau por uma literatura mais ou menos comprometida, mas antes objetiva, sim, perceber como certas estruturas estéticas apresentam composições específicas que, se analisadas literariamente, e posteriormente interpretadas historicamente, expõem visões críticas e manifestações sociais que se colocam em articulação com hegemonias que disputam o poder sobre uma sociedade. Assim sendo, como obras literárias que elegeram a guerra como tema podem contribuir para uma abordagem contemporânea do conflito que considere a compreensão e adesão das populações afetadas? Entre palavras e armas: literatura e guerra civil em Moçambique é totalmente baseado nesta primeira inquietação. Por isso se compõe como uma crítica comparada e histórica de dois romances que tratam da guerra pós-independência: Os sobreviventes da noite (2008), do escritor Ungulani Ba Ka Khosa, e Neighbours (1995), da escritora Lilia Momplé. O trabalho é dividido em dois movimentos: no primeiro, a crítica se desenvolve através da análise literária das configurações estéticas dos romances, de modo que seja possível delinear hipóteses comuns e diferenciais de leitura para ambos; o segundo movimento trata de tomar as hipóteses de leitura e buscar interpretá-las historicamente, com o apoio de um diálogo interdisciplinar entre os estudos literários e a historiografia, a sociologia, a antropologia, a economia e a ciência política de Moçambique.', '["Mozambique civil war","war literature","post-independence conflict","Ungulani Ba Ka Khosa","neighbors","Lília Momplé","war fiction","literary criticism","comparative literary criticism","hegemony","Mozambique"]', '10.7476/9788568576922', '9788568576922', 'https://books.scielo.org/id/4vbw2', 'https://books.scielo.org/id/4vbw2/pdf/souza-9788568576922.pdf', NULL, 'https://books.scielo.org/id/4vbw2/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
