INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4z33j', '4z33j', 'Geografia e movimentos sociais: dos primeiros estudos à abordagem socioterritorial', NULL, '["Nelson Rodrigo Pedon"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro, de Nelson Rodrigo Pedon, fruto do trabalho de diversos pesquisadores, faz uma análise dos movimentos sociais sob a perspectiva geográfica, com base na formulação de movimentos socioespaciais e movimentos socioterritoriais. Quando ainda era estudante de geografia, o pesquisador decidiu investigar a forma como os moradores de um bairro da periferia se organizavam para, em busca de soluções para os problemas locais, chamar a atenção do poder público. Ele então deu início à sistematização de ideias que o induziram a propor uma hipótese: nas relações de poder que os homens estabelecem entre si, o espaço adquire condição de território; dessa forma, a ação política de grande parte da classe trabalhadora envolve a conquista do espaço – e, portanto, a delimitação de seu poder manifestado na forma de território amplia suas capacidades, permitindo maior controle sobre os processos que condicionam suas vidas. A partir dessa formulação e de pesquisas sobre reivindicações populares junto a uma associação de moradores, o autor estabeleceu a relação entre topografia, condições de vida e participação política, imprescindível para que ele pudesse refletir sobre a importância da Geografia na compreensão dos processos sociais, cuja questão fundamental, ele afirma, é essencialmente territorial. “Esta obra pode ser considerada como um esforço de afirmação da identidade da ciência geográfica no conjunto das ciências humanas”, escreve Pedon.', '["social movements","socioterritorial movements","territoriality","power relations","popular demands","neighborhood associations","political participation","urban periphery"]', '10.7476/9788539304189', '9788539304189', 'https://books.scielo.org/id/4z33j', 'https://books.scielo.org/id/4z33j/pdf/pedon-9788539304189.pdf', NULL, 'https://books.scielo.org/id/4z33j/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4zb7w', '4zb7w', 'Um aprendiz de ciência', NULL, '["Carlos Chagas Filho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Carioca ''da gema'', sofisticado cosmopolita, bem-humorado e, ao mesmo, profundamente tocado pela simplicidade e pelas tradições das pequenas cidades mineiras e do mundo rural, o cientista e humanista Carlos Chagas Filho deixou, neste Um aprendiz de ciência, um delicioso relato de vivências, reflexões e realizações que são o testemunho do que há de mais significativo, na segunda metade do século XX, quanto à presença brasileira no campo das relações entre ciência, cultura, nacionalidade e cidadania. A obra contém um belo encarte com fotos, cartas e textos que marcaram a vida do autor.', '["science and culture","citizenship","Brazilian science","science and society"]', '10.7476/9788575412473', '9788520910825', 'https://books.scielo.org/id/4zb7w', 'https://books.scielo.org/id/4zb7w/pdf/chagas-9788575412473.pdf', NULL, 'https://books.scielo.org/id/4zb7w/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4znpy', '4znpy', 'Os Jesuítas e o apostolado social durante a ditadura militar: a atuação do CEAS', NULL, '["Grimaldo Carneiro Zachariadhes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O estudo aborda a intervenção política da Companhia de Jesus na história recente do Brasil, particularmente no período da ditadura militar. A obra tem importância decisiva para a compreensão do que teria sido a atuação da Igreja Católica durante os anos de autoritarismo e violação dos direitos humanos. Ao estudar o Centro de Estudos e Ação Social (CEAS), contribui-se para dar relevância ao papel que essa instituição teve no enfrentamento da ditadura, trazendo como resultado uma pesquisa consistente, que agrega conhecimento novo e fornece elementos para a compreensão da atuação dos jesuítas na realidade particular da Bahia. O autor consegue, sem perder o rigor acadêmico, escrever elegantemente, evitando qualquer hermetismo. Pelas características do trabalho, pela metodologia utilizada, pelo rigor na apuração, esta obra é uma referência obrigatória a quem pretende entender o que foi a atuação da Companhia de Jesus durante a ditadura militar no Brasil.', '["Jesuits","social apostolate","military dictatorship","Catholic Church","human rights violations","church-state relations","Bahia"]', '10.7476/9788523208929', '9788523208929', 'https://books.scielo.org/id/4znpy', 'https://books.scielo.org/id/4znpy/pdf/zachariadhes-9788523208929.pdf', NULL, 'https://books.scielo.org/id/4znpy/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-4zvdn', '4zvdn', 'Isso (não) é muito Black Mirror: passado, presente e futuro das tecnologias de comunicação e informação', NULL, '["André Lemos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra é fruto de uma disciplina ministrada na Faculdade de Comunicação da UFBA e das discussões feitas em sala de aula. Ao longo dos capítulos, Lemos faz uma análise completa de cada um dos episódios ao longo das quatro temporadas da série. Episódios como “Urso Branco” e “Black Museum” trazem às páginas do livro discussões profundas sobre tecnologia, comunicação, justiçamento, sociedade do espetáculo, entre outras.', '["Black Mirror","science fiction television","communication technology","information technology","technology and society","justice","spectacle society"]', '10.7476/9788523218607', '9788523217082', 'https://books.scielo.org/id/4zvdn', NULL, NULL, 'https://books.scielo.org/id/4zvdn/cover/cover_thumbnail.jpeg', 164, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-52tf5', '52tf5', '“Desta para a melhor”: a presença das viúvas machadianas no Jornal das Famílias', NULL, '["Jaqueline Padovani da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A vasta contribuição de Machado de Assis ao longo dos 16 anos de circulação do Jornal das Famílias aponta para um conjunto literário que dispõe de cerca de oitenta contos veiculados, na maioria das vezes, de forma seriada. Majoritariamente endereçadas a um público leitor feminino, tais narrativas exploram temas relacionados ao amor e ao casamento, em conformidade com a natureza conservadora do próprio Jornal. Este livro enfatiza o cenário das núpcias explorado pelo impresso de Garnier a fim de que se possa analisar o trabalho feito por Machado no que concerne à temática da viuvez e à possível tomada de “liberdade” assumida pela mulher dentro dos limites sociais impostos pelo matrimônio no século XIX. Com base no estudo das publicações do Jornal e com as noções teóricas da História Cultural, foi possível notar que, apesar do “conservadorismo” apregoado pelo impresso, a figura da viúva machadiana ocupa espaços de modulação entre o teor moralista do periódico e o deboche crítico indiciado em algumas matérias da revista.', '["Machado de Assis","Jornal das Famílias","widows","marriage","love","women''s reading","cultural history","moralism","women''s freedom","Garnier"]', '10.7476/9788579836596', '9788579836596', 'https://books.scielo.org/id/52tf5', 'https://books.scielo.org/id/52tf5/pdf/silva-9788579836596.pdf', 'https://books.scielo.org/id/52tf5/epub/silva-9788579836596.epub', 'https://books.scielo.org/id/52tf5/cover/cover_thumbnail.jpeg', 325, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-52zqk', '52zqk', 'Zeis já: pelo direito à moradia e à cidade', 'pelo direito à moradia e à cidade', '["Lima, Adriana Nogueira Vieira","Teixeira, Aparecida Netto","Viveiros, Liana","Carvalho, Marcos Bau","Rosa, Thaís Troncon"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Trata-se de obra constituída em formato de livro, trazendo uma coletânea de textos elaborados a partir do diálogo com o Projeto Zeis Já!: pelo Direito à Moradia e à Cidade, realizado entre 2020 e 2024 em Salvador, concebido como uma campanha de comunicação de massa orientada pela articulação entre produção coletiva de conhecimento e formação. Nessa perspectiva, a composição articulada de textos de naturezas diversas produz e constrói repertórios populares e abre horizontes sobre a aplicação do instrumento de Política Urbana das Zonas Especiais de Interesse Social (ZEIS). Os textos apresentam, de maneira contextualizada, o desafio dessa experimentação, fazendo ainda uma retrospectiva histórica para compreender os sentidos atribuídos não apenas pela academia, mas também sob o olhar de lideranças e moradores de ZEIS.', '["right to housing","right to the city","urban policy","Salvador, Bahia","collective knowledge production","community participation"]', '10.7476/9788555921902', '9788555921230', 'https://books.scielo.org/id/52zqk', NULL, NULL, 'https://books.scielo.org/id/52zqk/cover/cover_thumbnail.jpeg', 262, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-549x2', '549x2', 'O romance histórico brasileiro contemporâneo (1975-2000)', NULL, '["Antônio R. Esteves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro aborda a trajetória do romance histórico e a reatualização do gênero na narrativa brasileira contemporânea, fazendo uso de um corpus diversificado, que privilegia aspectos fundamentais para a compreensão da diversidade e da multiplicidade do romance histórico brasileiro contemporâneo publicado a partir da década de 1970, como: as rupturas em relação ao romance histórico tradicional; a questão da metaficção historiográfica; o cânone e as vozes periféricas; e a revisão crítica da História do Brasil por meio do discurso ficcional (identidade nacional, o papel do intelectual e do escritor, a voz feminina e a voz dos marginalizados), pondo em questão aspectos ligados à literatura e espaços públicos, estudos culturais e transculturação.', '["historical fiction","contemporary Brazilian literature","historiographical metafiction","literary canon","national identity","role of intellectuals","women''s voices","marginalized voices","public space","cultural studies","transculturation"]', '10.7476/9788539304479', '9788539300198', 'https://books.scielo.org/id/549x2', NULL, NULL, 'https://books.scielo.org/id/549x2/cover/cover_thumbnail.jpeg', 288, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-54jvt', '54jvt', 'Identidades emergentes, genética e saúde: perspectivas antropológicas', NULL, '["Ricardo Ventura Santos","Sahra Elizabeth Gibbon","Jane Biltrão"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As novas tecnologias biomédicas têm impactos não só na saúde, mas também sociais, políticos, éticos e econômicos, o que coloca desafios para historiadores, filósofos, antropólogos e sociólogos. Reflexões e análises sobre o assunto são apresentadas nesta coletânea, cujos artigos abordam os mais variados fenômenos: os testes de ancestralidade genética, a polêmica sobre uso de embriões para produção de células-tronco, a gênese da loucura e da violência, diagnósticos moleculares, doação de sêmen e longevidade humana, assim como o papel da biomedicina na luta sindicalista e no reconhecimento de direitos de povos indígenas. “Através de diferentes enfoques, os textos abordam as múltiplas formas pelas quais a ciência (em especial a tecnociência contemporânea) contribui para moldar o mundo social em domínios como identificação pessoal, identidades nacionais e ações coletivas, inclusive na área da saúde”, resumem os organizadores. “Os textos aqui reunidos estão, em sua totalidade, voltados para as vinculações entre produção de conhecimento científico sobre a biologia humana e seus desdobramentos socioculturais e políticos.”', '["emerging identities","biomedical technology","genetic ancestry testing","stem cell research","molecular diagnosis","sperm donation","human longevity","indigenous rights","personal identity","national identity","collective action","human biology"]', '10.7476/9788575415184', '9788575415184', 'https://books.scielo.org/id/54jvt', 'https://books.scielo.org/id/54jvt/pdf/santos-9788575415184.pdf', NULL, 'https://books.scielo.org/id/54jvt/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-54nrh', '54nrh', 'Teatrematizar', 'afetações de uma professora de Matemática com escola, com teatro, com alunas, com...', '["Hannah Lacerda"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O título, Teatrematizar, diz da temática do trabalho: uma pesquisadora, professora de matemática, atriz com a perspectiva de problematizar o produzir matemática e teatro, não matematizando o teatro, nem teatralizando a matemática, mas buscando uma potência dessa articulação. Durante o caminhar, uma pergunta de pesquisa se constitui: Que pode um grupo de estudantes produzir como experiências educativas junto a um processo teatral? No intuito de experienciar os possíveis dessa pergunta, são traçados os objetivos: acompanhar um grupo de teatro, criado por alunas de uma escola da Rede Estadual Paulista de Educação; afetar-se com as possíveis experiências educativas, produzidas junto a um processo teatral e pensá-las junto à Educação (matemática). Uma pesquisa como experiência. Uma tese adolescente. Uma pesquisadora que se encontra no entre. Um jogo compositivo, uma brincolagem. Aproximações a um teatro cego. Para a leitura da tese, prepare-se com um cheiro que se lembre de casa, uma das tantas que você pode ter tido. Um perfume, uma vela, um incenso… Traga consigo uma bebida para brindar e algo para comer (quem sabe morangos?). Para o tato, deixo com você meu abraço.', '["mathematics education","educational experience","interdisciplinarity"]', '10.7476/9786559543786', '9786559543786', 'https://books.scielo.org/id/54nrh', 'https://books.scielo.org/id/54nrh/pdf/lacerda-9786559543786.pdf', NULL, 'https://books.scielo.org/id/54nrh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-56bv2', '56bv2', ': Quanta ciência há no ensino de ciências', NULL, '["Antonio Carlos Pavão","Denise de Freitas"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Esse livro inscreve-se no âmbito das temáticas atuais sobre ensino de Ciência, livro didático e prática docente. Destina-se principalmente a professores dos ensinos fundamental e médio, alunos de graduação e pós-graduação e demais interessados no tema, sendo um importante material de apoio aos cursos de formação inicial e continuada de professores. É resultado de um esforço coletivo de professores e pesquisadores de várias áreas de conhecimentos: Física, Química, Biologia, entre outras, de vários estados brasileiros: Ceará, Maranhão, Mato Grosso do Sul, Minas Gerais, Pará, Paraíba, Pernambuco, Rio Grande do Sul, Santa Catarina, São Paulo e Distrito Federal, que fizeram parte do processo de avaliação do Programa Nacional do Livro Didático - PNLD (2005). Em decorrência da diversidade de formação e atuação dos autores, o livro apresenta artigos com variadas perspectivas teóricas e diferentes níveis de aprofundamento, contemplando ideias bastante plurais sobre o ensino de ciências, o livro didático e a prática docente.', '["science education","textbooks","teaching practice","teacher professional development","K-12 education","science education theory"]', '10.7476/9788576003625', '9788576003625', 'https://books.scielo.org/id/56bv2', NULL, NULL, 'https://books.scielo.org/id/56bv2/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-56qxh', '56qxh', 'Iconografia: pesquisa e aplicação em estudos de Artes Visuais, Arquitetura e Design', NULL, '["Hernández, Maria Herminia Olivera","Lins, Eugênio de Ávila"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro materializa a multiplicação dos resultados do curso intensivo internacional Iconografia: pesquisa e aplicação em estudos de artes visuais, realizado no Museu de Arte da Bahia (MAB) coordenado pelo Programa de Pós-Graduação em Artes Visuais da Escola de Belas Artes da Universidade Federal da Bahia. São 13 artigos presentes na publicação de autoria de pesquisadores brasileiros e portugueses que se debruçam sobre o protagonismo da imagem, a linguagem figurativa, que se configura como ponto de partida para as análises iconográficas e diversas outras temáticas da área.', '["iconography","visual arts","architecture","design","figurative language","image analysis","iconographic analysis","visual language"]', '10.7476/9788523218614', '9788523218614', 'https://books.scielo.org/id/56qxh', 'https://books.scielo.org/id/56qxh/pdf/hernandez-9788523218614.pdf', NULL, 'https://books.scielo.org/id/56qxh/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-57gcv', '57gcv', 'De quem é esse corpo? A performatividade do gênero feminino no teatro contemporâneo – cruzamentos entre processos criativos das mulheres, cena e gênero', NULL, '["Lúcia Regina Vieira Romano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra analisa a criação teatral contemporânea das mulheres e questiona a caracterização dessa produção a partir do recorte de gênero feminino. A partir dos termos teatro feminino, teatro da mulher e teatro feminista, Lúcia Romano aponta as implicações deles na crítica e na prática teatrais, na cena nacional e internacional, e a necessidade de revisão dessa terminologia. A autora ressalta a atual multiplicidade de estratégias e poéticas particulares do teatro feito por mulheres, em especial, nas atuações de algumas performers, das atrizes criadoras integrantes do OdinTeatret e da rede internacional Magdalena Project. Observa ainda o progresso do teatro feminista internacional, nas criações dos teatros lésbico, feminista negro e multicultural. Para iluminar o complexo cruzamento entre corporeidade, processos criativos e subjetivação, a autora propõe a constituição de imagens encarnadas, em que a consciência de gênero gera corporeidades específicas na cena, e a análise do corpo sexuado, no processo de comunicação teatral. Por fim, projeta um teatro do andrógino, afeito à subversão de concepções binárias e capaz de encorpar a instabilidade das performances de gênero.', '["women''s theatre","feminist theatre","performativity","female gender","contemporary theatre","women playwrights","Odin Teatret","lesbian theatre","multicultural theatre","embodiment","gendered bodies","subjectivation"]', '10.7476/9788595461789', '9788595461789', 'https://books.scielo.org/id/57gcv', 'https://books.scielo.org/id/57gcv/pdf/romano-9788595461789.pdf', NULL, 'https://books.scielo.org/id/57gcv/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-57nhx', '57nhx', 'Nas asas da borboleta: filosofia de Bergson e educação', NULL, '["Rita Célia Magalhães Torreão"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra apresenta a Pedagogia da Duração em um texto poemático-filosófico. A partir das ideias de Bérgson, a autora fala sobre a linha tênue entre o fluir do tempo e o espaço sólido. Rita Célia reúne os conhecimentos adquiridos no ambiente acadêmico com sua vocação para a poesia e o resultado é um livro que vai além da pedagogia de Bérgson, utilizando-o apenas como um interlocutor.', '["Henri Bergson","time and space","philosophy of education","poetry and philosophy"]', '10.7476/9788523212001', '9788523212001', 'https://books.scielo.org/id/57nhx', 'https://books.scielo.org/id/57nhx/pdf/torreao-9788523212001pdf', NULL, 'https://books.scielo.org/id/57nhx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-583jd', '583jd', 'Identidade e cidadania: como se expressa o judaismo brasileiro', NULL, '["Helena Lewin"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A Universidade do Estado do Rio de Janeiro por intermédio de seu Programa de Estudos Judaicos, vinculado à Sub Reitoria de Extensão e Cultura, apresenta este volume intitulado Identidade e Cidadania: como se expressa o judaísmo brasileiro composto de textos que foram apresentados durante o III Encontro Brasileiro de Estudos Judaicos, realizado de 23 a 25 de Abril de 2002, nesta Universidade.[Trecho retirado da apresentação do livro]', '["Jewish identity","Jewish citizenship","Jewish studies"]', '10.7476/9788579820182', '9788579820182', 'https://books.scielo.org/id/583jd', 'https://books.scielo.org/id/583jd/pdf/lewin-9788579820182.pdf', NULL, 'https://books.scielo.org/id/583jd/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
