ication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-595cz', '595cz', 'De Clinton a Obama: políticas dos Estados Unidos para a América Latina', NULL, '["Luís Fernando Ayerbe"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os ensaios reunidos estudam as correntes de pensamento na formulação da política externa estadunidense após o fim da guerra fria e concepções estratégicas dos Estaos Unidos sobre a segurança internacional dos governos de Bill Clinton, George W. Bush e Barack Obama, Verifica ainda os interesses nacionais norte-americanos na América Latina entre 1993 e 2009, além de tratar dos cem primeiros dias do governo Obama.', '["US foreign policy toward Latin America","post-Cold War US foreign policy","Clinton administration","Bush administration","Obama administration","US national interests","international security","US-Latin American relations"]', '10.7476/9788595461949', '9788571399747', 'https://books.scielo.org/id/595cz', NULL, NULL, 'https://books.scielo.org/id/595cz/cover/cover_thumbnail.jpeg', 260, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5969x', '5969x', 'O harém ao rés do chão: imaginário europeu e representações médicas sobre o lugar-segredo, 1599-1791', NULL, '["Marina de Oliveira Soares"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No imaginário ocidental o harém primeiro fascina pelo mistério. Com efeito, a compreensão lendária das culturas do Médio Oriente incorpora uma visão de mulheres isoladas e restritas, à disposição da lascívia de seu senhor. E ainda que, em tempos mais recentes, estudos, relatos e ações tenham adentrado as questões postas pela condição feminina em países de cultura islâmica, contudo a imagem de sedução e dominação associada ao harém perdura com resiliência perturbadora. A historiadora Marina Soares procede a uma inovadora arqueologia desses conceitos, imagens e permanências. Ela percorre narrativas de viagens de europeus ao Império Otomano, Pérsia e Norte da África, publicadas em língua inglesa e francesa, remontando ao final do século XVI e prosseguindo até o final do século XVIII. Nesse cenário textual é possível seguir os rastros das representações do harém que ensejaram o imaginário de luxúria a compor a figuração das sociedades islâmicas. Dentre essas fontes cuidadosamente reunidas e analisadas, o último relato, publicado em 1791, destaca a experiência médica de um viajante inglês em dois haréns do Reino de Marrocos. Trata-se de documento privilegiado que permite recuperar nessa questão pontual o confronto das culturas: os pressupostos médicos europeus encontram as práticas médicas mouras – um encontro de perplexidades e trocas que a argúcia da investigadora traz à luz com fina maestria. O tema é muito pouco explorado pela pesquisa acadêmica sobre o Oriente, em geral mais voltada para estudos que, de alguma forma, possam instruir as questões políticas do presente. E, contudo, é na longa duração que a economia dos costumes enreda pacientemente o tecido da cultura – urdidura que dá sentido aos acontecimentos que convocam a atenção para as relações entre os povos. Este livro propicia o delicado desenlace dos atados mais profundos de nossa simbologia sobre o harém, um mistério desvelado como uma ficção instigante que nos convida a mirar em espelho nossas próprias quimeras.', '["harem","European imaginary","medical representation","Orientalism","travel writing","Ottoman Empire","North Africa","gender and sexuality","cultural encounter"]', '10.7476/9788568576816', '9788568576816', 'https://books.scielo.org/id/5969x', 'https://books.scielo.org/id/5969x/pdf/soares-9788568576816.pdf', NULL, 'https://books.scielo.org/id/5969x/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5997v', '5997v', 'Autogoverno e formação humana em tempos sombrios: aspectos éticos e políticos', NULL, '["Odair Neitzel"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, cujos textos se fundamentam em diferentes autores, aborda temáticas que procuram indicar a importância de um despertar do tempo presente, considerando a conjugação de outros tempos e a vivência de experiências coletivas que tenham significado à vida humana. É, dessa forma, de acordo com a ideia geral do livro, que a emergência de um cuidado de si poderá florescer. Conceitos como ética, política, poder, dignidade humana, educação, memória, contemporaneidade, formação humana, cuidado de si, biopoder, governamentalidade, entre outros, são problematizados e discutidos no livro. A diversidade dos conceitos refletidos faz parte da história do livro. As amplas discussões sobre formação humana e autogoverno foram sendo sistematizadas com o desenvolvimento do Projeto de Pesquisa “Políticas Educacionais e Autogoverno” e a partir dele. Trata-se de um projeto que se desenvolveu como fomento à linha de Pesquisa “Políticas Educacionais” do Mestrado em Educação da UFFS – Campus Chapecó, em parceria com o Grupo de Pesquisa “Educação, Filosofia e Sociedade (GPEFS)”, e com apoio da FAPESC.', '["self-government","human formation","ethics","politics","power","human dignity","education","memory","contemporaneity","care of the self","biopower","governmentality"]', '10.7476/9786586545364', '9786586545364', 'https://books.scielo.org/id/5997v', 'https://books.scielo.org/id/5997v/pdf/neitzel-9786586545364.pdf', NULL, 'https://books.scielo.org/id/5997v/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-59fv5', '59fv5', 'O sistema de justiça', NULL, '["Maria Tereza Sadek"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O principal objetivo deste texto é descrever e analisar o sistema de justiça, tal como ele é vivido pela população e por algum de seus integrantes. Procuraremos analisar o perfil dos principais agentes deste sistema e apontar \nos caminhos normalmente percorridos pelo cidadão que procura justiça. Para \nisto recorreremos fundamentalmente a observações qualitativas realizadas em comarcas de diferentes tamanhos e características. Utilizaremos também dados de fontes secundárias, muito embora eles só tenham a função de contextualizar o problema em discussão. [trecho retirado do capítulo "O sistema de justiça"]', '["justice system","public perception of justice","legal agents","judiciary","courts"]', '10.7476/9788579820397', '9788579820397', 'https://books.scielo.org/id/59fv5', 'https://books.scielo.org/id/59fv5/pdf/sadek-9788579820397.pdf', NULL, 'https://books.scielo.org/id/59fv5/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-59g2d', '59g2d', 'Matrizes interacionais: a comunicação constrói a sociedade', NULL, '["José Luiz Braga","Regina Calazans","Leon Rabelo","Caroline Casali","Micheli Machado","Paula Reis Melo","Rosana Cabral Zucolo","Ana Lúcia Medeiros","Pedro Benevides","Eloísa Joseane da Cunha Klein","Monalisa Pontes Xavier","André Dornelles Pares"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os processos comunicacionais são habitualmente “perguntados” a partir de angulações sociológicas, econômicas, lingüísticas, políticas (entre outras), direcionadas por premissas daqueles campos. Diversamente, nosso enfoque busca perguntas e ângulos de observação mais próximos de preocupações comunicacionais. Temos a premissa de que todos os processos sociais se desenvolvem tentativamente – a partir de problemas, necessidades e interesses inerentes ao próprio fato de compartilharmos o mundo da natureza e dos humanos. Este, apesar de apresentar capítulos com autores individualmente nomeados, não é uma coletânea de artigos. A obra é uma produção conjunta do Grupo de Pesquisa Dispositivos & Circuitos em Comunicação, com a composição indicada na capa (na ordem dos capítulos). Os trabalhos foram iniciados por um Seminário, em outubro de 2012, a partir da heurística, então em fase preliminar de elaboração, proposta por José Luiz Braga, Coordenador do Grupo.', '["communication and society","social processes","communication theory","heuristics"]', '10.7476/9788578795726', '9788578795726', 'https://books.scielo.org/id/59g2d', 'https://books.scielo.org/id/59g2d/pdf/braga-9788578795726.pdf', NULL, 'https://books.scielo.org/id/59g2d/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-59grm', '59grm', 'Agraristas políticos brasileiros', NULL, '["Raimundo Santos"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos que integram a I Parte deste livro provêm da pesquisa “Perfis agraristas brasileiros” ora em andamento no CPDA (Programa de Pós-graduação em Desenvolvimento, Agricultura e Sociedade), da UFRRJ, e cujo objetivo consiste em comparar autores da ver tente comunista com a matriz representada por José de Souza Martins, sociólogo que tem na reflexão de Florestan Fernandes sua referência básica. [trecho retirado do livro]', '["agrarian thought","political economists","José de Souza Martins","Florestan Fernandes","land reform"]', '10.7476/9788599662816', '9788599662816', 'https://books.scielo.org/id/59grm', 'https://books.scielo.org/id/59grm/pdf/santos-9788599662816.pdf', NULL, 'https://books.scielo.org/id/59grm/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-59hq6', '59hq6', 'Matérias da memória', NULL, '["Maria da Glória Bordini"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro se deve a uma experiência desenvolvida no Sul do Brasil, em torno de seu romancista mais mundialmente conhecido, Erico Verissimo. Partindo da preservação de sua documentação literária, outras iniciativas vieram à luz, e uma série de estudos e eventos acadêmicos, que envolveram muitos pesquisadores, docentes e discentes universitários de todo o país, deu corpo à expansão de tecnologias de gestão e difusão do que veio a ser chamado de “acervo literário”. O conjunto de trabalhos produzido por esse empreendimento memorial ultrapassa os limites desta coletânea, interessada em expor algumas das facetas da investigação de acervos, dirigida a várias áreas dos estudos sobre literatura. A dispersão e a pulverização dos estudos literários em aspectos muito delimitados da cena atual tornam difícil propor qualquer teorização sistêmica para a literatura. Uma das direções tomadas no pensamento teórico, hoje, é a da rediscussão, sob uma perspectiva não mais, ou não exclusivamente, marxista, da materialidade da literatura, buscando articulações da obra.', '["Erico Verissimo","literary archives","literary documentation","memory","materiality of literature"]', '10.7476/9786557251225', '9786557251225', 'https://books.scielo.org/id/59hq6', 'https://books.scielo.org/id/59hq6/pdf/bordini-9786557251225.pdf', NULL, 'https://books.scielo.org/id/59hq6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5b7hm', '5b7hm', 'Gênero, direitos e diversidade sexual: trajetórias escolares', NULL, '["Eliane Rose Maio","Crishna Mirella de Andrade Correa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta aspectos da discussão da sexualidade sob os pontos de vista da Educação, Psicologia e Direito, voltados a auxiliar a compreensão sobre as questões que envolvem o conceito de Gênero, as identidades de gênero e a diversidade sexual.', '["gender","sexual diversity","gender identity","sex education","educational trajectories","gender rights","gender psychology","gender and law"]', '10.7476/9788576286561', '9788576285281', 'https://books.scielo.org/id/5b7hm', NULL, NULL, 'https://books.scielo.org/id/5b7hm/cover/cover_thumbnail.jpeg', 213, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5bhdb', '5bhdb', 'Tópicos em Virologia', NULL, '["Lemos, Elba Regina Sampaio de","Lívia Melo Villar","Luciane Almeida Amado Leon","Guimarães, Monick Lindenmeyer","Teixeira, Sylvia Lopes Maia","Paula, Vanessa Salete de"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-05-24', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Incluindo os principais aspectos da virologia humana em um contexto de saúde global, o primeiro volume da Coleção BIo contribui para o conhecimento científico e para a compreensão de fenômenos relacionados à virologia, enfatizando a necessidade da integração homem-animal-meio ambiente-saúde. Os nove capítulos abordam aspectos relacionados a: biossegurança, diagnóstico, características gerais dos vírus, epidemiologia, viroses emergentes, prevenção, entre outros. Na vanguarda do conhecimento, reunindo áreas híbridas e multidisciplinares cruciais para o desenvolvimento científico e tecnológico do país, a coleção Bio está voltada para temas situados na interseção entre as pesquisas biológicas e biomédicas. Os conteúdos, em sua maioria inéditos em língua portuguesa, são apresentados em linguagem simples por especialistas com competência técnico-científica e experiência prática. Dessa forma, contribui para a atualização e a qualificação de profissionais em temas de referência em biociência e biotecnologia, estimulando o diálogo sobre conhecimento científico e inovações.', '["biosafety","viral diagnosis","virus properties","emerging viral diseases","disease prevention","global health"]', '10.7476/9786557082119', '9786557082119', 'https://books.scielo.org/id/5bhdb', 'https://books.scielo.org/id/5bhdb/pdf/lemos-9786557082119.pdf', NULL, 'https://books.scielo.org/id/5bhdb/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5bstp', '5bstp', 'Educação e divulgação científica: democratização de saberes na cibercultura', NULL, '["Alves, Verônica","Porto, Cristiane","Couto, Edvaldo"]', 'EDUEFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro aborda a Educação e a Divulgação Científica em um contexto mundial de pandemia causado pela Covid-19. No quadro pandêmico, diante das recomendações da Organização Mundial da Saúde (OMS), assumimos o afastamento social presencial e desenvolvemos estratégias de convivência por meio da aproximação social digital. Por conseguinte, as relações via internet se intensificaram, o mundo passou praticamente a funcionar de modo remoto via Rede Mundial de Computadores. Paralelamente, nós nos voltamos ansiosamente para a Ciência na esperança que explicasse e contornasse o problema estabelecido mundialmente. A Educação, a Ciência e a Divulgação Científica encontraram espaço fértil em redes sociais digitais como o Instagram, o Twitter, o TicTok, o Facebook e o Youtube, onde pessoas compartilham conteúdos e informações sobre a pandemia.', '["science communication","science education","democratization of knowledge","digital culture","COVID-19 pandemic","social networking sites","distance education","social distancing","online information sharing"]', '10.7476/9788555921179', '9786589524564', 'https://books.scielo.org/id/5bstp', NULL, NULL, 'https://books.scielo.org/id/5bstp/cover/cover_thumbnail.jpeg', 322, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5btwk', '5btwk', 'Teoria epidemiológica hoje: fundamentos, interfaces e tendências', NULL, '["Naomar de Almeida Filho","Maurício L. Barreto","Renato Peixoto Veras","Rita Barradas Barata"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Parte do princípio de que finalmente uma malaise epistemológica se instala na epidemiologia, determinada pela incômoda posição de principal responsável pelas contradições da saúde pública neste fim de milênio. Assim, convoca estudiosos e profissionais a questionar fundamentos, explorar interfaces e formular discursos competentes indicadores de tendências.', '["epidemiological theory","epistemology of epidemiology","interdisciplinary interfaces","research trends"]', '10.7476/9788575412794', '9788575412794', 'https://books.scielo.org/id/5btwk', 'https://books.scielo.org/id/5btwk/pdf/almeida-9788575412794.pdf', NULL, 'https://books.scielo.org/id/5btwk/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5d8tg', '5d8tg', 'Coleções biológicas científicas brasileiras: diagnóstico, prioridades e recomendações', NULL, '["Marinoni, Luciane","Basílio, Daniel Silva","André Luís de Gasper"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'Em 2021, o Ministério da Ciência, Tecnologia e Inovação (MCTI) solicitou à Sociedade Brasileira de Zoologia (SBZ) que coordenasse o projeto “O papel das Redes de Coleções Zoológicas no aprimoramento e preenchimento de lacunas taxonômicas e geográficas em bases de dados de acesso aberto” junto ao Edital Capacity Enhancement Support Programme (CESP) do Global Biodiversity Information. O projeto que contou com o financiamento do GBIF, visou fortalecer as coleções zoológicas, fornecendo diretrizes comuns e proporcionando capacitação em ferramentas de gestão para os curadores. Como parceiro do projeto, o nó português do GBFI apoiou as atividades de capacitação, particularmente nos temas de gestão de coleções, limpeza e qualidade de dados. Além do nó do GBIF Portugal, participaram do projeto os países africanos de língua portuguesa: Angola (nó do GBIF), São Tomé e Príncipe, Moçambique e Cabo Verde. Dando sequência às atividades do projeto CESP/SBZ, o MCTI encomendou à SBZ a ampliação do diagnóstico para todas as coleções biológicas científicas do Brasil, adicionando as coleções botânicas e microbiológicas. Este trabalho foi realizado em 2022 em cooperação com a Sociedade Botânica do Brasil (SBB), Sociedade Brasileira de Microbiologia (SBM), Sociedade Brasileira de Virologia (SBV) e sociedades constituintes do Fórum de Sociedades da área de Zoologia. Esse foi o primeiro inventário das coleções biológicas brasileiras acompanhado de um diagnóstico amplo, realizado com metodologia que possibilita a comparação entre as áreas da botânica, microbiologia e zoologia. Neste livro serão apresentados os dados do diagnóstico das coleções científicas brasileiras, nas áreas botânica, microbiologia e zoologia, levando em consideração as informações solicitadas pelo MCTI, relativos ao quantitativo de coleções e sua representação no catálogo do SiBBr, distribuição geográfica, porte, natureza jurídica, além das condições de gestão, infraestruturas física e de pessoal, digitalização dos acervos, acesso e qualidade.', '["zoological collections","plant collections","collection inventory","collection management","data quality","data cleaning","GBIF","collection digitization","Brazil","capacity building"]', '10.7476/9786587590066', '9786587590066', 'https://books.scielo.org/id/5d8tg', 'https://books.scielo.org/id/5d8tg/pdf/marinoni-9786587590066.pdf', NULL, 'https://books.scielo.org/id/5d8tg/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5dcq3', '5dcq3', 'A ironia e suas refrações: um estudo sobre a dissonância na paródia e no riso', NULL, '["Camila da Silva Alavarce"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro estuda os discursos caracterizados pela dissonância, mais especificamente, a ironia, a paródia e o riso. Foram privilegiadas as teorias de Schopenhauer, Baudelaire e Jean Paul, já que são estudos que proporcionam uma aproximação estrutural e filosófica entre os fenômenos do riso e os discursos irônicos e paródicos. Desse modo, tal qual a ironia e a paródia, esse riso é também fruto de uma dissonância, que instaura, ao invés da certeza, a possibilidade, em lugar do uníssono, o ambivalente. O estudo dos significativos pontos de contato entre a ironia, a paródia e o riso legitima a relevância do sujeito na decodificação desses discursos caracterizados pela ambigüidade. Para a sua análise a autora analisou os textos: "O homem duplicado" (2002), de José Saramago, "O cavaleiro inexistente" (1959), de Ítalo Calvino, e "O duplo" (1846), de Dostoievski. A seleção das obras guiou-se pela estrutura dissonante dessas narrativas, nas quais se encontram muitas e variadas aplicações estéticas da ironia, da paródia e do riso.', '["irony","parody","laughter","dissonance","Arthur Schopenhauer","Charles Baudelaire","Jean Paul","ambiguity","José Saramago","Italo Calvino","Fyodor Dostoevsky","The Man Without Qualities"]', '10.7476/9788579830259', '9788579830259', 'https://books.scielo.org/id/5dcq3', 'https://books.scielo.org/id/5dcq3/pdf/alavarce-9788579830259.pdf', NULL, 'https://books.scielo.org/id/5dcq3/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5dczv', '5dczv', 'Objetivos humanísticos, conteúdos científicos: contribuições da história e da filosofia da Ciência para o ensino de Ciências', NULL, '["Ana Paula Bispo da Silva","Breno Arsioli Moura"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro pre­tende apresentar novos elementos para a pesquisa em História e Filosofia da Ciência no Ensino de Ciências. Os trabalhos trazem novas questões filosóficas sobre os modelos e narrativas das ciências; os pressupostos culturais dos experimen­tos e teorias científicas e sua relação com o ensino; e, de maneira inversa, como as teorias e pressupostos científicos estão presentes na cultura e na divulgação de conhecimentos.', '["history of science","philosophy of science","science education","scientific models","scientific narratives","science education research"]', '10.7476/9786586221664', '9786586221664', 'https://books.scielo.org/id/5dczv', 'https://books.scielo.org/id/5dczv/pdf/silva-9786586221664.pdf', NULL, 'https://books.scielo.org/id/5dczv/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5gg44', '5gg44', 'Literatura, leitura e educação', NULL, '["Márcia Cabral da Silva","Estela Natalina Mantovani Bertoletti"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Reúne ensaios sobre a literatura destinada à infância e ao jovem e sobre as práticas de leitura no âmbito da escola e da vida social. Os autores transitam por diversos recortes temporais da relação entre leitura e educação, oferecendo também análise das reflexões de Cecília Meirelles e de Leonardo Arroyo acerca do tema. Os capítulos contribuem para o debate sobre a função da leitura literária na escola e a formação dos professores na condição de mediadores fundamentais do processo educativo.', '["children''s literature","young adult literature","reading practices","reading and education","school reading","social reading","teacher professional development"]', '10.7476/9788575114971', '9788575114971', 'https://books.scielo.org/id/5gg44', 'https://books.scielo.org/id/5gg44/pdf/silva-9788575114971.pdf', NULL, 'https://books.scielo.org/id/5gg44/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5gtk4', '5gtk4', 'Educação infantil em tempos de pandemia', NULL, '["Marlene Oliveira dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra propõe socializar, a partir de múltiplas vozes – crianças, professores(as) e coordenadores(as) pedagógicos(as) e docentes universitários(as) -, resultados de estudos, pesquisas e narrativas sobre a pandemia da covid-19 e suas reverberações na vida pessoal e profissional dos(as) trabalhadores(as) da educação infantil, das crianças e das suas famílias. Além disso, promove a discussão sobre o papel do Estado na garantia dos direitos fundamentais do ser humano em momentos de crise sanitária e humanitária, bem como a proposta pedagógica e curricular e a formação de políticas públicas para a educação infantil.', '["early childhood education","COVID-19 pandemic","early childhood educators","children and families","role of the state","fundamental human rights","health crisis"]', '10.7476/9786556303703', '9786556303703', 'https://books.scielo.org/id/5gtk4', 'https://books.scielo.org/id/5gtk4/pdf/santos-9786556303703.pdf', NULL, 'https://books.scielo.org/id/5gtk4/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5h', '5h', 'Dietário (1582-1815) do Mosteiro de São Bento da Bahia: edição diplomática', NULL, '["Alícia Duhá Lose","Dom Gregório Paixão","Anna Paula Sandes de Oliveira","Gérsica Alves Sanches","Célia Marques Telles"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta os resultados finais obtidos pelo projeto intitulado "Dietário (1582-1815) do Mosteiro de São Bento da Bahia: edição diplomática", a pesquisa em nível de pós-doutoramento é vinculada ao Programa de Pós-Graduação em Letras e Lingüística da Universidade Federal da Bahia. O trabalho apoiou-se sobre o documento manuscrito Dietario das vidas e mortes dos Monges, que faleceram neste Mosteiro de S. Sebastião da Bahia da Ordem do Príncipe dos Patriarchas S. Bento e procurou relatar a vida e morte de cada um dos monges que viveram e morreram nesta instituição religiosa. A narrativa vai de 1582, um ano após a fundação da instituição religiosa, e encerra em 1815. O Mosteiro bahiano é fruto da milenar história beneditina e sua grande tradição bibliográfica, possuindo, em seus arquivos grandes raridades e manuscritos do Brasil.', '["Benedictine monasteries","monastic records","dietary records","monastic archives","manuscript edition","religious history"]', '10.7476/9788523209360', '9788523209360', 'https://books.scielo.org/id/5h', 'https://books.scielo.org/id/5h/pdf/lose-9788523209360.pdf', NULL, 'https://books.scielo.org/id/5h/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
