INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5hfts', '5hfts', 'O ensino de geografia urbana: reflexões e ações pedagógicas', NULL, '["Rangel, Maria Cristina","Gilmar Alves Trindade","Gilsélia Lemos Moreira","Lurdes Bertol Rocha","Rita Jaqueline Nogueira Chiapetti","Tereza Genoveva Nascimento Torezani Fontes"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com o intuito de orientar e conduzir o aprendizado sobre o urbano, os escritores desta obra revisitaram vários autores, conceitos, teorias, análises, que pudessem iluminar a busca desse conhecimento, dessa vivência. Para isso, ao longo do livro, vão sendo traçados os caminhos que permitem concretizar esse objetivo. Para tanto, foram revisitados os conceitos de urbano e rural, cidade e campo.', '["urban studies education","educational intervention","city and countryside","geography education"]', '10.7476/9786586213874', '9786586213423', 'https://books.scielo.org/id/5hfts', NULL, NULL, 'https://books.scielo.org/id/5hfts/cover/cover_thumbnail.jpeg', 288, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5hjqk', '5hjqk', 'Janela da escuta: o adolescente especialista de si e a tessitura de uma rede sob medida', NULL, '["Cristiane de Freitas Cunha","Bianca Ferreira Rocha","Mateus Mourão"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-09-06', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Lê-se aqui uma proposta a esse corpo multiforme que é uma cidade, desde o coração da mesma, permitindo uma reconexão com o desejo a partir de uma abordagem interdisciplinar, na qual se coloca o adolescente no centro do dispositivo, com a ideia de que não há nenhum saber especializado para elucidar o que lhe acontece.(…) Uma proposta na medida do sujeito, aquilo que nossa cultura de especialistas, de saberes técnicos e de mercados rechaça: uma verdadeira proposta em ato, de tratamento para o mal-estar do nosso tempo', '["adolescents","listening","subjectivity","desire","expert knowledge","technical knowledge","interdisciplinary approach","social networks","self-knowledge"]', '10.7476/9786558580867', '9786558580546', 'https://books.scielo.org/id/5hjqk', NULL, NULL, 'https://books.scielo.org/id/5hjqk/cover/cover_thumbnail.jpeg', 717, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5j38w', '5j38w', 'Literatura, homoerotismo e expressões homoculturais', NULL, '["André Luís Mitidieri","Flávio Pereira Camargo"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos trazem à tona um universo homoerótico ambientado na literatura, na música e nas discussões teóricas mostrando que, atualmente, essas manifestações recebem outro olhar. Além disso, discutem as antigas bases de gênero e os novos modos de interpretação de sujeitos culturais, ressaltando a dificuldade em falar de questões homoafetivas em uma sociedade ainda machista e homofóbica. Eles mostram o distanciamento que algumas pessoas ainda têm a respeito do homoerotismo, por isso buscam desconstruir os estereótipos de gênero através da literatura, mostrando ao leitor que as expressões homoculturais vão além de um padrão pré-estabelecido pela sociedade e suas respectivas culturas.', '["homoeroticism","literature","music","gender stereotypes","homophobia","machismo","homoaffection","gender and sexuality","cultural subject"]', '10.7476/9788574554426', '9788574554426', 'https://books.scielo.org/id/5j38w', 'https://books.scielo.org/id/5j38w/pdf/mitidieri-9788574554426.pdf', NULL, 'https://books.scielo.org/id/5j38w/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5j9tr', '5j9tr', 'Vozes e versos quilombolas: uma poética identitária e de resistência em Helvécia', NULL, '["Gean Paulo Gonçalves Santana"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro de estreia do pesquisador Gean Paulo Gonçalves Santana é um importante registro da força política da mulher negra no Brasil, sustentada no canto, na dança, no tambor e na ação coletiva. Hoje temos consciência do protagonismo das mulheres em diversos movimentos sociais, na promoção de transformações em benefício da comunidade, de modo que já não se concebem ações antirracistas sem que se considerem as questões relativas à mulher. Este livro se debruça sobre as ações de um grupo de mulheres negras de Helvécia, no sul da Bahia, em que poesia e política se mesclam, organizando a vida em sociedade a partir do canto dançado, em solidariedade.', '["Black women","resistance","southern Bahia","song and dance","drumming","collective action","anti-racist movements"]', '10.7476/9786588211335', '9786588211243', 'https://books.scielo.org/id/5j9tr', 'https://books.scielo.org/id/5j9tr/pdf/santana-9786588211335.pdf', 'https://books.scielo.org/id/5j9tr/epub/santana-9786588211335.epub', 'https://books.scielo.org/id/5j9tr/cover/cover_thumbnail.jpeg', 336, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5jggz', '5jggz', 'Dossiê Bruno Latour', NULL, '["Geane Carvalho Alzamora","Joana Ziller","Francisco Ângelo Coutinho"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-06-15', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'A obra de Bruno Latour, uma das mais originais e influentes que emergiram nas últimas décadas, encontra ressonância em áreas variadas de investigação, como antropologia, sociologia, filosofia, história, comunicação e educação, entre outras. Algumas leituras situam o pensador entre os mais proeminentes analistas da antropologia da ciência e do que se convencionou chamar de modernidade. Neste volume, apresentamos o pensamento de Bruno Latour em diálogo com a teoria ator-rede, da qual ele é um dos fundadores. São discutidos conceitos referenciais para o autor a partir de seu próprio ponto de vista, do de seus colegas na formulação da teoria ator-rede e do de especialistas brasileiros.', '["Bruno Latour","actor-network theory","anthropology of science","modernity","science and society","sociology of science","philosophy of science"]', '10.7476/9786558580485', '9788542303223', 'https://books.scielo.org/id/5jggz', NULL, NULL, 'https://books.scielo.org/id/5jggz/cover/cover_thumbnail.jpeg', 310, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5jjqx', '5jjqx', 'Dicionário temático de patrimônio: debates contemporâneos', NULL, '["Cristina Meneguello"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro reúne 62 autores, de diferentes áreas disciplinares, e 50 verbetes sobre temas relacionados às discussões patrimoniais no Brasil. Eles foram organizados em duas partes: a primeira, voltada para definições de conceitos, instituições, tipologias e legislação, e a segunda, dedicada aos novos temas na área patrimonial, tais como memória da internet e turismo religioso. Rigorosos, mas escritos de forma acessível, os verbetes são sempre acompanhados de referências bibliográficas consideradas fundamentais pelos especialistas. A obra é voltada para estudiosos, gestores públicos e interessados no tema do patrimônio.', '["cultural heritage","heritage debate","heritage legislation","cultural heritage institutions","heritage typology","religious tourism","heritage management","concept of heritage"]', '10.7476/9786586253696', '9786586253276', 'https://books.scielo.org/id/5jjqx', NULL, NULL, 'https://books.scielo.org/id/5jjqx/cover/cover_thumbnail.jpeg', 271, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5kb3t', '5kb3t', 'Utilização de resíduos agroindustriais na construção', NULL, '["Antônio Ludovico Beraldo"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Com o aumento da população e o crescimento da demanda, um sério problema tem atingido o setor da construção civil: a escassez de recursos naturais. Sua exploração, além de custosa, pois as jazidas costumam estar distantes dos grandes centros, tem grande impacto ambiental. Assim, a busca de materiais alternativos àqueles comumente empregados no setor da construção civil é muito bem-vinda. Este livro apresenta e avalia novos tipos de aglomerantes e/ou de agregados, que buscam atender às especificações técnicas e podem substituir ou complementar o uso dos aglomerantes e agregados convencionais, bem como servir a novos tipos de aplicação. Uma larga gama de materiais, anteriormente denominados rejeitos ou descartes, foi analisada por uma equipe multidisciplinar de pesquisadores de várias instituições brasileiras, reunindo expertises de variados segmentos relacionados à construção civil. A conclusão é a descoberta de que materiais muitas vezes jogados fora podem ser incorporados aos processos tradicionais da construção civil, após pequenas modificações, resultando em edificações econômica e ambientalmente mais sustentáveis.', '["agro-industrial waste","building materials","binders","aggregates","waste reuse","sustainable construction","natural resource scarcity","alternative building materials"]', '10.7476/9788526815407', '9786586253337', 'https://books.scielo.org/id/5kb3t', NULL, NULL, 'https://books.scielo.org/id/5kb3t/cover/cover_thumbnail.jpeg', 404, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5kgsm', '5kgsm', 'Arquitetura e educação: campus universitários Brasileiros', NULL, '["Gelson de Almeida Pinto","Ester Buffa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Este livro, escrito por um arquiteto urbanista e uma historiadora da educação, trata, no essencial, do percurso histórico da instituição universitária que, nascida na Europa medieval como uma instituição urbana, sofreu grandes transformações no tempo e no espaço, chegou aos nossos dias, no Brasil, a ser construída apartada da cidade e a se constituir como câmpus universitário, um território novo e original. São analisados alguns dos projetos de planejamento e construção do câmpus de algumas renomadas universidades brasileiras: UFRJ, USP, UFRGS, UnB e UNICAMP.', '["university campus","campus architecture","higher education history","campus planning","university building construction","Brazilian universities","Universidade Federal do Rio de Janeiro","USP","UFRGS","UNICAMP"]', '10.7476/9788576003748', '9788576003748', 'https://books.scielo.org/id/5kgsm', 'https://books.scielo.org/id/5kgsm/pdf/pinto-9788576003748.pdf', NULL, 'https://books.scielo.org/id/5kgsm/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5kj52', '5kj52', 'Luchas indígenas, trayectorias poscoloniales (Américas y Pacífico)', NULL, '["Bosa, Bastien","Santamaría, Ángela","Éric Wittersheim"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto es único, puesto que se centra en las trayectorias sociales de líderes indígenas de diferentes regiones del mundo, poniendo los actores sociales en el centro del análisis. Igualmente, el libro privilegia, de una manera novedosa, el método etnográfico y da cuenta, sin embargo, de procesos estructurales (la lógica jurídica, política y económica). Así, permite hacer una crítica, a través de la presentación de materiales empíricos muy ricos, de las aproximaciones clásicas en antropología de la problemática indígena. También da cuenta de investigaciones novedosas sobre objetos y terrenos de investigación interdisciplinarios, que permiten la convergencia de varias disciplinas (antropología, historia, derecho, relaciones internacionales, sociología). Este texto logra reunir autores de muchas regiones del mundo alrededor de una misma problemática, y logra una aproximación teórica y metodológica al tema. Está dirigido a la comunidad académica nacional e internacional: internacionalistas, antropólogos sociales, politólogos, sociólogos y, en general, estudiosos de las cuestiones indígenas y raciales.', '["indigenous resistance","indigenous leaders","indigenous peoples","social trajectories","indigenous rights","Latin America","Pacific Islands"]', '10.7476/9789585005389', '9789585005389', 'https://books.scielo.org/id/5kj52', 'https://books.scielo.org/id/5kj52/pdf/bosa-9789585005389.pdf', NULL, 'https://books.scielo.org/id/5kj52/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5kkth', '5kkth', 'As comissões da verdade e os arquivos da ditadura militar brasileira', NULL, '["Mônica Tenaglia"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2023, '2023-06-29', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra explora o contexto histórico-legal das comissões da verdade no Brasil e no mundo e reconstrói as estratégias e ações das comissões brasileiras para o acesso aos arquivos da ditadura militar (1964-1985). A partir da análise da emergência do reconhecimento dos arquivos para as investigações sobre violações dos direitos humanos e a efetivação do direito à informação, à verdade e à memória, o livro discute o fenômeno da criação de comissões da verdade em todo o território nacional brasileiro e as relações das comissões com os arquivos. Nesse sentido, evidenciam-se a insuficiência das políticas de gestão documental e um quadro de negação, ocultamento e destruição dos arquivos do período da ditadura militar. Todavia, identifica-se que, apesar dos problemas e limitações, as comissões da verdade conseguiram criar estratégias e implementar ações para superar essas dificuldades, dentre elas, parcerias com as universidades, especialmente com os cursos de Arquivologia. Como lacuna na atuação das comissões da verdade no Brasil, o livro constata que foram poucas as ações educativas realizadas fora dos círculos acadêmicos e voltadas a uma parcela mais ampla da população brasileira.', '["truth commissions","Brazilian military dictatorship 1964-1985","human rights violations","right to information","right to truth","right to memory","archival access","archival education"]', '10.7476/9786558461692', '9786558461692', 'https://books.scielo.org/id/5kkth', NULL, NULL, 'https://books.scielo.org/id/5kkth/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5m6xs', '5m6xs', 'Cartografias do ensino do teatro', NULL, '["Florentino, Adilson","Telles, Narciso"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'other', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Um caleidoscópio das diferentes teorias e práticas empregadas na análise do teatro. Em seus 29 textos, esse livro proporciona a reflexividade e a criticidade sem perder a paixão e entusiasmo pelo teatro.', '["theatre education","theatre pedagogy","theatre analysis","theatre theory","theatre practice","reflexivity","critical thinking"]', '10.7476/9788570785183', NULL, 'https://books.scielo.org/id/5m6xs', 'https://books.scielo.org/id/5m6xs/pdf/florentino-9788570785183.pdf', NULL, 'https://books.scielo.org/id/5m6xs/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5mz6v', '5mz6v', 'Jano y las caras opuestas de los derechos humanos de los pueblos indígenas', NULL, '["Brett, Roddy","Santamaría, Ángela"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2010, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Este Boletín presenta la sistematización de las conclusiones más relevantes del Simposio Alianzas y Redes Regionales en la Implementación del Acuerdo Final, evento propuesto por la Universidad del Rosario y la Fundación Hanns Seidel para permitir el debate y diálogo constructivo entre actores institucionales, sociales y académicos de diversas regiones del país. La metodología utilizada en las mesas de trabajo, permitió sintetizar los aportes y publicarlos como insumo para futuros trabajos de investigación y seguimiento del Acuerdo de Paz con las FARC. El trabajo aborda cuatro temas: i) las voces de las víctimas, ii) reforma de tierras, iii) participación política para construir la paz, y iv) reincorporación y fin del conflicto. Las conclusiones del trabajo coinciden con los informes internacionales, al señalar como prioritarias las medidas para la protección y seguridad en los territorios, el proceso de reincorporación de los excombatientes, y la operación exitosa de la Jurisdicción Especial para la Paz (JEP).', '[]', '10.7476/9789585005365', '9789587381474', 'https://books.scielo.org/id/5mz6v', 'https://books.scielo.org/id/5mz6v/pdf/brett-9789585005365.pdf', 'https://books.scielo.org/id/5mz6v/epub/brett-9789585005365.epub', 'https://books.scielo.org/id/5mz6v/cover/cover_thumbnail.jpeg', 221, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5nbzq', '5nbzq', 'Cidadania glocal, identidade nordestina: ética da comunicação na era da internet', NULL, '["José Marques de Melo"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os estudos produzidos na área de comunicação no Brasil, nas últimas quatro décadas, confundem-se com o nome do professor José Marques de Melo.Poucos pesquisadores detém uma produção acadêmico-científica tão fértil e comprometida com um campo de conhecimento em busca de identidade.A extensão de sua obra é reconhecida mundialmente, com ênfase para as contribuições relacionadas às sociedades latino-americanas e, de modo especial, aos fenômenos comunicacionais brasileiros.Neste sentido, conduz-lhe uma bandeira: "não abdico do direito à autodeterminação e do dever de projetar nossas identidades no cenário mundial.', '["glocalization","citizenship","Northeastern Brazilian identity","communication ethics","internet","digital media","internet era","José Marques de Melo","Brazilian communication studies","self-determination (international law)","identity construction"]', '10.7476/9788578797254', '9788578797254', 'https://books.scielo.org/id/5nbzq', 'https://books.scielo.org/id/5nbzq/pdf/melo-9788578791254.pdf', NULL, 'https://books.scielo.org/id/5nbzq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5ngcb', '5ngcb', 'Epidemiologia nutricional', NULL, '["Kac, Gilberto","Sichieri, Rosely","Gigante, Denise"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Nesta coletânea de fôlego, os organizadores e autores oferecem uma poderosa ferramenta de trabalho aos pesquisadores e interessados na epidemiologia nutricional brasileira. Ampliando os horizontes tradicionais desse campo de estudo, o livro vai além de avaliação de dietas e da relação entre alimentação e doenças crônicas não transmissíveis. Os 38 capítulos desta segunda edição revista e ampliada contemplam métodos e análises que abrangem antigos e atuais problemas nutricionais brasileiros, com engajamento propositivo na solução de problemas. Simultaneamente, manual técnico da complexa área da avaliação nutricional e rigorosa enciclopédia nutricional brasileira, este compêndio de enfoque amplo e multidisciplinar reúne os principais investigadores na área de nutrição e saúde pública no Brasil e surge como leitura fundamental para os estudos de nutrição e saúde coletiva.', '[]', '10.7476/9786557081891', '9786557081891', 'https://books.scielo.org/id/5ngcb', NULL, NULL, 'https://books.scielo.org/id/5ngcb/cover/cover_thumbnail.jpeg', 608, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5pgjy', '5pgjy', 'Estratégias de visualidade na literatura: o Olho Sebald', NULL, '["Kelvin Falcão Klein"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Estratégias de visualidade na literatura: Olho Sebald é um ensaio dividido em capítulos temáticos que trata da relação entre texto e imagem na literatura contemporânea, com ênfase no escritor alemão W. G. Sebald (1944-2001). Oferece também associações com outros autores, tanto de literatura quanto de ciências humanas (Walter Benjamin, Theodor Adorno, Michel Foucault), extraindo parte de sua premissa inicial de uma categoria desenvolvida por Georges Didi–Huberman em sua obra, ou seja, a noção de “olho da História”. Tal categoria é aqui ampliada e direcionada para uma leitura detida da literatura contemporânea em geral e dos escritos de W. G. Sebald em específico. Ao longo do livro, utilizando tanto ensaios quanto ficções de W. G. Sebald, o autor busca refletir sobre as estratégias de visualidade inseridas nos textos (como o olhar é uma categoria historicamente construída), bem como realizar uma discussão crítica acerca da inserção de imagens dentro dos romances (a questão da materialidade, da montagem dos fragmentos visuais e do estatuto ético da representação visual). Cada capítulo do livro é intitulado a partir de uma obra comentada por Sebald em seu trabalho. Tais obras podem ser tanto livros (de ficção ou de teoria) quanto pinturas, como é o caso, por exemplo, de Lição de anatomia, de Rembrandt, ou Sob o signo de Saturno, que remete a um livro de ensaios de Susan Sontag. Com isso, cada capítulo propõe uma discussão teórica no âmbito da crítica literária e da literatura comparada, lidando com a poética de W. G. Sebald e, ao mesmo tempo, remetendo a outros textos e imagens em viés comparatista.', '["W. G. Sebald","visuality in literature","text-image relationship","Georges Didi-Huberman","Walter Benjamin","Theodor W. Adorno","Michel Foucault","visual representation","materiality of images","visual montage","contemporary literature","comparative literature"]', '10.7476/9786558580843', '9786558580409', 'https://books.scielo.org/id/5pgjy', NULL, NULL, 'https://books.scielo.org/id/5pgjy/cover/cover_thumbnail.jpeg', 207, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5pk6k', '5pk6k', 'Un ecosistema llamado universidad', NULL, '["Juan Pablo Salgado-Guerrero"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro está dedicado a la universidad como protagonista de cambios. El texto lleva a comprender la universidad como ámbito de la relación indivisible de organización-sistema, en donde el todo es más que la suma de las partes, y el producto es el conocimiento como fin, medio y fundamento para el desarrollo de la persona (sentido crítico) y la respuesta al entorno (razón instrumental). A lo largo del texto se va construyendo la imagen de la universidad-ecosistema productora de novedad, donde la única certeza es la incertidumbre y que, además está en permanente crecimiento espiral, que transforma su entorno apuntado a la construcción de la ciudadanía responsable y la persona libre; la espiral del conocimiento sin control de casualidad. Un ecosistema, como el de la universidad propuesta, se encuentra en permanente construcción y deconstrucción, es el comenzar que es crear permanentemente con el presente y el pasado que está ya asumido en el presente. Redescubrir la frescura natural de un ecosistema inmerso en la universidad, y la vivencia pura de comunidad, nos llevará de la mano a quienes presumimos de catedráticos, al origen más puro del conocimiento humano que tienen saber de vida, a la pureza refrescante de lo inédito y el valor auténtico de lo ingenuo, para que en ese instante seamos nosotros, comunidad en la que se autoorganiza y construye proyectos de vida, cultura y destino.', '["knowledge production","university-community collaboration","responsible citizenship","human development","uncertainty","spiral growth","self-organization","higher education transformation"]', '10.7476/9789978106822', '9789978106822', 'https://books.scielo.org/id/5pk6k', 'https://books.scielo.org/id/5pk6k/pdf/salgado-9789978106822.pdf', NULL, 'https://books.scielo.org/id/5pk6k/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5ptyx', '5ptyx', 'Reflexiones sobre periodismo deportivo: experiencias, retos y expectativas', NULL, '["Torres-Toukoumidis, Ángel","Andrea De Santis-Piras","Tamay-Crespo, Ángeles"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro responde al desafío de dar a conocer la situación del periodismo deportivo a nivel local, regional, nacional e internacional. En esta ocasión, estudiantes de la carrera de Comunicación, sede Cuenca de la Universidad Politécnica Salesiana, Ecuador articulan un compendio de ocho capítulos de investigación en los que manteniendo una estructura organizada pretenden vincular los medios y el deporte con la historia, publicidad, redes sociales, política, profesionalización mediática, olimpíadas, estereotipos femeninos y los E-sports. La heterogeneidad de los resultados obtenidos enriquece las acciones futuras en esta área de la comunicación, entre ellas, la migración digital de las audiencias prescribe una adaptación progresiva de los medios, la necesidad de romper el estereotipo femenino en un ambiente excesivamente masculinizado, alertar a las autoridades del uso del deporte para proselitismo político, entre otras.', '["sports journalism","media professionalization","social media in sport","Olympic Games","gender stereotypes","esports","political uses of sport"]', '10.7476/9789978108277', '9789978108277', 'https://books.scielo.org/id/5ptyx', 'https://books.scielo.org/id/5ptyx/pdf/torres-9789978108277.pdf', NULL, 'https://books.scielo.org/id/5ptyx/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5r38c', '5r38c', 'Arquitetura militar ou fortificação moderna', NULL, '["Diogo da Sylveyra Vellozo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O professor e arquiteto Mário Mendonça de Oliveira lançou em Salvador, por intermédio da editora da Universidade Federal da Bahia, um tratado inédito de Engenharia Militar, escrito em Pernambuco pelo Brigadeiro Diogo da Silveira Vellozo, e intitulado "Arquitetura Militar ou Fortificação Moderna", um texto interessantíssimo do século XVIII, que consegue desvendar, para os não iniciados, os segredos da fortificação abaluartada e da engenharia da época. Trata-se de texto obrigatório para historiadores, engenheiros, arquitetos e restauradores. O professor Mário Mendonça organizou e transcreveu o manuscrito, acrescentando abundantes notas explicativas que aclaram o texto original, que contém ainda 49 pranchas de desenhos que foram reproduzidos com sistema digital. É um documento que permite ver a grande erudição e conhecimento deste personagem da construção do Brasil. Este livro vem se juntar a outra publicação recente do professor Mário Mendonça, "As Fortificações Portuguesas de Salvador", ambas obras fundamentais para o conhecimento das fortificações militares no Brasil.', '["military architecture","fortifications","military engineering","18th-century fortifications","bastioned fortifications","Portuguese fortifications","historical manuscripts","architectural drawings"]', '10.7476/9788523208868', '9788523208868', 'https://books.scielo.org/id/5r38c', 'https://books.scielo.org/id/5r38c/pdf/vellozo-9788523208868.pdf', NULL, 'https://books.scielo.org/id/5r38c/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5rfdh', '5rfdh', 'O quibe no tabuleiro da baiana: uma reflexão sobre a imigração síria e libanesa e o turismo cultural em Ilhéus', 'uma reflexão sobre a imigração síria e libanesa e o turismo cultural em Ilhéus', '["Maria Luiza Silva Santos"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os imigrantes sírios e libaneses chegaram ao Sul da Bahia no final do século XIX e início do século XX em função das crises políticas em seus territórios e pela perspectiva de progresso da região. Este trabalho visa a contribuir com a divulgação dessa história embasada em depoimentos e nos conceitos de migração, turismo, identidade e globalização, propondo uma reflexão quanto a sua utilização no sentido de enriquecer a cultura e o turismo regional.', '["cultural tourism","Ilhéus","regional tourism","immigrant identity","globalization","migration history","cultural heritage"]', '10.7476/9788574556390', '9788574556222', 'https://books.scielo.org/id/5rfdh', NULL, NULL, 'https://books.scielo.org/id/5rfdh/cover/cover_thumbnail.jpeg', 151, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5rh3c', '5rh3c', 'Computação, cognição, semiose', NULL, '["João Quiroz","Ângelo Loula","Ricardo Gudwin"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro aborda problemas teóricos, empíricos e metodológicos. Discute as ideias de “semiose genuína” e deUmwelt em sistemas artificiais e as ideias de emergência de semiose e de “mundo fenomenal” nestes sistemas. Relaciona as noções de semiose, aprendizagem, símbolo, máquina semiótica, inteligência estendida e computacional.', '["semiosis","Umwelt","artificial systems","phenomenal world","learning","symbols","extended mind","computational intelligence","cognition","artificial intelligence"]', '10.7476/9788523217297', '9788523204549', 'https://books.scielo.org/id/5rh3c', NULL, NULL, 'https://books.scielo.org/id/5rh3c/cover/cover_thumbnail.jpeg', 286, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5rwhm', '5rwhm', 'Simulacros de Império: território, mapeamento e invenção das fronteiras ibero-americanas (século XVIII)', 'território, mapeamento e invenção das fronteiras ibero-americanas (século XVIII)', '["Denise Aparecida Soares de Moura"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mapear é uma ação inerente ao humano, pois todo indivíduo consciente necessita se situar no espaço. Nesse sentido, qualquer pessoa – profissional da geografia ou da cartografia ou leigo nessa área – pratica geografia, mapeamento e produz mapas mentais, gráficos ou performáticos para se orientar ou para simplesmente descrever o espaço. Quando essas geografias não profissionais são apropriadas pelos Estados, seus autores originais são elididos e, consequentemente, seus legítimos direitos à terra são anulados, como mostra a experiência do Estado colonial português na segunda metade do século XVIII, quando disputava com a Coroa de Espanha a definição de seus limites territoriais na América do Sul. Este é um livro sobre como estados coloniais da época moderna inventaram soberania, autoridade e direitos sobre terras de outros a partir de expedições de mapeamento e mapas. A partir da cartografia histórica do Brasil, a autora indica um caminho para começarmos a recuperar autorias de territórios e lugares apagadas por agentes estatais envolvidos em simular impérios, territórios e terras de Estado.', '["colonial cartography","historical maps","territorial boundaries","Portuguese colonial empire","Spanish Empire","18th century","state sovereignty","indigenous land rights"]', '10.7476/9786557145531', '9786557145531', 'https://books.scielo.org/id/5rwhm', 'https://books.scielo.org/id/5rwhm/pdf/moura-9786557145531.pdf', NULL, 'https://books.scielo.org/id/5rwhm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5rwtx', '5rwtx', 'Cartas dos índios camarões escritas em tupi antigo (1645) - Volume 1', NULL, '["Eduardo Navarro","Alícia Duhá Lose","Bruna Trindade Gomes Carneiro","Mariana Fagundes de Oliveira Lacerda","Zenaide de Oliveira Novais Carneiro"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Foi a partir de 2017 que o projeto Corpus Eletrônico de Documentos Históricos do Sertão (CE-DOHS), do Núcleo de Estudos de Língua Portuguesa (NELP) da Universidade Estadual de Feira de Santana (UEFS), já tendo disponibilizado significativo material de sua primeira fase de execução (pós-colonial), começou a investir na constituição de corpus ilustrativo do período colonial brasileiro, intensificando a parceria com a Paleografia, com a Diplomática e com a Filologia, para o tratamento de textos de épocas ainda mais recuadas. Destaca-se a parceria com o projeto Modus Scribendi — Grupo de Pesquisas Paleográficas, Diplomáticas, Codicológicas, Filológicas e Históricas, da Universidade Federal da Bahia (UFBA). O trabalho de constituição do corpus colonial do CE-DOHS/NELP representa, entre outros, junto ao Projeto Nacional para a História do Português Brasileiro (PHPB), um avanço de sua agenda de corpus históricodiacrônico, tanto em razão da ampliação do banco de textos — fazendo uma melhor cobertura das fases da periodização da história sociolinguística do Brasil — como em razão do diálogo, com maior grau de maturidade, com a Paleografia, a Diplomática e a Filologia. O ingente trabalho de organização de corpora histórico-diacrônicos é condição sine qua non para desenvolver pesquisas de base empírica, tendo em vista uma melhor compreensão da história do português no/do Brasil e a discussão de questões teóricas solidamente fundamentadas.', '["Tupi language","Amazonian indigenous peoples","colonial Brazil","historical corpora","diachronic corpus","historical Portuguese","paleography","diplomatics"]', '10.7476/9788555921896', '9788555921322', 'https://books.scielo.org/id/5rwtx', NULL, NULL, 'https://books.scielo.org/id/5rwtx/cover/cover_thumbnail.jpeg', 171, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5sd7p', '5sd7p', 'Estudo da competitividade da indústria brasileira: o complexo agroindustrial', NULL, '["John Wilkinson"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Neste trabalho apresenta-se uma análise da competitividade do complexo agroindustrial brasileiro no contexto dos novos padrões de concorrência a nível internacional, com a finalidade de propor um conjunto de políticas para o incremento da competitividade do setor e identificar os indicadores mais relevantes para o acompanhamento de sua evolução.', '["competitiveness","agro-industrial complex","international competition","competitiveness indicators","industrial policy","agricultural sector"]', '10.7476/9788599662649', '9788599662649', 'https://books.scielo.org/id/5sd7p', 'https://books.scielo.org/id/5sd7p/pdf/wilkinson-9788599662649.pdf', NULL, 'https://books.scielo.org/id/5sd7p/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5twcy', '5twcy', 'Biopolítica, deficiência e educação: outros olhares sobre a inclusão escolar', NULL, '["Pedro Ângelo Pagni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ao abordar os modos deficientes de existência sob a ótica da biopolítica, este livro procura encontrar na fragilidade desses corpos uma potencialidade a ser cultivada na escola. Objetiva com isso propor aos leitores uma reflexão sobre sua relação com esse outro e evocar dessa forma um posicionamento ético nos jogos atuais do biopoder. Para tanto, o autor analisa a passagem da deficiência como condição a ser evitada à paradigma da biopolítica neoliberal, engendrando processos de identidade e de subjetivação que estão no centro das atuais políticas de inclusão. Discute também os efeitos desses processos para a chamada inclusão escolar, sugerindo como estão presos a um olhar científico e a tecnologias de biopoder que subtraem o ethos do ser deficiente para subordiná-los a regulamentações predeterminadas e a uma governamentalidade identitária. Por fim, interessado na decifração da particularidade desses modos de existência, Pedro Angelo Pagni interpreta a radicalidade ontológica da deficiência, elucidando sua relação com os acidentes e seu potencial para agenciar outros olhares sobre a inclusão na escola.', '["biopolitics","disability","inclusive education","identity politics","subjectivation","governmentality","accidents","disability in education","disability ethics"]', '10.7476/9788595463332', '9788595463332', 'https://books.scielo.org/id/5twcy', 'https://books.scielo.org/id/5twcy/pdf/pagni-9788595463332.pdf', NULL, 'https://books.scielo.org/id/5twcy/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5v3dr', '5v3dr', 'Transfigurações de Axel: leituras de teatro moderno em Portugal', NULL, '["Renata Soares Junqueira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Quando, no fim do século 19, a forma dramática baseada no diálogo e nas ações decorrentes de relações intersubjetivas entra em crise pela incapacidade de expressar a situação do sujeito no contexto social, o foco da dramaturgia volta-se para o sujeito isolado e introvertido. Essa forma de representação viria a caracterizar não apenas o teatro, mas a arte moderna em geral. Esse sujeito, transformado em “coisa”, peça da engrenagem industrial, ao poucos vai perdendo a capacidade de diálogo e vê sua vontade de agir cerceada pelo sistema socioeconômico decorrente do avanço do capitalismo industrial. Com a rarefação do diálogo o drama sobreviveria transformando-se. Daí, o teatro moderno ser povoado de personagens introvertidas e autocentradas, mais afeitas ao monólogo. Neste livro aautora busca entender o teatro moderno a partir de personagens que carregam essas características – o protagonista do drama homônimo de Auguste Villiers de l’Isle-Adam (1838–1889), o misantropo radical Axel, que renuncia à vida para não ver frustrados os seus sonhos; e o ícone do homem atual, ou seja, o homem solitário e oprimido pelo mundo circundante, figurado em O grito (1893), quadro do pintor norueguês Edvard Munch (1863–1944). No decorrer da obra ela aborda criações que compõem a história do moderno teatro português entre o fim do século 19 e as primeiras décadas do 20. Entre os autores analisados, estão Eugénio de Castro, Manuel Teixeira-Gomes, Mário de Sá-Carneiro, Fernando Pessoa, António Patrício, Raul Brandão e Branquinho da Fonseca.', '["Axel","Edvard Munch","The Scream","monologue","misanthropy","modern subject","industrial capitalism","Eugénio de Castro","Mário de Sá-Carneiro","Fernando Pessoa","Raul Brandão"]', '10.7476/9786557144756', '9786557144756', 'https://books.scielo.org/id/5v3dr', 'https://books.scielo.org/id/5v3dr/pdf/junqueira-9786557144756.pdf', NULL, 'https://books.scielo.org/id/5v3dr/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5v9s3', '5v9s3', 'Análise estratégica em saúde e gestão pela escuta', NULL, '["Francisco Javier Uribe Rivera"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'A n e x o 283Reúne-se, aqui, uma série de trabalhos cujo fio condutor representa uma proposta teórico-metodológica de gestão, traduzida no título: Análise Estratégica em Saúde e Gestão pela Escuta.Estes estudos ganham coerência em relação ao passado ou por oposição ao passado.Representam um desdobramento de nossa tese de doutoramento em Saúde Pública, defendida em 1991 na Escola Nacional de Saúde Pública da Fundação Oswaldo Cruz (Ensp/Fiocruz), que consistiu em um contraponto teórico-metodológico entre a Teoria do Agir Comunicativo de Habermas e a Teoria do Planejamento Estratégico em Saúde.Naquele momento, fomos animados pelo propósito de (des)construir o enfoque de planejamento estratégico, através de uma análise crítica sistemática, alicerçada na idéia do planejamento como uma relação interativa dialógica, superadora da lógica da utilidade individual e da reificação dos outros atores.Essa crítica não objetivou, porém, a negação radical dos métodos conhecidos de planejamento estratégico, especialmente do enfoque situacional de Matus, mas um alargamento de perspectiva, na direção de uma maior flexibilidade metodológica, resgatando o planejamento a serviço da criação de um ambiente de comunicação ampla, da busca por legitimidade e do consenso na construção das propostas pertinentes.A tese teve um escopo eminentemente teórico de refletir, no interior do campo do planejamento e da gestão, um novo paradigma, o comunicativo.A partir de então, conscientes de que a crítica teórica é necessária, porém insuficiente em um campo pragmático, emerge o propósito de realizar um trabalho propositivo que implicasse dar um conteúdo prático a uma proposta de agir comunicativo em gestão e planejamento.Tal propósito não tem sido fácil de realizar, pois subentende o estabelecimentos de mediações, de pontes, entre o nível mais epistemológico da grande teoria e a especificidade do terreno da gerência.Este esforço comporta a busca de autores e de enfoques do campo respectivo que possam ser utilizados como fatores de articulação e ser identificados como expoentes da gestão como intersubjetividade discursiva e como APRESENTAÇÃO 1 0 processo de desenvolvimento da aprendizagem, da solidariedade e de nexos ou redes criativas.Isto quer dizer que não é possível deduzir mecanicamente ou linearmente do agir comunicativo uma proposta prática.Esta só se configura como uma diversidade pragmática de enfoques que podem ser aproximados dos pressupostos gerais desse paradigma comunicativo.A docência sistemática na pós-graduação da Ensp nos ensejou uma disciplina de pesquisa e reflexão que nos permitiu apreender autores e enfoques, os quais pudemos aglutinar dentro de nosso referencial.Alguns foram testados ou experimentados junto aos alunos dessa casa e algumas dessas experiências queremos trazer à tona no livro.Estes alunos foram a condição de possibilidade de alguns capítulos.Podem ser chamados quase co-autores, em alguns momentos, e a eles agradecemos.O trabalho de pesquisa, articulado à docência, é lento, cumulativo e demanda tempo.É uma tentativa permanente de dissipar os traços de escuridão inerentes ao experimentar com idéias em prol de mais luz.Isto, somado aos altos e baixos da vida, explica o lapso de tempo ao trazer à tona os resultados deste trabalho nesta publicação e porque não atingimos completamente este propósito.Vale dizer que o trabalho de pesquisa com idéias é permanente e contínuo.Os autores principais que fomos solidificando nesse nosso processo relativamente sistemático, às vezes intuitivo, de apreensão das identificações discursivas, são, principalmente Matus, Crémadez, Godet e Senge.Carlos Matus, grande ideólogo do planejamento latinoamericano, falecido há pouco tempo, nos ensinou a arte de pensar mais pragmaticamente o planejamento como gerência descentralizada de problemas abordados criativa e interativamente, bem como as regras de como pensar estrategicamente uma organização.É o autor que mais pudemos abarcar e conhecer, e que mais marcas deve ter deixado no nosso imaginário mais profundo.Ele não é o motivo principal deste trabalho, mas a ele dedicamos as primeiras linhas, no primeiro capítulo, pois é a partir das lacunas/possibilidades que nele identificamos, iluminados pelo Agir Comunicativo de Habermas, que desenvolvemos a pesquisa de outros autores e perspectivas que pudessem complementar sua abordagem, preenchendo os vazios e possibilidades de comunicação.Sua produção profícua é mais do que suficiente e nos leva naturalmente à busca de novos autores que ampliem o perfil de sua obra, como parte deste nosso trabalho de pesquisa.Devemos frisar aqui que o legado de Matus é um patrimônio inexorável nesta área que é o nosso campo de reflexão e de prática.Michel Crémadez, de uma equipe francesa de gestão estratégica (de Altos Estudos Comerciais), é o segundo autor que conhecemos com maior profundidade relativa.À sua obra teórico-prática e a seus desdobramentos, dedicamos ajudar a incentivar o desenvolvimento da liderança individual e coletiva.A publicação representa, através de sua proposta, a tentativa de apresentar mais uma referência para o treinamento de habilidades típicas da liderança.A gestão pela escuta acentua a necessidade de uma liderança que se desenvolva a partir de uma escuta da cultura, de uma capacidade aumentada de negociação cooperativa e de um poder de comunicação a serviço, preferencialmente, do crescimento do coletivo.No primeiro capítulo, em co-autoria com Elizabeth Artmann, atualizamos nosso mapeamento de tendências neste campo e dos desafios em termos de pesquisa para complementar o referencial do planejamento estratégico-situacional, de maneira a construir um substrato prático para a gestão comunicativa.Esta discussão é uma atualização de um artigo já publicado em 1999, na Revista Ciência & Saúde Coletiva, da Associação Brasileira de Pós-Graduação em Saúde Coletiva (Abrasco).No segundo capítulo, apresentamos a proposta teórico-metodológico de Michel Crémadez, que se notabiliza pelo esforço de transformação de uma lógica do planejamento estratégico corporativo em um sistema de gestão estratégica para hospitais do setor público e privado, que contribua para uma avaliação sistemática da missão em função de uma perspectiva que privilegia os usuários do sistema e a composição de redes.O capítulo três representa o resultado de um exercício de aplicação do enfoque da análise estratégica hospitalar francesa ao Hospital Philippe Pinel, cujo autor principal foi o então diretor do hospital e aluno da Ensp, Fernando Augusto de Cunha Ramos, do Curso de Gestão Hospitalar (1997).No quarto capítulo apresentamos, discutimos e aplicamos o modelo de análise de Godet, e outras aproximações à questão dos cenários de cálculo prospectivo.Os capítulos cinco, seis e sete representam um conjunto de textos de nossa autoria cujo fio condutor é a gestão pela escuta.Destacamos, em cada um, questões específicas pertinentes ao tema.No primeiro deles, no capítulo cinco, apresentamos vários enfoques de análise cultural, incluindo uma discussão sobre a perspectiva de mudança cultural e de análise do conceito de liderança, privilegiando uma concepção comunicativa da mesma, que se articula à possibilidade de mudança cultural.O sexto capítulo representa um enfoque geral de negociação cooperativaconsagrado por autores como Fischer e Ury da escola de Negociação de Harvard -onde destacamos a necessidade da utilização de ferramentas de comunicação que provêm de âmbitos variados, como a própria psicologia.No capítulo sete, (Inter)subjetividade, aprendizagem organizacional e mudança: algumas ferramentas lúdico-pragmáticas, apresentamos as principais 1 9 gração, da possibilidade de um projeto solidário, entendido como desafio gerencial permanente.Nesta perspectiva, a escolha dos métodos de desenho ou de análise se subordina a esse objetivo próprio ao campo da gestão.Podem-se utilizar vários métodos que criem a possibilidade de fluxos de comunicação ampliada e de negociação de compr', '["health management","listening","communicative action","Jürgen Habermas","legitimacy","consensus"]', '10.7476/9788575413036', NULL, 'https://books.scielo.org/id/5v9s3', 'https://books.scielo.org/id/5v9s3/pdf/rivera-9788575413036.pdf', NULL, 'https://books.scielo.org/id/5v9s3/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5vnvp', '5vnvp', 'De Gregório a Raul: literatura baiana em curso, vol. 1', NULL, '["Jorge de Souza Araujo"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O primeiro volume do livro De Gregório a Raul: literatura baiana em curso faz uma análise da produção dos grandes escritores da Bahia, como Gregório de Mattos, Ildefonsa Laura César, Luiz Gama, João Gualberto, entre outros. É uma obra forte, que atravessa a história da Bahia/Brasil a partir da literatura em suas várias épocas. O autor demonstra profundo conhecimento das obras analisadas, dos períodos de surgimento, do contexto histórico/literário, priorizando a análise dos conteúdos e formas culturais do Nordeste, da Bahia.', '["Bahian literature","Luiz Gama","literary history"]', '10.7476/9788574555874', '9788574555621', 'https://books.scielo.org/id/5vnvp', NULL, NULL, 'https://books.scielo.org/id/5vnvp/cover/cover_thumbnail.jpeg', 656, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5vwmw', '5vwmw', 'Pensamento e linguagem: Vygotsky, Wallon, Chomsky e Piaget', NULL, '["Adrián Oscar Dongo-Montoya"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este trabalho analisa as teorias científicas que procuram explicar a aquisição e o desenvolvimento da linguagem e do pensamento sob a perspectiva genética. Essa análise é feita a partir dos debates entre seus expoentes mais ilustres, como Vygotsky, Wallon, Chomsky e Piaget, e dos pontos de convergência e divergência entre eles. Apesar das diferenças, há entre esses pensadores um propósito comum: fundamentar o estudo psicológico daquelas funções sobre bases científicas e genéticas e superar as concepções idealistas e materialistas mecanicistas. Desse modo, Dongo-Montoya retoma o tema da origem do pensamento da linguagem, com o debate entre Vygotsky e Piaget, cujas ideias estiveram presentes nas discussões do século XX. Na sequência, confronta as posições de Wallon e Piaget e de Piaget e Chomsky. Por fim, o autor dedica-se a evidenciar o pensamento mais atual e acabado de Piaget sobre o tema e a apresentar as consequências do desenvolvimento desses debates e dessas teorias sobre pensamento e linguagem para as questões educacionais e pedagógicas atuais.', '["language acquisition","cognitive development","language and thought","Vygotsky","Wallon","Noam Chomsky","Piaget","genetic psychology","origin of thought","educational implications"]', '10.7476/9786557140505', '9786557140505', 'https://books.scielo.org/id/5vwmw', 'https://books.scielo.org/id/5vwmw/pdf/dongo-9786557140505.pdf', NULL, 'https://books.scielo.org/id/5vwmw/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5vx2d', '5vx2d', 'A ciência a caminho da roça: imagens das expedições científicas do Instituto Oswaldo Cruz ao interior do Brasil entre 1911 e 1913', NULL, '["Intituto Oswaldo Cruz. Casa de Oswaldo Cruz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1992, '1992-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '(Ganhador do Prêmio de Excelência Gráfica Werner Klatt 2019) Bela e criteriosa seleção de imagens das expedições científicas do Instituto Oswaldo Cruz ao interior do Brasil nos anos de 1911-1913. Ao percorrer extensas áreas da Amazônia e da região Nordeste, os expedicionários não só realizaram o levantamento das condições médico-sanitárias de tais populações, como também possibilitaram um minucioso registro de aspectos geográficos, econômicos e socioculturais dos lugares visitados. Proporciona uma reflexão em torno da linguagem fotográfica que, conjugada à pesquisa sobre a evolução das políticas públicas, revela aspectos originais da memória da saúde e das ciências biomédicas no Brasil.', '["Instituto Oswaldo Cruz","scientific expeditions","history of medicine","history of public health","photographs","Amazon","Northeast Brazil","health policy","biomedical sciences"]', '10.7476/9788575413074', '9788575413074', 'https://books.scielo.org/id/5vx2d', 'https://books.scielo.org/id/5vx2d/pdf/intituto-9788575413074.pdf', NULL, 'https://books.scielo.org/id/5vx2d/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5vydm', '5vydm', 'Vacinas', NULL, '["Jorlan Fernandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-06-29', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro busca discutir e reforçar o papel das vacinas na prevenção e no controle de doenças infecciosas ao longo da história. Apesar de ter sido idealizada antes da pandemia de Covid-19, a obra é publicada em timing propício e aproveita o alto engajamento da sociedade sobre o tema para aprofundar informações. Integrante da coleção Temas em Saúde, o título reúne pesquisadores e especialistas de diferentes gerações vinculados à Fiocruz. Jorlan Fernandes, Natália Lanzarini, Akira Homma - uma das maiores autoridades em vacinas no mundo - e Elba Lemos abordam questões que se tornaram corriqueiras na agenda pública, como ensaios clínicos, vacina de vetor viral, vacina de mRNA, imunidade de rebanho, hesitação em vacinar, queda na cobertura vacinal e aumento do movimento antivacinas.', '["vaccines","infectious disease prevention","history of vaccination","clinical trials","viral vector vaccines","mRNA vaccines","herd immunity","vaccine hesitancy","vaccine coverage decline","anti-vaccine movement","COVID-19 pandemic"]', '10.7476/9786557081075', '9786557080351', 'https://books.scielo.org/id/5vydm', NULL, NULL, 'https://books.scielo.org/id/5vydm/cover/cover_thumbnail.jpeg', 164, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5wxg8', '5wxg8', 'Educação em Astronomia: reflexões e práticas formativas', NULL, '["Gustavo Iachel","Roberta Chiesa Bartelmebs"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, que surgiu no contexto do Grupo de Pesquisa EnCiMaT: Educação em Ciências, Educação Matemática e TICs no ensino, a partir da linha de Educação em Astronomia, visa dialogar com autoras e autores, pesquisadoras e pesquisadores, professoras e professores que atuam na Educação em Astronomia, seja na escola, seja na universidade. Organizada em duas partes, totaliza 10 capítulos, os quais apresentam pesquisas e ações que podem promover reflexões e mudanças nas práticas de ensino de conceitos ligados à área de Astronomia. Educação em Astronomia: reflexões e práticas formativas traz ao leitor a informação e a formação, com vistas a fazer da ciência uma forma mais respeitada e valorizada de interpretar o mundo ao nosso redor. E faz isso de duas maneiras: foca em aspectos atrelados à prática de sala de aula, ou seja, mais afeitos ao professor em serviço, mas não deixa de oferecer contribuição àqueles que cuidam da formação dos novos professores. Para aqueles em formação, tece olhares a respeito de estratégias para o ensino em sala de aula, mas também aborda reflexões que vão além delas e que são necessárias para entender como a Astronomia contribuiu para nossa ampliação de conhecimento de mundo. Trata-se do terceiro volume da Coleção Ensino de Ciências, organizada pelos pesquisadores Roque Ismael da Costa Güllich, Rosangela Inês Matos Uhmann e Rosemar Ayres dos Santos.', '["astronomy education","teaching practice","classroom strategies","teacher professional development","science education","mathematics education","ICT in teaching"]', '10.7476/9786550190538', '9786550190538', 'https://books.scielo.org/id/5wxg8', 'https://books.scielo.org/id/5wxg8/pdf/iachel-9786550190538.pdf', NULL, 'https://books.scielo.org/id/5wxg8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5xntg', '5xntg', 'Problematizações das figuras da Psicologia Clínica: olhar, cuidar e escutar', NULL, '["Sílvio José Benelli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro, o autor procura entender e sistematizar as coordenadas teóricas, práticas e éticas que fundamentam tais modelos de clínicas nos ensaios escritos nessa investigação, com a intenção de esclarecer e orientar a própria práxis. O objetivo consistiu em problematizar, a partir da práxis, da documentação e da literatura, as possibilidades clínicas no campo da Psicologia, distinguindo e caracterizando seus modelos de atenção e também procurando entender quais são os efeitos éticos promovidos. O autor também buscou trabalhar com o conceito fundamental de subjetividade para pensar e problematizar de modo paradigmático o campo psicológico e a área da clínica, com destaque o conceito de subjetividade numa acepção muito precisa: a que emerge da Psicanálise do campo de Freud e Lacan e o tipo de clínica que daí deriva, como fundamental para um psicólogo que se pretenda psicossocial.', '["clinical psychology","psychoanalytic clinic","subjectivity","psychoanalysis","Sigmund Freud","Jacques Lacan","clinical practice","listening","care","psychosocial practice"]', '10.7476/9786557144558', '9786557144558', 'https://books.scielo.org/id/5xntg', 'https://books.scielo.org/id/5xntg/pdf/benelli-9786557144558.pdf', NULL, 'https://books.scielo.org/id/5xntg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5xrp7', '5xrp7', 'Leite para os Trópicos! Consumo, produção e políticas públicas no Brasil, 1889-1964', NULL, '["Sören Brinkmann"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“Leite para os Tropicos” pode ser localizado na interface entre a história sanitária, econômica e administrativa. Como o trabalho de pesquisa mais abrangente sobre o leite até o momento, o livro enriquece o (extenso) estado da pesquisa sobre a história da intervenção estatal nas áreas de higiene e saúde pública. Ele lança uma luz multifacetada sobre o desenvolvimento e as condições de produção na pecuária leiteira e é um acréscimo importante ao foco clássico na indústria do café no início do século XX. Além disso, este estudo faz um importante trabalho pioneiro com relação ao surgimento de instituições estatais. Usando o exemplo do abastecimento de leite, que se baseava em cadeias de suprimento suprarregionais, Brinkmann mostra quais objetivos concretos de política econômica ou de saúde pública orientavam as autoridades responsáveis em cada um dos momentos examinados.', '["milk supply","dairy farming","public health policy","state intervention in health","economic history","public policy history","supply chain","coffee industry","Brazil"]', '10.7476/9786557082164', '9786557081877', 'https://books.scielo.org/id/5xrp7', NULL, NULL, 'https://books.scielo.org/id/5xrp7/cover/cover_thumbnail.jpeg', 270, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5y76v', '5y76v', 'Trabalhadores, sindicatos e industrialização', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Não teríamos condições de apreciar de modo sistemático a complexidade de situações sindicais e operárias nos diferentes países. Aqui estamos interessados apenas em tentar isolar os principais fatores relacionados à formação do capitalismo europeu e que parecem significativos para a análise das formas de ação e ideologia operárias. [...]', '["workers","trade unions","industrialization","European capitalism","labor movement"]', '10.7476/9788599662991', '9788599662991', 'https://books.scielo.org/id/5y76v', 'https://books.scielo.org/id/5y76v/pdf/rodrigues-9788599662991.pdf', NULL, 'https://books.scielo.org/id/5y76v/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5zb2p', '5zb2p', 'Psiquiatria e Política: o jaleco, a farda e o paletó de Antonio Carlos Pacheco e Silva', NULL, '["Gustavo Querodia Tarelow"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Integrante da coleção História e Saúde, o livro é um estudo da trajetória do professor e psiquiatra Antonio Carlos Pacheco e Silva durante o período 1898-1988. Personagem relevante na história biográfica da medicina e da psiquiatria brasileira do século XX, Silva é retratado em suas muitas contradições, tensões e singularidades nesta obra escrita pelo historiador Gustavo Querodia Tarelow. Para além dos espaços acadêmicos, o personagem angariou cargos políticos, empresariais e militares, tendo sido um ícone do pensamento conservador brasileiro e participando de bandeiras e movimentos ditatoriais do país. O autor do título é pesquisador do Museu Histórico da Faculdade de Medicina da Universidade de São Paulo (FMUSP), instituição em que Pacheco e Silva participou de mecanismos de perseguição política a partir de 1964. A obra é dividida em três capítulos e inclui também notas e álbuns fotográficos com imagens que ilustram as diferentes eras da vida do psiquiatra.', '["history of psychiatry","Brazilian psychiatry","psychiatry and politics","Brazilian conservatism","military dictatorship","political persecution","20th century medicine"]', '10.7476/9786557080184', '9786557080054', 'https://books.scielo.org/id/5zb2p', NULL, NULL, 'https://books.scielo.org/id/5zb2p/cover/cover_thumbnail.jpeg', 293, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5zms8', '5zms8', 'Consciência e matéria: o dualismo de Bergson', NULL, '["Jonas Gonçalves Coelho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro remete a três complexas questões filosóficas as quais abordaremos a partir do pensamento de Bergson: a natureza da consciência, a natureza da matéria e a relação entre consciência e matéria. Tendo em vista os objetivos do presente estudo apresentaremos essa temática, cuja história é longa e tortuosa, a partir daquela que pode ser considerada como a sua formulação paradigmática, a de Descartes, referência teórica fundamental com a qual a tradição filosófica posterior, inclusive contemporânea, dialoga e da qual não consegue se desvencilhar, em que pesem os grandes desenvolvimentos das ciências físicas e biológicas. É por meio de um exercício de aproximação e de distanciamento em relação ao pensamento de Descartes que buscaremos compreender os principais aspectos da filosofia de Bergson e refletir criticamente sobre os seus fundamentos.', '["Henri Bergson","consciousness","matter","dualism","René Descartes","Cartesian dualism","philosophy of mind","philosophy of science"]', '10.7476/9788579831089', '9788579831089', 'https://books.scielo.org/id/5zms8', 'https://books.scielo.org/id/5zms8/pdf/coelho-9788579831089.pdf', NULL, 'https://books.scielo.org/id/5zms8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5zqwp', '5zqwp', 'Saúde e Educação: um encontro plural', NULL, '["Liane Maria Bertucci","André Mota","Lilia Blima Schraiber"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Este livro foi idealizado a partir de nossas conversas sobre a multiplicação de estudos que o tema saúde-educação tem motivado no Brasil entre historiadores e outros pesquisadores que estabeleceram uma interação com a história. Esses estudos, com diferentes enfoques teóricos, segundo nossa perspectiva, precisavam ser reunidos em uma coletânea que fosse composta de trabalhos de historiadores, educadores, médicos e cientistas sociais. [...] Esta coletânea foi organizada com a pretensão de reunir pesquisas e reflexões que, com diferentes perspectivas e objetos específicos, traduzem essa diversidade. Os capítulos que compõem a coletânea estão divididos em três partes. A primeira centra-se na esfera profissional; a segunda, nas campanhas e práticas de prevenção; e a terceira, no universo escolar. [...] Tendo em vista o conjunto dos capítulos aqui apresentados, esperamos que a coletânea permita ao leitor alcançar não só as principais problemáticas da relação entre saúde e educação que se estabeleceram no país como aspectos dos percursos que historicamente foram traçados em sua construção."', '["education and health","history of health education","healthcare workers","school health","school-based health education"]', '10.7476/9786557080603', '9788575415009', 'https://books.scielo.org/id/5zqwp', NULL, NULL, 'https://books.scielo.org/id/5zqwp/cover/cover_thumbnail.jpeg', 326, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-5zs3s', '5zs3s', '"Por que aprender isso, professora?” Sentido pessoal e atividade de estudo na Psicologia Histórico-Cultural', NULL, '["Flávia da Silva Ferreira Asbahr"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro aponta alguns caminhos da pesquisa sobre como crianças entendem e vivenciam sua história escolar e quais os sentidos que atribuem à atividade de estudar. Tendo a Psicologia Histórico-Cultural como referência teórica e larga experiência em projetos da rede de educação pública e privada, Flávia da Silva Ferreira Asbahr desenvolve o trabalho em duas frentes: uma investigação bibliográfica conceitual, com sínteses teóricas sobre os conceitos de sentido pessoal e atividade de estudo; e uma investigação empírica, realizada em escola pública municipal da cidade de São Paulo, com estudantes de quarta série do ensino fundamental. A autora verifica os limites da formação de estudantes na atual organização do ensino público e lança a hipótese sobre qual seria a principal atividade formadora do pensamento teórico para grande parte dos estudantes. Apoiada na categoria da contradição, Asbahr ressalta o papel do professor nesse processo e defende que, para que a aprendizagem escolar ocorra, as ações de estudo devem ter um sentido pessoal para os estudantes.', '["personal meaning","study activity","historical-cultural psychology","school learning","theoretical thinking","contradiction","teacher role","public schools","fourth grade"]', '10.7476/9788595461772', '9788595461772', 'https://books.scielo.org/id/5zs3s', 'https://books.scielo.org/id/5zs3s/pdf/asbahr-9788595461772.pdf', NULL, 'https://books.scielo.org/id/5zs3s/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-622m9', '622m9', 'Autômatos geniais: a mente como sistema emergente e perspectivista', NULL, '["Luiz Henrique de Araújo Dutra"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Neuroscience', 'Este livro retoma alguns dos problemas centrais da Filosofia tradicional da Mente – tal como o dualismo mente-corpo e a natureza da consciência – e procura considerá-los na perspectiva inovadora das teorias recentes sobre a cognição distribuída, a mente estendida e os sistemas complexos. Essas contribuições são associadas a uma concepção emergentista da mente humana, que procura situá-la na rede de processos naturais e sociais que constituem as condições de base para o surgimento da mente e a manutenção de suas funções, especialmente as funções intelectuais superiores, como a consciência reflexiva, a linguagem simbólica, o discernimento, a racionalidade e a consciência moral, aspectos únicos com os quais podemos caracterizar a humanidade plenamente. Além de se valer de teorias e concepções conhecidas, o livro apresenta ideias inovadoras, tal como a caracterização da mente humana como um sistema complexo de cognição e ação distribuídas, isto é, como aquilo que habilita os seres humanos a tomarem parte na riquíssima rede de relações que constitui a sociedade e a cultura em geral. Assim, este livro contribui não apenas para se refletir sobre os temas específicos da Filosofia da Mente, mas também para pensar os fundamentos das Ciências Humanas como aquelas disciplinas que se dedicam ao estudo dos produtos da ação humana em sociedade. A própria mente humana é vista como resultado de processos evolutivos, biológicos e psicológicos, em associação com processos sociais, especialmente a linguagem, cuja relação com o mentalismo humano é indiscutível, mas ainda pouco compreendida pela Filosofia e pelas Ciências.', '["philosophy of mind","mind-body dualism","consciousness","extended mind","distributed cognition","complex systems","emergentism","language and mind","moral consciousness","symbolic language","social cognition","human evolution"]', '10.7476/9788523013387', '9788523012229', 'https://books.scielo.org/id/622m9', NULL, NULL, 'https://books.scielo.org/id/622m9/cover/cover_thumbnail.jpeg', 488, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-628vk', '628vk', 'Objeto, gozo e corpo nas toxicomanias e adições: uma leitura psicanalítica', NULL, '["Carla Oliveira Fernandes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro é fruto de uma pesquisa teórico-clínica fundamentada na experiência com pacientes que recorrem ao uso de drogas como forma de tratamento do sofrimento. A obra apresenta os resultados de uma investigação sobre as especificidades das toxicomanias e das adições, o estatuto do objeto e sua relação com o gozo e o corpo. Além disso, frente a uma variedade de usos e abusos do objeto droga, promove a discussão, a partir de casos clínicos, sobre a singularidade do recurso à droga em cada caso, considerando o tratamento possível pela psicanálise de orientação lacaniana.', '["drug addiction","substance use disorders","Lacanian psychoanalysis","objects","jouissance","body","clinical case","psychoanalytic treatment"]', '10.7476/9786556302027', '9786556300207', 'https://books.scielo.org/id/628vk', NULL, NULL, 'https://books.scielo.org/id/628vk/cover/cover_thumbnail.jpeg', 199, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-62rp6', '62rp6', 'Avança, Brasil: proposta de Governo', NULL, '["Fernando Henríque Cardoso"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Este documento apresenta as diretrizes do programa de governo com as quais se compromete o presidente Fernando Henrique Cardoso, se reeleito para um novo mandato. São diretrizes e metas ao mesmo tempo consistentes e ambiciosas. Consistentes porque se baseiam numa visão realista das possibilidades do país. Ambiciosas porque apontam para uma virada histórica no desenvolvimento da sociedade brasileira. [trecho retirado do livro]', '["Fernando Henrique Cardoso","presidential re-election","government programs","political program","Brazilian politics","economic development","social development"]', '10.7476/9788599662687', '9788599662687', 'https://books.scielo.org/id/62rp6', 'https://books.scielo.org/id/62rp6/pdf/cardoso-9788599662687.pdf', NULL, 'https://books.scielo.org/id/62rp6/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-63mpp', '63mpp', 'Receita de ambrosia: peça didática', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro deriva do poema “Receita de ambrosia”, publicado no livro “Em sobressaltos: formação de professora”. Caracteriza-se como um segundo ato daquele, em duplo sentido: retoma o tema/problema por meio de desdobramento do segundo ato, “O ritual”, e dá continuidade a dois artigos em que tematizo a alfabetização/ensino de língua portuguesa como processo discursivo. O objetivo é problematizar a formação inicial de professores para a compreensão ativa do processo discursivo, considerando que, para ensiná-lo, não basta falar sobre. É necessário também mostrar fazendo nas relações de ensino-aprendizagem de que os futuros professores participam aqui e agora como alunos que se formam para o magistério. Inspiro-me na concepção de “peça didática”, de Bertolt Brecht, com finalidade de “educação estética-política”, por meio da encenação de um “modelo de ação”. A discussão do problema é mostrada em seis cenas que sintetizam momentos “cruciais” das atividades da disciplina Conteúdo, Metodologia e Prática de Ensino: Língua Portuguesa e Literatura Infantil, que ministro no curso de Pedagogia da Faculdade de Filosofia e Ciências da Universidade Estadual Paulista (Unesp), câmpus de Marília. O objetivo, entretanto, não é apresentar modelo a ser copiado ou prescrições a serem seguidas. Embora o termo “receita” (etimologicamente, “recebido”) remeta a discurso instrucional, indicando relação de ingredientes e modo de fazer, o modelo de/em ação aqui encenado se caracteriza como roteiro de uma antirreceita, de um antirritual. Porque igualmente afetada e modificada pela condição de participante-observadora do processo encenado, convido-os a compartilhar esta peça didática como materialização de antigo e ambicioso desejo: que também ela configure um processo discursivo a propiciar experiência formativa aos leitores/espectadores assim como sua elaboração proporcionou a esta pesquisadora-narradora-personagem.', '["didactic play","Bertolt Brecht","initial teacher education","Portuguese language teaching","teaching-learning relationship","pedagogy course","children''s literature","participant-observer"]', '10.7476/9786557140086', '9786557140086', 'https://books.scielo.org/id/63mpp', 'https://books.scielo.org/id/63mpp/pdf/mortatti-9786557140086.pdf', NULL, 'https://books.scielo.org/id/63mpp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-63sd8', '63sd8', 'Agroecologia e desenvolvimento rural sustentável: dinâmicas socioambientais e manejo ecológico', 'dinâmicas socioambientais e manejo ecológico', '["Janete Stoffel","Renata Borges Kempf","Gabriela Silva Moura","Denise Cargnelutti","Rodrigo Ozelame da Silva","Cláudia Simone Madruga Lima"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Agroecologia e Desenvolvimento Rural Sustentável: dinâmicas socioambientais e manejo ecológico" é uma coletânea escrita por 42 autores e autoras, que se constitui de doze capítulos estruturados em três eixos temáticos. No primeiro eixo – Agroecologia, Gênero e Geração – os cinco capítulos abordam questões relacionadas a gênero, sobre a participação e a importância das mulheres rurais na produção e diversificação agroecológica, bem como as estratégias utilizadas na produção de alimentos sustentáveis. Em relação à juventude, são apresentados aspectos sobre a reprodução social de jovens assentados nos estados do Paraná e do Ceará, além da contribuição do ensino de alternância na formação da juventude no campo, assim como os desafios e as estratégias para a construção do Desenvolvimento Rural. O segundo – Circuitos Curtos, Soberania e Segurança Alimentar – reúne três capítulos e inicia com a discussão sobre o direito humano à alimentação, aborda a promoção de segurança alimentar e nutricional a partir das dinâmicas produtivas em assentamentos da Reforma Agrária e o papel de políticas públicas no fortalecimento de sistemas alimentares alternativos baseados em princípios agroecológicos como instrumento da promoção de mecanismos que promovam o encurtamento do processo de produção ao consumo final, principalmente pensando em aspectos que gerem a reorganização do abastecimento alimentar. No terceiro eixo temático – Manejo Agroecológico – são quatro capítulos que relatam os princípios do manejo de pragas nos sistemas agroecológicos, bem como métodos de controle biológico de pragas e/ou mecanismos alternativos de produção.', '["agroecology","sustainable rural development","socio-environmental dynamics","ecological management","agrarian reform settlements","short food circuits","food sovereignty","right to food","food and nutrition security","alternative food systems","public policy","pest control"]', '10.7476/9786550191184', '9786550191207', 'https://books.scielo.org/id/63sd8', 'https://books.scielo.org/id/63sd8/pdf/stoffel-9786550191184.pdf', NULL, 'https://books.scielo.org/id/63sd8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-64c6x', '64c6x', 'Tear de Fios, tecer de mulheres: o tecido narrativo de Helena Parente Cunha', NULL, '["Lílian Almeida de Oliveira Lima"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Escritora brasileira nascida na Bahia, reconhecida nacional e internacionalmente, Helena Parente Cunha assenta seu projeto literário na quebra de paradigmas, na ruptura com os padrões hegemônicos, na desestabilização da lógica falocêntrica. Lílian Almeida de Oliveira Lima analisa em sua pesquisa de doutorado as personagens e estruturas da construção do ser mulher na obra desta autora.', '["women''s writing","representation of women","female identity","narrative structure","Brazilian women writers","Bahian literature","female characters"]', '10.7476/9786588211168', '9788578873356', 'https://books.scielo.org/id/64c6x', 'https://books.scielo.org/id/64c6x/pdf/lima-9786588211168.pdf', 'https://books.scielo.org/id/64c6x/epub/lima-9786588211168.epub', 'https://books.scielo.org/id/64c6x/cover/cover_thumbnail.jpeg', 336, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-64g49', '64g49', 'Rumo ao interior: médicos, saúde da família e mercado de trabalho', NULL, '["Rômulo Maciel Filho","Maria Alice Fernandes Branco"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Um dos grandes desafios para a consolidação do Sistema Único de Saúde (SUS) é a distribuição geográfica dos profissionais e serviços de saúde. Compreender tal desafio e fornecer subsídios para enfrentá-lo são os objetivos dos autores, nesse estudo. A distribuição desigual reflete outro problema: a concentração dos serviços de saúde e das escolas médicas nas regiões economicamente mais favorecidas, facilitando a permanência dos profissionais, depois de formados, no Sul e Sudeste, apesar da expansão dos postos de trabalho no Norte, Nordeste e Centro-Oeste. Quatro programas de interiorização são analisados: o Projeto Rondon, o Programa de Interiorização das Ações de Saúde e Saneamento (Piass), o Programa de Interiorização do SUS (Pisus) e o Programa de Interiorização do Trabalho em Saúde (Pits). Este último, por ser uma iniciativa inédita do Ministério da Saúde, é avaliado em detalhes em um dos capítulos.', '["Family Health Strategy","healthcare workers","health care consolidation","Projeto Rondon","pits","health workforce retention","Unified Health System (SUS)"]', '10.7476/9788575416013', '9788575416013', 'https://books.scielo.org/id/64g49', 'https://books.scielo.org/id/64g49/pdf/romulo-9788575416013.pdf', NULL, 'https://books.scielo.org/id/64g49/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-64kv3', '64kv3', 'Guia de uso do português: confrontando regras e usos', NULL, '["Maria Helena de Moura Neves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Organizado a partir de um estudo exaustivo dos usos vigentes no português contemporâneo do Brasil, informa como são usadas pelos falantes as formas da língua portuguesa. Rejeita a prescrição cega e também o vale-tudo, deixando a escolha para a consciência do leitor. Esta obra dirige-se a qualquer pessoa - estudante, profissional ou simples falante da língua portuguesa - que, em algum momento de desempenho lingüístico, sinta algum tipo de dificuldade na formulação de seu enunciado. Organizada a partir do exame de livros, jornais, revistas e peças teatrais contemporâneos, ela informa como está sendo usada a língua e, quando oportuno, as prescrições que a tradição vem repetindo. Partindo do princípio de que o uso pode contrariar a norma, e o falante tem liberdade de escolha, o livro lhe dá a conhecer os dois lados da questão: o modo como os manuais normativos dizem que "deve ser" o uso, e o modo como, realmente, ele "é".', '["Brazilian Portuguese","language norms","prescriptive grammar","language use","language variation","language teaching","contemporary language use"]', '10.7476/9788539303106', '9788571394575', 'https://books.scielo.org/id/64kv3', NULL, NULL, 'https://books.scielo.org/id/64kv3/cover/cover_thumbnail.jpeg', 830, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-65bdz', '65bdz', 'Fundamentos teóricos e práticos em análise de alimentos', NULL, '["Heloisa Máscia Cecchi"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Esta obra é resultado de 20 anos de docência na área, em cada um dos quais a preparação das aulas era aprimorada, com a elaboração de apostilas para os alunos, as quais se transformaram neste livro-texto. Os capítulos descrevem fundamentos teóricos e experimentos práticos que podem ser utilizados como guia para aulas teóricas e de laboratório da disciplina de análise de alimentos. O livro pode ser utilizado por alunos de graduação e pós-graduação em engenharia de alimentos, farmácia e bioquímica, nutrição, agronomia, química e também nos respectivos cursos técnicos.', '["food analysis","food chemistry","food engineering education","food composition"]', '10.7476/9788526814721', '9788526806412', 'https://books.scielo.org/id/65bdz', NULL, NULL, 'https://books.scielo.org/id/65bdz/cover/cover_thumbnail.jpeg', 206, 256, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-65pmf', '65pmf', 'Prácticas educativas, pedagogía e interculturalidad: V Congreso internacional de etnografía y educación julio de 2020. Modalidad virtual', NULL, '["Rubén Bravo","Sebastián Granda Merchán","Ana María Narváez"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estas páginas constituyen las Memorias del V Congreso Internacional de Etnografía y Educación. Prácticas educativas, pedagogía e interculturalidad (2020) convocado por la Universidad Politécnica Salesiana del Ecuador. En el Congreso participaron investigadores, docentes y estudiantes de México, Argentina, Brasil, Colombia, Chile, Ecuador, Antillas, Estados Unidos, Canadá, Italia, Francia y España con ponencias sobre tres ejes temáticos: Educación, sociedad y política; Escuela, diversidades y exclusiones; y Avances teóricos y metodológicos de la investigación etnográfica en educación. Más de 60 trabajos que amplían las reflexiones y que abren la discusión, desde la antropología y la pedagogía, hacia la construcción de una educación intercultural.', '["intercultural education","ethnography of education","teaching practice","pedagogy","education and society","education and politics","diversity in schools","school exclusion","ethnographic methods","anthropology of education"]', '10.7476/9789978108253', '9789978108253', 'https://books.scielo.org/id/65pmf', 'https://books.scielo.org/id/65pmf/pdf/bravo-9789978108253.pdf', NULL, 'https://books.scielo.org/id/65pmf/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-65tf2', '65tf2', 'Raízes históricas da medicina ocidental', NULL, '["Raymundo Manno Vieira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro tem por objetivo oferecer ao leitor um largo panorama da evolução do cuidado com a saúde, mostrando a multiplicidade e variedade de legados culturais que confluíram na formação do que hoje conhecemos por medicina. Fruto de grande pesquisa de um médico experiente e com vastas leituras de filosofia e história, o volume apresenta em sequência cronológica uma síntese dos preceitos e práticas de diversos povos em sua luta por conhecer e combater as doenças. Desde as remotas civilizações da Mesopotâmia e do Nilo até a Helênica, berço da doutrina hipocrática; desde fenícios, persas, hebreus e etruscos até a Europa Medieval e Islâmica, contemplam-se todas as etapas e facetas do processo que, na Renascença e no Século das Luzes, ensejou a transformação das artes médicas numa ciência moderna. Uma obra de consulta útil tanto para o leigo interessado em conhecer a genealogia da ciência médica como para o estudante, o docente e o profissional que queira ampliar seus horizontes para além dos limites de sua especialidade.', '["history of medicine","ancient medicine","Mesopotamian medicine","Egyptian medicine","ancient Greek medicine","Persian medicine","medieval medicine","Islamic medicine","Renaissance medicine","Enlightenment medicine"]', '10.7476/9788561673321', '9788561673321', 'https://books.scielo.org/id/65tf2', NULL, NULL, 'https://books.scielo.org/id/65tf2/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-65ywx', '65ywx', 'O tradutor-intérprete de Libras escolar, seu conhecimento de Física e a percepção de sua práxis', NULL, '["Camila Gasparin"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta obra objetiva ser um material informativo para todos os interessados em inclusão de surdos, sejam estudantes, profissionais da educação ou familiares buscando orientação inicial quanto à legislação de inclusão, educação especial, especificidades da formação do intérprete e sua atuação com os estudantes surdos no dia a dia escolar. A partir da pesquisa desenvolvida no Mestrado, a autora busca contribuir para a efetiva inclusão dos surdos, o acesso ao sagrado direito ao conhecimento, a vivência escolar prazerosa e para a construção de um futuro acadêmico e profissional brilhante para todos, sejam eles surdos, ouvintes, cegos ou que tenham qualquer necessidade específica. “O tradutor-intérprete de Libras escolar, seu conhecimento de Física e a percepção de sua práxis” constitui-se de duas partes; na primeira, apresenta o embasamento teórico utilizado na pesquisa da qual se originou o livro. Nela se encontram, portanto, o histórico da educação de surdos no mundo e no Brasil, seu arcabouço legal e seu desenvolvimento histórico, a formação dos intérpretes de Libras no país e sua atuação profissional, o ensino de Física, as misconceptions dos conceitos de Física presentes após a educação formal de nível básico e o conhecimento de Física dos intérpretes de Libras. Na segunda, que mostra o resultado da pesquisa aplicada, se apresentam a percepção da práxis pelo intérprete de Libras, a sua visão quanto à inclusão do surdo no ambiente escolar de acordo com a legislação atual, os aspectos que afetam a atuação profissional dos intérpretes de Libras e a sua relação com professores de Física.', '["Brazilian Sign Language (Libras)","deaf students","inclusive education","physics misconceptions","physics education","interpreter training","deaf education legislation"]', '10.7476/9786550190507', '9786550190507', 'https://books.scielo.org/id/65ywx', 'https://books.scielo.org/id/65ywx/pdf/gasparin-9786550190507.pdf', NULL, 'https://books.scielo.org/id/65ywx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6654j', '6654j', 'Vidas e doutrinas dos filósofos ilustres', NULL, '["Diogênes Laêrtios"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 1970, '1970-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Vidas e doutrinas dos filósofos ilustres, de Diôgenes Laêrtios, é a mais preciosa obra conservada da Antiguidade a respeito da história da filosofia e dos filósofos gregos. Esta obra constitui a fonte principal para o conhecimento das filosofias epicurista e estóica, e é importante para o estudo do ceticismo e das ramificações da filosofia socrática (o cinismo, o hedonismo e a dialética). Nela, o autor expõe as idéias dos mais importantes pensadores gregos, desde as origens da filosofia e dos chamados Sete Sábios até os últimos escolarcas da Academia platônica e do Liceu aristotélico, abrangendo cerca de oitenta filósofos. Por serem antes uma história dos filósofos do que uma história da filosofia, os capítulos que compõem este livro pertencem tanto à literatura quanto à filosofia propriamente dita. Essa característica confere um interesse ainda maior à obra, principalmente por seu conteúdo humano. Outro de seus méritos é a evocação palpitante da atmosfera do mundo em que viveram os filósofos antigos, graças aos numerosos detalhes que apresenta e aos elementos míticos e fantásticos misturados a anedotas de sabor popular. Esses detalhes, aparentemente marginais, são na realidade muito significativos e esclarecedores.', '["Diogenes Laertius","Lives of Eminent Philosophers","ancient Greek philosophy","history of philosophy","Epicureanism","Stoicism","cynicism","hedonism","Socratic philosophy","Platonism","Aristotelianism","Seven Sages"]', '10.7476/9786558461623', '9788523004798', 'https://books.scielo.org/id/6654j', NULL, NULL, 'https://books.scielo.org/id/6654j/cover/cover_thumbnail.jpeg', 360, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-67y3k', '67y3k', 'Rosae: linguística histórica, história das línguas e outras histórias', NULL, '["Tânia Lobo","Zenaide de Oliveira Novais Carneiro","Juliana Soledade","Ariadne Almeida","Silvana Soares Costa Ribeiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Publicada pela EDUFBA e organizada por Tânia Lobo, Zenaide Carneiro, Juliana Soledade, Ariadne Almeida e Silvana Ribeiro, a obra é constituída por 48 artigos que apresentam investigações sobre o português arcaico e o português brasileiro com intuito de prestar homenagem à Profa. Dra. Rosa Virgínia Mattos e Silva, Professora Titular de Língua Portuguesa e Professora Emérita da Universidade Federal da Bahia (UFBA), falecida em julho de 2012.', '["historical linguistics","language history","archaic Portuguese","Brazilian Portuguese","Portuguese language"]', '10.7476/9788523212308', '9788523212308', 'https://books.scielo.org/id/67y3k', 'https://books.scielo.org/id/67y3k/pdf/lobo-9788523212308.pdf', NULL, 'https://books.scielo.org/id/67y3k/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-68', '68', 'Difusão e cultura científica: alguns recortes', NULL, '["Cristiane de Magalhães Porto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro tem como objetivo oferecer uma discussão mais ampla sobre o tema, possibilitado, com isso, a formação de uma cultura científica no Brasil. O livro oferecerá aos leitores textos interdisciplinares que abordam a ciência no momento contemporâneo e evolui, ao passo da leitura, para as formas da difusão científica nos diversos campos do conhecimento.', '["science communication","scientific culture","contemporary science"]', '10.7476/9788523209124', '9788523209124', 'https://books.scielo.org/id/68', 'https://books.scielo.org/id/68/pdf/porto-9788523209124.pdf', NULL, 'https://books.scielo.org/id/68/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-688yb', '688yb', 'Insatisfechos Suramérica y las protestas sociales en 2019 analizadas en la obra de Fabio Mota', NULL, '["Omar Alonso García-Martínez"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La masa se agita, los llamados a participar en las marchas están en la agenda del día. El bullir de nervios frente a la desigualdad y el cinismo de los dirigentes colma la paciencia del pueblo. El inconformismo crece. Sucumbir a las provocaciones del sistema en silenciosas obediencias no es más una opción. Hay que levantar la voz, el puño, soportar el sol en los rostros durante los largos y agotadores días de marcha, convivir con la lluvia y llevar los cuerpos al límite del cansancio.', '["social protest","2019 protests","social discontent","inequality","political leadership","protest marches","Latin America"]', '10.7476/9786287725140', '9786289526202', 'https://books.scielo.org/id/688yb', 'https://books.scielo.org/id/688yb/pdf/garciamartinez-9786287725140.pdf', NULL, 'https://books.scielo.org/id/688yb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-68jj8', '68jj8', 'Acesso à saúde como direito: caminhos entre o legal e o real', 'caminhos entre o legal e o real', '["Luciane Cristina Feltrin de Oliveira","Maria Ângela Alves do Nascimento"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Diante das dificuldades de acesso à saúde de forma integral enfrentadas pela população brasileira, e da discussão global de como estabelecer um parâmetro, ou um nível de prestação à saúde a ser exigido e garantido pelas políticas públicas. Esta coletânea possibilita reflexões sobre a temática, discutindo as dimensões e os desafios para o acessoa igualitário e integral.', '["right to health","health care access","health equity","comprehensive health care","health policy","public health policy","healthcare quality standards","Brazil"]', '10.7476/9788555921728', '9786589524717', 'https://books.scielo.org/id/68jj8', 'https://books.scielo.org/id/68jj8/pdf/oliveira-9788555921728.pdf', NULL, 'https://books.scielo.org/id/68jj8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-68sth', '68sth', 'Entre o segredo e a solidão: aborto ilegal na adolescência', NULL, '["Wendell Ferrari"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-05-04', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O objetivo central deste livro é apresentar contribuições da pesquisa empírica realizada com adolescentes de uma favela do Rio de Janeiro para a compreensão da prática clandestina do aborto nesse período da vida. O trabalho de pesquisa qualitativa teve como fio condutor o estudo da sexualidade, de modo a produzir dados sobre a iniciação sexual, a reprodução, a contracepção, as relações entre os pares em conexão com a escolarização, entre outras intersecções. Wendell Ferrari consegue de forma extremamente competente e sensível acessar uma rede de adolescentes que realizaram aborto ilegal. O autor transmite segurança e discrição altamente necessárias para a criação de uma atmosfera de confiança tratando com respeito de um assunto não confidenciado com outras pessoas além de amigas e/ou parceiros.', '["illegal abortion","adolescent girls","sexual initiation","contraception","reproductive health","peer relationships","school education","favela youth","secrecy"]', '10.7476/9786557081037', '9786557080078', 'https://books.scielo.org/id/68sth', NULL, NULL, 'https://books.scielo.org/id/68sth/cover/cover_thumbnail.jpeg', 316, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
