INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-69k3v', '69k3v', 'Diretrizes de auditoria ambiental', NULL, '["Celso Maran de Oliveira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este livro se propõe a ser um contributo nos campos científico e profissional. No campo científico, por ser um movimento relativamente recente, mesmo em nível internacional, suscita reflexões no meio científico, na forma de discutir a importância da auditoria como instrumento de apoio à gestão e à atuação ética dos profissionais envolvidos na auditoria, bem como o papel que a auditoria ambiental desempenhará na gestão corporativa. No campo profissional, o objetivo é proporcionar reflexões aos profissionais da área sobre o contributo da auditoria ambiental para a gestão mais eficaz, bem como o reconhecimento das funções destes profissionais, internos ou externos, ligados à auditoria.', '["environmental auditing","auditing guidelines","business management","environmental management"]', '10.7476/9788576004554', '9788576004554', 'https://books.scielo.org/id/69k3v', 'https://books.scielo.org/id/69k3v/pdf/oliveira-9788576004554.pdf', NULL, 'https://books.scielo.org/id/69k3v/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-69w3p', '69w3p', 'Para ler Gaston Bachelard: ciência e arte', NULL, '["Catarina Sant’Anna"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Com suas análises engenhosas e sua retórica brilhante, G. Bachelard soube renovar a psicologia e o espírito científico em suas vitórias contra os obstáculos epistemológicos, assim como soube lançar um olhar sobre as formas e poderes da imaginação poética em comércio com a Natureza e/ou com os objetos os mais familiares de nosso quotidiano. O interesse e a riqueza dessa obra coletiva recaem sobre as invenções e as tomadas de posição teóricas de G. Bachelard nos domínios da epistemologia como da poética, retomando deles a gênese, o sentido e o alcance, iluminando-os através de estudos comparatistas das convergências e divergências com outros pensadores.', '["Gaston Bachelard","art and science","epistemology","poetics","imagination","scientific imagination","psychology","nature","everyday objects","comparative philosophy"]', '10.7476/9788523212131', '9788523206994', 'https://books.scielo.org/id/69w3p', NULL, NULL, 'https://books.scielo.org/id/69w3p/cover/cover_thumbnail.jpeg', 342, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-69ysj', '69ysj', 'Infâncias perdidas o cotidiano nos internatos-prisão', NULL, '["Sônia Altoé"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A adolescência tem sido tema de interesse tanto em estudos no campo da psicologia do desenvolvimento quanto na psicologia social. Este estudo trata-se de uma pesquisa qualitativa e exploratória, onde o objetivo geral foi investigar como adolescentes em abrigamento concebem esta fase de sua vida dentro do abrigo, e os objetivos específicos averiguar se as adolescentes participantes têm planos para o futuro, verificar o que mudariam no abrigo, investigar o que significa o fechamento do abrigo e verificar, junto as adolescentes participantes, se há dificuldades em estabelecer relações interpessoais dentro do abrigo. A análise teve como base a abordagem sócio-histórica que entende a adolescência como uma categoria historicamente construída. As participantes foram sete adolescentes negras, do sexo feminino, com idades entre 12 e 17 anos, na unidade de acolhimento Abrigo Beija Flor, em Nova Iguaçu (RJ). O instrumento utilizado foi questionário aberto e as respostas foram categorizadas de acordo com a análise de conteúdo (Bardin, 2016). Os resultados apontaram perspectiva de adolescência difícil, abandonada e incompreendida, revelando que as adolescentes julgam dificuldade em viver essa fase de sua vida em unidade de acolhimento e em fazer amizades. Consideraram existência de aspectos positivos e negativos em unidade de acolhimento, apontaram necessidade de mudanças no ambiente físico e psicológico. Planos para o futuro permeado de sonhos e fechamento revelou, entre as adolescentes participantes, tristeza, abandono, injustiça e culpa. Promover diálogo em acolhimento institucional é primordial para compreensão do que é capturado a partir dos olhares das adolescentes sobre a adolescência através das paredes do acolhimento institucional servindo para ampliar, e lidar, com as multifacetadas formas de adolescer em unidade de acolhimento', '["institutionalized adolescents","adolescent girls","residential care","orphanages","adolescence","interpersonal relationships","future plans","abandonment","institutional care","socio-historical approach","Black girls","Nova Iguaçu"]', '10.7476/9788599662946', '9788599662946', 'https://books.scielo.org/id/69ysj', 'https://books.scielo.org/id/69ysj/pdf/altoe-9788599662946.pdf', NULL, 'https://books.scielo.org/id/69ysj/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6bhc8', '6bhc8', 'Leituras e releituras românticas: José de Espronceda e Álvares de Azevedo', NULL, '["Maira Angélica Pandolfi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro trata da obra de dois escritores: o espanhol José de Espronceda y Delgado (1808-1842) e o brasileiro Manuel Antônio Álvares de Azevedo (1831-1852), ambos considerados expoentes de uma corrente noturna do Romantismo. A análise comparativa mostra o apreço que nutriram por obras, temas, arquétipos e outros elementos comuns em voga no romantismo europeu. Personagens que retomam o arquétipo do herói byroniano e sua problemática psique, a vaidade fáustica, a sedução donjuanesca, a bela e a fera habitando o mesmo ser, a loucura, o amor, a morte e uma profusão de imagens que simbolizam a complexa teia de sentimentos díspares, ambíguos e violentos que emergem do inconsciente. A forma com que cada escritor relê esses elementos deixa entrever motivações de cunho estético e/ou político e acabam produzindo obras que remetem, por meio de um sistema simbólico transnacional, uma revisão das polêmicas locais. O florescimento do espírito revolucionário romântico impulsionou a leitura e a releitura de velhos mitos renascentistas para fazê-los ressurgir sob uma nova roupagem.', '["José de Espronceda","Romanticism","comparative literature","literary reception","madness","love","death","Spanish Romanticism","Brazilian Romanticism","literary archetypes"]', '10.7476/9788595463363', '9788595463363', 'https://books.scielo.org/id/6bhc8', 'https://books.scielo.org/id/6bhc8/pdf/pandolfi-9788595463363.pdf', NULL, 'https://books.scielo.org/id/6bhc8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6bjnp', '6bjnp', 'Raça como questão: história, ciência e identidades no Brasil', NULL, '["Marcos Chor Maio","Ricardo Ventura Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra é uma reunião de ensaios, não cronológicos, cuidadosamente selecionados pelos organizadores, que vão da biologia às ciências sociais, antropologia e história, com variados enfoques. Analisando discussões sobre o pensamento higienista e trajetórias da antropologia física no Brasil do século XIX, os artigos abrangem até as atuais correlações do pensamento racial com as tecnologias genômicas. Precioso material para quem estuda e se interessa pelas questões relacionadas à raça no Brasil.', '["race","racial thought","history of race","physical anthropology","hygienism","scientific racism","racial identity","genomic technologies","race and science","race and history","Brazil"]', '10.7476/9788575413586', '9788575411933', 'https://books.scielo.org/id/6bjnp', NULL, NULL, 'https://books.scielo.org/id/6bjnp/cover/cover_thumbnail.jpeg', 316, 38, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6bmrk', '6bmrk', 'Vigilância sanitária: temas para debate', NULL, '["Ediná Alves Costa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro pretende contribuir no ensino de vigilância sanitária, com um conjunto de temas, cuja seleção não pretendeu ser exaustiva, levando em conta sua presença constante nos cursos, a disponibilidade já de alguns textos e a experiência desenvolvida no Instituto de Saúde Coletiva/ UFBA no ensino de vigilância sanitária em seus vários níveis.', '["disease surveillance","public health education","health education curriculum","collective health"]', '10.7476/9788523208813', '9788523208813', 'https://books.scielo.org/id/6bmrk', 'https://books.scielo.org/id/6bmrk/pdf/costa-9788523208813.pdf', NULL, 'https://books.scielo.org/id/6bmrk/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6bw3d', '6bw3d', 'A promessa de pacificação: a favela em discurso', 'a favela em discurso', '["Liliane Souza dos Anjos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Fruto de uma premiada pesquisa de doutorado, este livro convida o leitor a explorar os discursos que sustentam a promessa de pacificação das favelas do Rio de Janeiro. Fundamentado na Análise do Discurso materialista, o estudo desvenda a promessa como mecanismo discursivo de um compromisso assumido juridicamente. Ao mobilizar saberes relacionados aos estudos performativos, a obra desconstrói as condições de felicidade associadas ao ato de fala “prometer”, expondo seu funcionamento político e problematizando sentidos reducionistas atribuídos às favelas. Observando o entrelaçar de efeitos de promessa e ameaça, a análise revela a tensa relação entre Estado e favela, marcada pela memória histórica de apartação e pelo racismo estrutural. Com uma análise contundente, este livro desafia o leitor a se aprofundar no funcionamento da linguagem e a refletir sobre as dinâmicas de exclusão que estruturam a relação entre cidade e favela, convidando-o a um olhar mais crítico sobre essas questões.', '["favelas","Rio de Janeiro favelas","discourse analysis","materialist discourse analysis","performativity","structural racism","historical memory","urban exclusion","language and power"]', '10.7476/9786557145579', '9786557145579', 'https://books.scielo.org/id/6bw3d', 'https://books.scielo.org/id/6bw3d/pdf/anjos-9786557145579.pdf', NULL, 'https://books.scielo.org/id/6bw3d/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6cfsw', '6cfsw', 'Ao fim da cidade', NULL, '["André Prado"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ao fim da cidade apresenta uma abrangente análise de um dos elementos mais marcantes da paisagem das cidades e de suas periferias: os conjuntos habitacionais populares. Trata-se de uma minuciosa exploração de nove conjuntos habitacionais construídos no município de Belo Horizonte, incluindo desde características físicas e ambientais das moradias até sua inserção e diálogo com os fragmentos de cidade que os envolvem. Situado na interface entre os estudos sobre políticas de habitação de interesse social gestadas nas últimas décadas e a identificação de conflitos socioambientais delas decorrentes, o livro avança com sensibilidade na compreensão das formas de expansão urbana e de consolidação de territórios populares, contribuindo assim para a construção de uma ecologia política da urbanização brasileira contemporânea.', '["urban periphery","social housing policy","socio-environmental conflicts","urban expansion","popular territories","Belo Horizonte"]', '10.7476/9788542302899', '9788542302042', 'https://books.scielo.org/id/6cfsw', NULL, NULL, 'https://books.scielo.org/id/6cfsw/cover/cover_thumbnail.jpeg', 338, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6cn9c', '6cn9c', 'Arquitetura da informação pervasiva', NULL, '["Borsetti Gregorio Vidotti, Silvana Ap.","Cruz de Oliveira, Henry Poncio","Virgínia Bentes"]', 'BiblioBoard Library Catalog (Open Research Library)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é indicado não apenas para estudantes, profissionais e pesquisadores que trabalhem com Ciência da Informação e Arquitetura da Informação, mas também para todos que militem em áreas como a ciência da computação, comunicação, arquitetura, design gráfico e outras. Os autores, primeiramente, contextualizam as dinâmicas sociotecnológicas pertinentes ao mundo contemporâneo; posteriormente, apresentam a Arquitetura da Informação sob diversos aspectos – discutindo o tema por um viés epistêmico – e discutem a Arquitetura da Informação sob quatro diferentes abordagens – arquitetural, sistêmica, informacional e pervasiva. Por fim, analisam o tema que é objeto central da obra: a Arquitetura da informação pervasiva.', '["information architecture","ubiquitous computing","systems approach","information design","architecture and design"]', '10.7476/9788579836671', '9788579836671', 'https://books.scielo.org/id/6cn9c', 'https://static.scielo.org/scielobooks/6cn9c/pdf/oliveira-9788579836671.pdf', NULL, 'https://books.scielo.org/id/6cn9c/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6d2bj', '6d2bj', 'Dinâmica do relevo: quantificação de processos formadores', NULL, '["Peter Christian Hackspacher"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'Nesta obra organizada por Peter Christian Hackspacher, estão reunidos especialistas para analisar, de modo geral e sucinto, alguns importantes assuntos relacionados à Geologia estrutural, à Geomorfologia e à Estratigrafia: os conceitos de calor e de transporte na crosta terrestre; a aplicação de mode­los numéricos termais na Geomorfologia; a evolução do relevo a partir da relação entre tectônica e sedimentação; os fatores exógenos de elaboração do relevo; a evolução do relevo a partir de escarpas e as antigas superfícies geomórficas; os métodos termocronológicos. Um livro original, que trata o tema de modo o mais próximo possível da realidade nacional e demonstra como a evolução do relevo implica diretamente uma diversidade de consequências quanto à forma e ao uso da terra. Uma importante contribuição para o meio acadêmico e científico sobre a dinâmica do relevo.', '["relief dynamics","landscape evolution","exogenic processes","escarpment","thermochronology","structural geology","stratigraphy"]', '10.7476/9786557145234', '9786557145234', 'https://books.scielo.org/id/6d2bj', 'https://books.scielo.org/id/6d2bj/pdf/hackspacher-9786557145234.pdf', NULL, 'https://books.scielo.org/id/6d2bj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6djz9', '6djz9', 'África, margens e oceanos: perspectivas de história social', NULL, '["Reginaldo, Lucilene","Ferreira, Roquinaldo"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Desde meados dos anos 2000, a produção africanista brasileira vem destacando-se no cenário internacional por suas contribuições originais. Este livro apresenta alguns desses aportes, tais como a ênfase na história social e o protagonismo de atores africanos. Ao mesmo tempo, destaca as referências intelectuais e os contornos sociais que demarcam a produção sobre história da África no Brasil, evidenciando a relevância dos estudos sobre o tráfico, o interesse pelas experiências dos escravizados e as demandas dos movimentos negros na sua constituição. Coloca em relevo também os diálogos estabelecidos com a historiografia africanista estrangeira, seja ela produzida em centros de pesquisa norte-americanos, europeus ou africanos. Além disso, explora os limites e alarga os horizontes das pesquisas realizadas no Brasil, chamando atenção para temas e cenários ainda pouco explorados, notadamente as conexões do Índico com a África, as Américas e a Ásia. Por fim, mas não menos importante, aborda questões relativas ao ensino de história da África, enfatizando sua relação com os estudos acadêmicos e com as políticas públicas de combate ao racismo no Brasil.', '["African history","African agency","slave trade","Black movement","transatlantic connections","Indian Ocean","history education"]', '10.7476/9788526815339', '9786586253665', 'https://books.scielo.org/id/6djz9', NULL, NULL, 'https://books.scielo.org/id/6djz9/cover/cover_thumbnail.jpeg', 560, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6dk6p', '6dk6p', 'Profissão farmacêutica em São Paulo: prática científica, ensino e gênero, 1895-1917', NULL, '["Isabella Bonaventura"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Eis uma história de purificações e misturas ali onde purificar e misturar são o nome do jogo: a farmácia científica. No caso, a de São Paulo, entre 1895 e 1917. Seus ritos de institucionalização, operando fronteiras e alianças entre médicos e farmacêuticos, o científico e o não científico, a saúde pública e o comércio, instruem a narrativa de Isabella Bonaventura. A autora ainda combina duas perspectivas – a dos estudos de gênero e a dos Science Studies – que afrontam os cânones normalmente mobilizados nas fontes históricas. Entram em cena mulheres e não humanos, cujas atuações foram tão presentes quanto sombreadas pela produção dominante do conhecimento. E assim o foram pelas arraigadas premissas de que, por um lado, ciência não tem gênero (o que levou à prevalência do gênero não marcado, o masculino), e, por outro, de que as coisas ou subordinam-se às pessoas ou vice-versa.', '["history of pharmacy","gender","women in pharmacy","pharmacy education","institutionalization of science","public health","commerce","non-human actors","science studies","São Paulo"]', '10.7476/9786557080887', '9786557080269', 'https://books.scielo.org/id/6dk6p', NULL, NULL, 'https://books.scielo.org/id/6dk6p/cover/cover_thumbnail.jpeg', 236, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6f3kk', '6f3kk', 'Vidas em exclusão e a reinvenção do cuidado', NULL, '["Roberta Gondim de Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-12-13', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'A obra move-se astuciosamente entre as diferentes escalas que nos permitem entender os debates sobre o conhecimento em saúde e as práticas de cuidado que procuram resgatar os valores do cuidado, da solidariedade e da dignidade.', '["care practices","social exclusion","health knowledge","solidarity","human dignity","care ethics"]', '10.7476/9786557081549', '9786557080504', 'https://books.scielo.org/id/6f3kk', NULL, NULL, 'https://books.scielo.org/id/6f3kk/cover/cover_thumbnail.jpeg', 204, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6ft6m', '6ft6m', 'Como é possível o conhecimento matemático? As estruturas lógico-matemática a partir da Epistemologia Genética', NULL, '["Alexandre Augusto Ferraz","Ricardo Pereira Tassinari"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, a partir da Epistemologia Genética, objetiva-se explicitar como se constroem estruturas presentes e necessárias na Lógica e na Matemática, através de relações entre estruturas epistêmico-psicológicas, estudadas na Psicologia Genética, e estruturas abstratas, estudadas na Lógica e na Matemática.', '["genetic epistemology","genetic psychology","mathematical knowledge construction","abstract structure","logic and mathematics"]', '10.7476/9788579836565', '9788579836565', 'https://books.scielo.org/id/6ft6m', 'https://books.scielo.org/id/6ft6m/pdf/ferraz-9788579836565.pdf', NULL, 'https://books.scielo.org/id/6ft6m/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6fyj3', '6fyj3', 'Saúde mental para a Atenção Básica', NULL, '["Nina Isabel Soalheiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta coletânea analisa diversas temáticas importantes e atuais em saúde mental e atenção psicossocial na rede básica, abordando os conceitos de forma acessível, embora mantendo sua complexidade. Baseados em pesquisas sobre cuidado em saúde mental na Estratégia Saúde da Família no Rio de Janeiro, os textos convidam o leitor a exercitar uma aproximação entre questões acadêmicas e práticas de cuidado no território. Os autores - profissionais com larga experiência de trabalho neste campo - buscam sistematizar e coletivizar saberes e práticas de forma a estimular as equipes de atenção básica a construírem e renovarem abordagens na perspectiva da desinstitucionalização. Segundo a organizadora, o entendimento de desinstitucionalização defendido no livro é aquele “que nos impulsiona para uma cultura do cuidado em instituições abertas e com um estilo coletivo de trabalho”. Diversas questões são colocadas em perspectiva, no sentido de ampliar os aspectos envolvidos no adoecimento com sofrimento psíquico, como a cultura e o ambiente em que se vive. A direção apontada é a da superação da dicotomia corpo-mente, destacando-se que a atenção psicossocial exige um cuidado interdisciplinar, integralizado e territorial.', '["mental health","primary care","psychosocial care","Family Health Strategy","deinstitutionalization","culture of care","mind-body dichotomy","multidisciplinary care","territorial care","mental illness","Rio de Janeiro"]', '10.7476/9786557082928', '9788575414958', 'https://books.scielo.org/id/6fyj3', 'https://books.scielo.org/id/6fyj3/pdf/soalheiro-9786557082928.pdf', NULL, 'https://books.scielo.org/id/6fyj3/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6g398', '6g398', 'Portugal d''agora', NULL, '["João do Rio"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No início de fevereiro de 1912, Portugal d’agora, um novo livro do festejado escritor João do Rio, impresso em Paris em fins do ano anterior, com crônicas sobre Portugal, foi exposto no estabelecimento do livreiro e editor Garnier, localizado na Rua do Ouvidor. Publicadas originalmente em jornais, as crônicas acabaram ficando com problemas de edição e discrepâncias na edição original em livro. Após minucioso trabalho de pesquisa e cotejo, as organizadoras deste volume logram disponibilizar enfim ao leitor os textos em seu estado integral e livres de erros, em crônicas que mostram um João do Rio em sua melhor forma.', '["João do Rio","Portuguese chronicles","Portuguese literature","textual editing","critical edition","Portuguese emigration"]', '10.7476/9786557146095', '9786557146095', 'https://books.scielo.org/id/6g398', 'https://books.scielo.org/id/6g398/pdf/rio-9786557146095.pdf', NULL, 'https://books.scielo.org/id/6g398/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6ght7', '6ght7', 'O projeto literário de Roberto Bolaño', 'estética do fracasso', '["Júlia Morena Costa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro é fruto de uma pesquisa cuidadosa e intensa que analisa toda a obra narrativa de Roberto Bolaño publicada em vida. A autora evidencia a narrativa de Bolaño como um projeto literário que, diante das desilusões e desafios estéticos e políticos vivenciados por sua geração, cria uma obra inovadora e crítica, que reposiciona o fazer literário latino-americano. Ao propor a leitura dos textos de Bolaño como um projeto inter-relacionado, Júlia Morena Costa faz uma incursão na obra deste que é considerado um dos maiores escritores latino-americanos, propondo analisar como o autor respondeu esteticamente ao duplo fracasso, estético e político, vivenciado pela América Latina no século XX.', '["Roberto Bolaño","literary project","Latin American narrative","Latin American literature","political failure","literary innovation","intertextuality"]', '10.7476/9786556308784', '9786556304779', 'https://books.scielo.org/id/6ght7', NULL, NULL, 'https://books.scielo.org/id/6ght7/cover/cover_thumbnail.jpeg', 333, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6gn4x', '6gn4x', 'Aplicativos de notícias, destacamento e efeitos de sentidos: representações internacionais sobre o Brasil (em UOL e Le Monde)', NULL, '["Érika de Moraes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No cenário da comunicação digital, a crescente influência dos aplicativos de notícias – que abastecem instantaneamente o usuário por meio de um feed, com recortes de atualidades considerados relevantes – é decisiva para a construção de efeitos de sentidos a respeito dos fatos divulgados e consequentes registros de memória. Este livro deriva de ampla pesquisa que investigou esses efeitos em notícias veiculadas em dois aplicativos, um nacional (UOL, vinculado a um dos portais mais acessados do país, que divulga conteúdo do jornal Folha de S.Paulo) e um internacional (Le Monde), com respaldo no quadro teórico-metodológico da Análise do Discurso de linha francesa, priorizando as noções de destacamento e destacabilidade. Em seu conjunto, os capítulos do livro permitem o aprofundamento da visão sobre a cobertura midiática a respeito do Brasil em nível internacional. Os resultados demonstram que a constituição de identidades é amplamente afetada pelos modos de funcionamento jornalístico, cuja discursividade pauta-se no que chamamos de uma sintaxe do destacamento.', '["news apps","news feeds","effects of meaning","UOL","Le Monde","online news","identity construction","French discourse analysis"]', '10.7476/9788595463325', '9788595463325', 'https://books.scielo.org/id/6gn4x', 'https://books.scielo.org/id/6gn4x/pdf/moraes-9788595463325.pdf', NULL, 'https://books.scielo.org/id/6gn4x/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6gsm7', '6gsm7', 'Depressão: clínica, crítica e ética', NULL, '["Orlando Coser"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro podemos entender a complexidade de questões associadas à depressão, desde suas origens como subproduto do contexto cultural contemporâneo ao horizonte mercadológico em que é alardeada como ''mal do século'' e fármacos são anunciados como ''milagrosos''. É nesse contexto de alarde e extrema variedade de informações pouco precisas e confiáveis que ele se torna importante e oportuno. O autor, contemplando a necessidade de precisar o conceito de depressão para problematizar criticamente tal processo, nos convida a repensar a clínica e sua respectiva ética, revitalizando o saber e a prática do psiquiatra e do psicanalista e a própria noção de doença como experiência vivida.', '["depression","clinical psychiatry","psychoanalysis","pharmaceutical advertising","concept of disease","illness experience","psychiatric ethics"]', '10.7476/9788575412558', '9788575412558', 'https://books.scielo.org/id/6gsm7', 'https://books.scielo.org/id/6gsm7/pdf/coser-9788575412558.pdf', NULL, 'https://books.scielo.org/id/6gsm7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6gstt', '6gstt', 'Dar à luz na sombra: exercício da maternidade na prisão', NULL, '["Ana Gabriela Mendes Braga","Bruna Angotti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro procura identificar necessidades, detectar entraves e elaborar estratégias para garantia do exercício de direitos materno-reprodutivos no sistema prisional brasileiro. Por meio da observação de estabelecimentos prisionais, da realização de grupo focal com presas e de entrevistas com especialistas, as autoras puderam identificar, no fluxograma do sistema de justiça, os entraves e as lacunas que impedem detentas de terem seus direitos efetivados; mapear a percepção de mães presas do tratamento jurídico-penal-social que lhes é concedido e granjear suas propostas para realização do exercício da maternidade na condição adversa em que se encontram. Como resultado da pesquisa, foram elaboradas trinta propostas sobre desencarceramento, convivência familiar e fluxo do sistema de justiça, se não para diminuir a população prisional feminina, pelo menos para reduzir as violações de direitos e as consequências do aprisionamento. Assim, este livro busca contribuir para o desenvolvimento e a divulgação da pesquisa empírica em Direito e para os avanços na defesa dos direitos de mulheres e crianças encarceradas no Brasil.', '["incarcerated mothers","reproductive rights","women prisoners","Brazilian prison system","family visits","decarceration","rights violations","women''s rights","children in prison","criminal justice system"]', '10.7476/9788595463417', '9788595463417', 'https://books.scielo.org/id/6gstt', 'https://books.scielo.org/id/6gstt/pdf/braga-9788595463417.pdf', NULL, 'https://books.scielo.org/id/6gstt/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6h39q', '6h39q', 'La lucha por el agua: gestión Comunitaria del Proyecto de Agua Potable Pesillo-Imbabura', NULL, '["José Manuel Perugachi Cachimuel","Charles Cachipuendo"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'El enfoque de la gestión comunitaria del agua en el Ecuador es un tema de vital importancia. El ejemplo del proyecto Pesillo-Imbabura, en donde la organización comunitaria fue fundamental para su ejecución, dio lugar a esta investigación. Reuniones de dirigentes, asambleas de usuarios, protestas, mingas, diálogo con distintos actores y con la cooperación fueron claves en el desarrollo del proyecto Pesillo: un ejemplo de cómo la unión y un objeto común son claves para tener resultados de desarrollo en territorios indígenas. Esta publicación recoge antecedentes históricos sobre las formas de acceso al agua hasta la creación de las Juntas de Administración de Agua Potable Comunitarias. Analiza tanto el derecho al agua como la organización comunitaria y, en Pesillo, encuentra un ejemplo que visibiliza la lucha por el agua a nivel nacional.', '["community water management","right to water","community organizations","indigenous territories","water access","minga","development cooperation","Ecuador"]', '10.7476/9789978105764', '9789978105764', 'https://books.scielo.org/id/6h39q', 'https://books.scielo.org/id/6h39q/pdf/perugachi-9789978105764.pdf', NULL, 'https://books.scielo.org/id/6h39q/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6hcrt', '6hcrt', 'A arte de enganar a natureza: contracepção, aborto e infanticídio no início do século XX', NULL, '["Fabíola Rohden"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A Arte de Enganar a Natureza é um ótimo título para um belo e revelador trabalho sobre os inúmeros e diversos embates morais, políticos, médicos e jurídicos em torno das ideias, representações e práticas de controle da natalidade no Brasil da primeira metade do século XX. Associando antropologia e história, conceitos e narrativas, múltiplas fontes e análise de casos, Fabíola Rohden nos oferece uma decisiva contribuição que se estende a vários campos disciplinares e temáticos: uma história da sexualidade e da reprodução no Brasil, uma história das relações de gênero e das políticas públicas voltadas para as mulheres e, também, uma página desconhecida da história da medicina brasileira.', '["contraception","abortion","infanticide","history of sexuality","history of reproduction","gender relations","women''s policy","history of medicine","early 20th century","Brazil"]', '10.7476/9786557081174', '9786557081174', 'https://books.scielo.org/id/6hcrt', 'https://books.scielo.org/id/6hcrt/pdf/rohden-9786557081174.pdf', NULL, 'https://books.scielo.org/id/6hcrt/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6hks3', '6hks3', 'Conhecimento, inovação e comunicação em serviços de saúde', NULL, '["Francisco José Aragão Pedroza Cunha","Cristiane Pinheiro Lázaro","Hernane Borges de Barros Pereira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Sensibilizar o leitor sobre a adoção e a assimilação de tecnologias de produção, circulação e acesso a informações gerenciais nos sistemas de atenção à saúde: este é o objetivo do livro. Três eixos temáticos compõem a obra: o primeiro aborda as políticas de informação, comunicação e inovação para os sistemas e redes de serviços em saúde; o segundo discute as perspectivas e limitações da política de inovação nos serviços de atenção e no Complexo Industrial da Saúde; e, por fim, o terceiro trata da comunicação organizacional e da difusão de inovações gerenciais em serviços de saúde. Os organizadores desta coletânea defendem que o habitus da interação precisa ser adotado, assimilado e incorporado por e entre sujeitos, organizações e instituições de Estado que promovem ciência, tecnologia, educação, comunicação e inovação no âmbito do SUS. Segundo eles, esforços nesse sentido são fundamentais para assegurar a saúde como um bem inalienável da sociedade.', '["health information systems","health communication","health innovation policy","organizational communication","diffusion of innovations","management information","health information policy","Unified Health System (SUS)"]', '10.7476/9788575415566', '9788575415566', 'https://books.scielo.org/id/6hks3', 'https://books.scielo.org/id/6hks3/pdf/cunha-9788575415566.pdf', NULL, 'https://books.scielo.org/id/6hks3/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6htpg', '6htpg', 'Adolpho Lutz - Adolpho Lutz e a entomologia médica no Brasil - v.2, Livro 3', NULL, '["Jaime Larry Benchimol","Magali Romero Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Integra a coleção: BENCHIMOL, Jaime Larry; SÁ, Magali Romero (Org.). Adolpho Lutz: obra completa. Rio de Janeiro: Fiocruz, [2004-200-?]. 4 v.', '["Adolpho Lutz","medical entomology","history of entomology","history of medicine","Brazil"]', '10.7476/9788575412299', '9788575412299', 'https://books.scielo.org/id/6htpg', 'https://books.scielo.org/id/6htpg/pdf/benchimol-9788575412299.pdf', NULL, 'https://books.scielo.org/id/6htpg/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6hxsz', '6hxsz', 'Pesquisas em educação e redes colaborativas', NULL, '["Lucena, Simone","Nascimento, Marilene B. da C.","Sorte, Paulo Boa"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-11-09', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Pesquisa em Educação e Redes Colaborativas apresenta-nos resultados de estudos em espaços de ensino e pesquisa, visando ao desenvolvimento de ações na perspectiva de contextos híbridos e multimodais de aprendizagens no campo da educação. Esta coletânea evidencia a (re)construção de conhecimento e saberes de todos/as os/as implicados/as, com vistas ao fortalecimento de intercâmbios entre pesquisadores/as de diferentes instituições e à melhoria da qualidade dos programas de pósgraduação. A leitura desta obra permite reflexões e compreensões sobre o campo da educação e das tecnologias digitais, sendo uma tessitura em movimentos pautados em processos inacabados que envolvem o ser, o fazer e o conhecer.', '["collaborative networks","educational research","hybrid learning","multimodal learning","knowledge construction","researcher exchange","graduate program quality","digital technologies in education","collaborative learning environments"]', '10.7476/9788574555638', '9788574555638', 'https://books.scielo.org/id/6hxsz', 'https://books.scielo.org/id/6hxsz/pdf/lucena-9788574555638.pdf', NULL, 'https://books.scielo.org/id/6hxsz/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != 