INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6jr3y', '6jr3y', 'Breve introdução à teoria das identidades polinomiais', NULL, '["Gabriel Santana Monteiro","Fernanda Gonçalves de Paula","Geraldo de Assis Junior"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'Breve introdução à teoria das identidades polinomiais vem suprir uma lacuna na literatura acadêmica em língua portuguesa sobre identidades polinomiais. O livro conduz o leitor pelos conceitos fundamentais desta área da álgebra, das raízes históricas da PI-Teoria até tópicos como álgebras graduadas e superálgebras. A obra nasce da experiência dos autores em projetos de iniciação científica e no ensino da disciplina Introdução às álgebras com identidades polinomiais, o que garante uma abordagem ao mesmo tempo didática e matematicamente sólida. Uma leitura indispensável para quem busca se aprofundar na PI-Teoria.', '["polynomial identities","PI-algebras","graded algebras","superalgebras"]', '10.7476/9788574556574', '9788574556437', 'https://books.scielo.org/id/6jr3y', 'https://books.scielo.org/id/6jr3y/pdf/monteiro-9788574556574.pdf', NULL, 'https://books.scielo.org/id/6jr3y/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6jsgp', '6jsgp', 'Dinâmicas e suportes para conhecer, reconhecer e integrar saberes em Comunicação e Educação', NULL, '["Eliana Nagamini","Ana Luísa Zaniboni Gomes"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os vinte artigos que compõem este quarto volume foram criteriosamente selecionados dentre vários trabalhos inscritos no XXIX Congresso Brasileiro de Ciências da Comunicação, em 2016. O Grupo de Pesquisa Comunicação e Educação integra a Divisão Temática Interfaces Comunicacionais, da Intercom, com estudos que apontam referenciais teóricos e metodológicos que permitem compreender os diálogos entre os processos comunicacionais e de ensino-aprendizagem existentes em espaços educativos formais, informais e não formais.', '["communication and education","knowledge integration","knowledge recognition","communication process","teaching-learning process","formal, non-formal and informal education"]', '10.7476/9788574554877', '9788574554877', 'https://books.scielo.org/id/6jsgp', 'https://books.scielo.org/id/6jsgp/pdf/nagamini-9788574554877.pdf', NULL, 'https://books.scielo.org/id/6jsgp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6k6kj', '6k6kj', 'Autoscopia: uma ação reflexiva sobre a prática docente', NULL, '["Nunes, Leila Regina d’Oliveira de Paula"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Analisa situações relacionadas à utilização, como tecnologia educacional, da autoscopia – metodologia que pressupõe o registro em imagem da atuação do professor para posterior análise. A técnica, além de favorecer a reflexão do docente sobre sua atuação, é considerada de grande utilidade na formação inicial e continuada de professores. Este livro reflete sobre a introdução da autoscopia na formação de professores e pais de crianças especiais, com destaque para educação de estudantes com o transtorno de espectro autista. Além disso, a obra proporciona uma revisão descritiva da literatura acerca da utilização de procedimentos de autoscopia na formação de professores. Com isso, a publicação apresenta uma abordagem reflexiva da educação, perspectiva que valoriza as variáveis situacionais e é centrada na investigação do fazer docente a partir de situações concretas de ensino no próprio contexto escolar.', '["teacher reflection","reflective practice","teacher professional development","continuing teacher education","autism spectrum disorder","special education","parents of children with special needs","educational technology","video recording of teaching"]', '10.7476/9786587949109', '9786587949109', 'https://books.scielo.org/id/6k6kj', 'https://books.scielo.org/id/6k6kj/pdf/nunes-9786587949109.pdf', NULL, 'https://books.scielo.org/id/6k6kj/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
